It remains an open question whether \textsc{2-Subcoloring} is NP-complete for unit disk graphs of height at most $1$. Resolving this question would definitively determine whether a $2$-approximation algorithm can be ruled out using a strip decomposition of the input unit disk graph.



\subsection{\textsc{$k$-Subcoloring} of co-comparability graphs}


The previous proof highlights the main idea for showing the hardness of \textsc{$k$-Subcoloring} on co-comparability graphs: using sequences of cliques to propagate coloring constraints. While the general approach is similar, the technical details differ. We reduce from the \textsc{No Rainbow Hypergraph 3-Coloring} problem, where the goal is to find a $3$-coloring of a $3$-uniform hypergraph such that no edge contains all three colors, and specific vertices must be assigned fixed colors.\newline

\fbox{
\begin{minipage}{0.9\linewidth}
\textsc{No Rainbow Hypergraph 3-Coloring :}

    \textbf{Input:} A $3$-uniform hypergraph $ H = (V, \mathcal{E}) $ with vertex set $ V $ and edge set $\mathcal{E}$ and $3$ sets $A_1,A_2,A_3 \subseteq V$.

    \textbf{Question:}  
    Is there a $3$-coloring $\mu : V \rightarrow \{1,2,3\}$ such that no hyperedge $ e \in \mathcal{E} $ is "rainbow" (i.e., no hyperedge contains all 3 colors) and such that for any $k \in \{1,2,3\}$ and $v\in A_k$, $\mu(v) = k$ ?
\end{minipage}}



\begin{theorem}[\cite{bulatov2006dichotomy}]
    \textsc{No Rainbow Hypergraph 3-Coloring} is NP-complete.
\end{theorem}
In \cite{zhuk2021no}, it was proven that the same problem without fixing some vertices with some color but just requiring that the $3$-coloring is surjective, is also NP-complete. We start with a straighforward lemma.

\begin{lemma}\label{lemma:K444}
    In any $3$-subcoloring of $K_{4,4,4}$, two vertices of two different parts have different colors, or equivalently, the three parts are all monochromatic with three different colors.
\end{lemma}

\begin{proof}
Let $A$, $B$, and $C$ be the three distinct parts of a $K_{4,4,4}$ graph, and let $\mu$ be a 3-subcoloring of this graph. Suppose, for contradiction, that there exist two vertices in different parts with the same color. \emph{W.l.o.g.}, assume $a \in A$ and $b \in B$ are both colored 3. Then, no other vertex $a' \in A \setminus \{a\}$ can have color 3; otherwise, the path $a b a'$ would form a monochromatic path of three vertices. Similarly, no other vertex $b' \in B \setminus \{b\}$ can have color 3.

Now, consider part $C$. If two different vertices $c, c' \in C$ are also colored 3, then the path $c a c'$ would also form a monochromatic path of three vertices. Consequently, after removing all vertices colored 3 from the graph, each part still contains at least three vertices. This configuration yields a 2-subcoloring of $K_{3,3,3}$, which cannot exist.
\end{proof}

\begin{theorem}
\textsc{3-Subcoloring} is NP-complete on co-comparability graphs.
\end{theorem}

\begin{proof}
We reduce from \textsc{No Rainbow Hypergraph 3-Coloring}. Let $H$ be a 3-uniform hypergraph with $n$ vertices $v_1, \dots, v_n$ and $m$ hyperedges. Let $A_1, A_2, A_3 \subseteq V(H)$. We construct a co-comparability graph $G$ as follows:

\begin{enumerate}
    \item For each $j = 1, \dots, m$, create two copies of $K_{n+6}$, denoted $C_j = \{c_{j,1}, c_{j,2}, \dots, c_{j,n+6}\}$ and $L_j = \{l_{j,1}, l_{j,2}, \dots, l_{j,n+6}\}$.

    \item For each $j = 1, \dots, m-1$, add edges to form a matching between $C_j$ and $L_j$, and similarly between $L_j$ and $C_{j+1}$. Specifically, add edges $\{(c_{j,i}, l_{j,i}) \mid 1 \leqslant i \leqslant n+6\}$ and $\{(l_{j,i}, c_{j+1,i}) \mid 1 \leqslant i \leqslant n+6\}$.

    \item For each $j = 1, \dots, m$, add a set of $n$ vertices $\{l_{j,i}' \mid 1 \leqslant i \leqslant n+6\}$ to $L_j$, where each $l_{j,i}'$ is a false twin of $l_{j,i} \in L_j$. More precisely, each $l_{j,i}'$ is adjacent to:
    \begin{itemize}
        \item all vertices in $L_j$ except $l_{j,i}$,
        \item the vertices $c_{j,i} \in C_j$ and, if $j < m$, $c_{j+1,i} \in C_{j+1}$.
    \end{itemize}
	Now, $L_j$ denote the set of vertices $\bigcup_{1\leqslant i\leqslant n} \{l_{j,i},l_{j,i}'\}$.
    \item For each hyperedge $e_j \in \mathcal{E}(H)$, introduce a new vertex $s_j$ (the "selector" vertex).
    \begin{itemize}
        \item Connect $s_j$ to all vertices in $L_j$, i.e., add edges $\{(s_j, u) \mid u \in L_j\}$.
        \item Additionally, connect $s_j$ to the vertices $\{c_{j,i} \mid v_i \in e_j\}$ in $C_j$ that correspond to the vertices in the hyperedge $e_j$.
    \end{itemize}

    \item Add a complete multipartite graph $K_{4,4,4}$ with parts $B_1$, $B_2$, and $B_3$. For each $k \in \{1,2,3\}$ and $v_i \in A_k$, add edges from $c_{1,i}$ to each vertex in $B_\ell$ for $\ell \in \{1,2,3\} \setminus \{k\}$. Additionally, add edges from $\{c_{1,n+1}, c_{1,n+2}\}$ to $B_2 \cup B_3$, from $\{c_{1,n+3}, c_{1,n+4}\}$ to $B_1 \cup B_3$, and from $\{c_{1,n+5}, c_{1,n+6}\}$ to $B_1 \cup B_2$.
\end{enumerate}

Observe that the size of $G$ is polynomial in the size of $H$, and we also confirm that $G$ is a co-comparability graph.

\begin{claim}
The graph $ G $ constructed above is a co-comparability graph.
\end{claim}

\begin{proof}
   In Figure~\ref{fig:StringRepresentation}, we illustrate a string representation for a simple example of $G$. Below, we provide a formal proof of the desired property. The class of co-comparability graphs is closed under the addition of false twins. Indeed, in any string representation of such a graph, a string can be replaced by two non-crossing strings following the original one, resulting in the creation of false twins. Therefore, to establish that $G$ is a co-comparability graph, it suffices to show that the graph obtained by contracting each pair of false twins in $G$ is a co-comparability graph.

    Let $G'$ be the graph obtained by contracting each pair of false twins $\{l_{j,i}, l_{j,i}'\}$ into a single vertex $t_{j,i}$ for all $1 \leq j \leq m$ and $1 \leq i \leq n+6$, and for each $k \in \{1,2,3\}$, contracting $B_k$ into a single vertex $b_k$. Define the $2m+1$ cliques of $G'$ as $D_0, \dots, D_{2m}$, where $D_0 = \{b_1, b_2, b_3\}$, $D_{2j-1} = C_j$, and $D_{2j} = \{t_{j,i} \mid i = 1, \dots, n+6\} \cup \{s_j\}$ for $1 \leq j \leq m$. Observe that every edge of $G'$ is either within one of these cliques or between two successive cliques.

    Now, consider the following order:
    \begin{align*}
        &b_1 \prec b_2 \prec b_3 \prec c_{1,1} \prec \dots \prec c_{1,n+6} \prec s_1 \prec t_{1,1} \prec \dots \prec t_{1,n+6} \prec \dots \\
        \prec &c_{m,1} \prec \dots \prec c_{m,n+6} \prec s_m \prec t_{m,1} \prec \dots \prec t_{m,n+6}.
    \end{align*}

    We will show that this ordering respects the non-edges of $G'$. Suppose, for some $u, v, w \in V(G')$, that $u \prec v$, $v \prec w$, $uv \notin E(G')$, and $vw \notin E(G')$. Assume, for contradiction, that $uw \in E(G')$. Then, $u$ and $w$ must either belong to the same clique or to two consecutive cliques. If $u, w \in D_j$ for some $j$, then by the construction of the order, $v \in D_j$, implying $uv \in E(G')$, a contradiction. If $u \in D_j$ and $w \in D_{j+1}$ for some $j$, then, by the ordering, $v$ must be in either $D_j$ or $D_{j+1}$. In the first case, $uv \in E(G')$, and in the second, $vw \in E(G')$, both contradicting the assumption. This confirms that $G'$ respects the co-comparability ordering.
\end{proof}

