\begin{theorem}\label{thm:DeltaInterval}
Any interval graph is a $\Delta$-disk graph. Moreover, there exists a $\Delta$-disk graph that is not an interval graph.
\end{theorem}

\begin{proof}
We say that two interval representations $ \{(\ell_v, r_v)\}_{v \in V(G)}$ and $ \{(\ell_v', r_v')\}_{v \in V(G)}$ of an interval graph $G$ \emph{coincide} if mapping $\ell_v$ to $\ell_v'$ and $r_v$ to $r_v'$ for all $v \in V(G)$ preserves the order on the real line.

\begin{claim}\label{Claim:CenteredDisks}
For any $t > 0$, let $D$ be the disk centered at $(t, t)$ with radius $t$. Let $a_1$ and $a_2$ be the smallest and largest values of $a > 0$ such that $(a, a) \in D$. Then,
\[
a_1 = \left( 1 - \frac{1}{\sqrt{2}} \right) t \quad \text{and} \quad a_2 = \left( 1 + \frac{1}{\sqrt{2}} \right) t
\]
\end{claim}

\begin{proof}
Notice that $a_1$ and $a_2$ are the positive solutions of the equations $t^2 = 2(t - a_1)^2$ and $t^2 = 2(a_2 - t)^2$, respectively.
\end{proof}

Let $G$ be an interval graph, and consider an interval representation $\{(\ell_v, r_v)\}_{v \in V(G)}$ of $G$ where intervals are sorted with respect to their right endpoints.
Define $G_i = G[\{v_1, \dots, v_i\}]$ for $1 \leqslant i \leqslant n$. We construct a disk representation of $G_i$ by induction:

\begin{itemize}
    \item Add a disk $D_1$ with center $(1, 1)$ and radius $1$ corresponding to $v_1$. Let $\ell_1'$ and $r_1'$ be the smallest and largest $t > 0$ such that $(t, t) \in D_1$.

    \item Assume that for $G_{i-1}$, a disk representation has been constructed such that:
    \begin{itemize}
        \item For any $1 \leqslant j < i$, the center of each disk $D_j$ is at $(t, t)$ for some $t > 0$, and each $D_j$ intersects both axes but not the origin.

        \item The set $\{(\ell_j', r_j')\}_{1 \leqslant j < i}$ forms an interval representation of $G_{i-1}$, coinciding with $\{(\ell_j, r_j)\}_{1 \leqslant j < i}$.
    \end{itemize}

    Now consider $G_i$ and distinguish two cases:
    \begin{itemize}
        \item If $\ell_i > r_{i-1}$, let $t_i = \frac{1}{1 - \frac{1}{\sqrt{2}}}(r_{i-1}' + 1)$ and let $D_i$ be the disk with center $(t_i, t_i)$ and radius $t_i$. By Claim~\ref{Claim:CenteredDisks}, the values $\ell_i' = r_{i-1}' + 1$ and $r_i' = \frac{\sqrt{2} + 1}{\sqrt{2} - 1}(r_{i-1}' + 1)$ are the smallest and largest real numbers $a > 0$ such that $(a, a) \in D_i$. This shows that $\{(\ell_j', r_j')\}_{1 \leqslant j \leqslant i}$ is an interval representation of $G_i$.

        \item If $\ell_i < r_{i-1}$, let $e_1, e_2 \in \{\ell_1, r_1, \dots, \ell_{i-1}, r_{i-1}\}$ be two events such that $e_1 < \ell_i < e_2$ and $|e_2 - e_1|$ is minimized. Let $e_1', e_2' \in \{\ell_1', r_1', \dots, \ell_{i-1}', r_{i-1}'\}$ be the values corresponding to $e_1$ and $e_2$ in the new interval representation of $G_{i-1}$. Choose $\ell_i' > 0$ such that $e_1' < \ell_i' < e_2'$, and set $t = \max\left( \frac{1}{1 - \frac{1}{\sqrt{2}}} \ell_i', r_{i-1}' \right)$. Define $D_i$ as the disk centered at $(t, t)$ with radius $R = \sqrt{2}(t - \ell_i')$. This ensures that:
        \begin{itemize}
            \item The smallest $a > 0$ such that $(a, a) \in D_i$ satisfies $2(t-a)^2 =R^2$, and thus is exactly~$\ell_i'$.
            \item The largest value $a > 0$ such that $(a, a) \in D_i$ satisfies $a > r_{i-1}'$, as $t > r_{i-1}'$. Set $r_{i}'$ to be this largest value.
        \end{itemize}
        Altogether, $\{(\ell_j', r_j')\}_{1 \leqslant j \leqslant i}$ forms an interval representation of $G_i$ which coincides with $\{(\ell_j, r_j)\}_{1 \leqslant j \leqslant i}$, and all disks $D_1, \dots, D_i$ intersect both axes but not the origin.
    \end{itemize}
\end{itemize}

At the end, we have $G_n = G$ with a disk representation that satisfies the properties of a $\Delta$-disk graph. Finally, note that $C_4$, the cycle on four vertices, is a $\Delta$-disk graph (see Figure~\ref{fig:C4DeltaDisk}) but not an interval graph. 

