\begin{theorem}\label{thm:Cocomp}
Any $\Delta$-disk graph $G$ is a co-comparability graph with respect to the following co-comparability order: for any two vertices $u, v \in V(G)$, define $u \prec v$ if and only if $x_u < x_v$, $y_u < y_v$, and $D_u \cap D_v = \emptyset$.
\end{theorem}

\begin{proof}
Observe that in a $\Delta$-disk graph $G$, if two disks $D_u$ and $D_v$ ($u, v \in V(G)$) do not intersect and $x_u < x_v$, then $y_u < y_v$. Indeed, suppose for contradiction that  $y_u \geqslant y_v$. In this case, both $D_u$ and $D_v$ intersect at the point $(x_u, y_v)$, since the radius of $D_u$ is at least $x_u$ and the radius of $D_v$ is at least $y_v$, contradicting the assumption that $D_u$ and $D_v$ are disjoint.
Finally the relation is indeed transitive:  if $u \prec v$ and $v \prec w$, then $u \prec w$ since $D_v$ separates $\mathbb{R}_+^2$.  
%We establish the relation $u \prec v$ as an order on non-edges, defined by $u \prec v$ if and only if $x_u < x_v$, $y_u < y_v$, and $D_u \cap D_v = \emptyset$. This relation is transitive; if $u \prec v$ and $v \prec w$, then $u \prec w$ since $D_v$ separates $\mathbb{R}_+^2$. Therefore, the defined order satisfies the conditions of a co-comparability graph.
\end{proof}


\subparagraph{Properties of $\Delta$-disk graphs.} We first establish some basic properties of $\Delta$-disk graphs that will be useful in our approximation algorithm. The following lemma, which will be applied frequently (often implicitly), states that if two disks in a $\Delta$-disk graph intersect, then their intersection must occur within the region $\Delta =  \mathbb{R}_+^2$. In other words, there cannot be a ``hidden'' intersection point located outside $\Delta$, e.g. at a point with a negative coordinates. This result follows directly from the geometry of the disks.

\begin{lemma}
Let $G$ be a $\Delta$-disk graph and let $uv \in E(G)$. Then, the disks $D_u$ and $D_v$ intersect within $\Delta$; that is, the intersection $D_u \cap D_v \cap \Delta$ is non-empty.
\end{lemma}

\begin{proof}
Observe that the line segment joining the centers of $D_u$ and $D_v$ lies entirely within $\Delta$. Since the disks intersect, at least one point on this segment must be in the intersection $D_u \cap D_v$, and this point also lies within $\Delta$.
\end{proof}


\begin{lemma}\label{lemma:BoundNonEdge}
Let $G$ be a $\Delta$-disk graph, and let $u, v \in V(G)$ such that $uv \notin E(G)$ and $d_u < d_v$. Then, $\min(x_v, y_v) \geqslant \max(x_u, y_u) + r_u$.
\end{lemma}

\begin{proof}
\emph{W.l.o.g.}, assume that $x_u \geq y_u$. We aim to show that if $\min(x_v, y_v) < x_u + r_u$, then $u$ and $v$ are adjacent in $G$. 

Since $d_u < d_v$, vertex $u$ precedes $v$ in the co-comparability ordering. Thus, by Theorem~\ref{thm:Cocomp}, we have $x_u < x_v$ and $y_u < y_v$. We now consider two cases:

\begin{itemize}
    \item If $x_v \leq x_u + r_u$. In this case, observe that both disks $D_u$ and $D_v$ intersect at the point $(x_v, y_u)$, making $u$ and $v$ adjacent in $G$, which contradicts the assumption that $uv \notin E(G)$.

    \item If $x_v > x_u + r_u$ but $y_v < x_u + r_u$. We show that $D_u$ and $D_v$ still intersect. We denote $C_u =(x_u,y_u)$ and $C_v=(x_v,y_v)$, and applying the triangle inequality gives:
    \[
    d(C_u, C_v) \leq (x_v - x_u) + (y_v - y_u) < (x_v - x_u) + (x_u + r_u - y_u).
    \]
    Since $x_v \leq r_v$ by assumption, it follows that $d(C_u, C_v) < r_u + r_v$, implying that $D_u$ and $D_v$ intersect, which again contradicts $uv \notin E(G)$.
\end{itemize}
Thus, we conclude that $\min(x_v, y_v) \geq \max(x_u, y_u) + r_u$.
\end{proof}




\begin{lemma}\label{lemma:Convexity}
Let $G$ be a $\Delta$-disk graph and $v\in V(G)$. If, for some $t\leqslant \min(x_v,y_v)$, $D_v\cap [0;t]^2$ is not empty, then $D_v$ intersects the point $(t,t)$.
\end{lemma}

\begin{proof}
Let $(x,y) \in D_v\cap [0;t]^2$. We notice that $x_v-x \geqslant x-t$ since $x\leqslant t$, and similarly $y_v-y\geqslant y-t$. It follows that $(x_v,y_v)$ is closer to $(t,t)$ than to $(x,y)$, and thus $D_v$ intersects $(t,t)$ as well. 
\end{proof}


