\begin{restatable}[\restateref{lem:quadrangle}]{lemma}{Quadrangle}
\label{lem:quadrangle}
Let $\langle G, w \rangle$ be an $n$-vertex edge-weighted graph consisting of:
\begin{itemize}
\item A $4$-cycle $\Box=abcd$.
\item A caterpillar $C_a$ with underyling path $P(C_a)$ starting at vertex $a \in \Box$.
\item A caterpillar $C_c$ with underyling path $P(C_c)$ starting at vertex $c \in \Box$.
\end{itemize}
Then, a PQ-layout $\Gamma$ of $\langle G, w \rangle$ with $\pqn(\Gamma)=1$ can be constructed in $\mathcal{O}(n \log n)$.
\end{restatable}

\begin{proof}[Proof Sketch]
	We arrange the cycle such that only the heaviest edge is co-active with the other three edges.
	We use \cref{lem:tree} for laying out the one caterpillar
	with designated leftmost vertex and we use \cref{lem:caterpillar}
	for laying out the other caterpillar with designated rightmost vertex.
	In the appendix, we argue that we can combine these three subgraphs,
	potentially adding some leaves later on, while still using only one priority queue.
\end{proof}

By \cref{lem:contraction}, if $G$ is a minor of a graph as described in \cref{lem:quadrangle}, then also $\pqn(G)=1$.

\begin{corollary}\label{cor:triangle}
 If $G$ consists of a triangle $\triangle = abc$ and two caterpillars $C_a$ and $C_b$ with underlying paths starting at vertex $a \in \triangle$ and $b \in \triangle$, respectively,
%  having $a$ and $b$ as degree-$1$ vertices of their underlying paths, respectively, 
 then $\pqn(G) = 1$.
\end{corollary}


Finally, we consider graphs that contain more than one cycle.
If we exclude disconnected graphs, there exist exactly two such graphs with priority queue number~1, the complete bipartite graph $K_{2,3}$ and the graph obtained from  $K_4$ by removing an edge.
We will later see that these are the only ones.

