\section{PQ-Layouts of Graphs with Bounded Pathwidth and Treewidth}\label{sec:results-kpq}

We present results for graphs of bounded pathwidth and bounded treewidth.
We assume familiarity with these concepts;
otherwise see \cref{app:pathwidth-treewidth} for formal definitions.

\begin{theorem}
    Let $G$ be a graph with pathwidth at most $p$. Then, $\pqn(G) \leq p+1$.
%    \todo{Reviewer~1: ``Is this bound tight?''}
\end{theorem}

\begin{proof}
    We may assume w.l.o.g.\ %without loss of generality
    that $G = (V,E)$ is edge-maximal of pathwidth $p$, i.e., $G$ is an interval graph with clique number $\omega(G) = p+1$~\cite{DBLP:journals/tcs/Bodlaender98}.
    Let $\{I_v = [a_v,b_v]\}_{v \in V}$ be an interval representation of $G$ with distinct interval endpoints.
    In particular $b_u \neq b_v$ for any $u \neq v \in V$.

    We take the ordering $v_1,\ldots,v_n$ of vertices given by their increasing right interval endpoints.
    That is, $b_{v_1} < \cdots < b_{v_n}$.
    Crucially, for any $i < j < k$ with $v_iv_k \in E$, also $v_jv_k \in E$.% is an edge in $G$.

    To define the partition of $E$ into $p+1$ priority queues $\mathcal{P}_1,\ldots,\mathcal{P}_{p+1}$, we consider a proper vertex coloring of $G$ with $\chi(G) = \omega(G) = p+1$ colors.
    This exists, as $G$ is an interval graph.
    Now for $c = 1,\ldots,p+1$ let $\mathcal{P}_c$ be the set of all edges in $G$ whose right endpoint in the vertex ordering has color $c$.
    In fact, each $\mathcal{P}_c$ contains none of the forbidden configurations in \cref{fi:forbidden-configurations}, and hence is a priority queue independent of the edge-weights, since in each forbidden configuration in \cref{fi:forbidden-configurations} there would be an edge in $G$ between the right endpoints $v_r$ and $v_{r'}$ of the two edges $e$ and $e'$ forming the forbidden configuration.
	But this would imply different colors for $v_r$ and $v_{r'}$ and therefore different priority queues for $e$ and $e'$.
\end{proof}

We remark that \cref{cor:k_n} implies that there are graphs with pathwidth $p$ and priority queue number at least $\left\lfloor \frac{3-\sqrt{5}}{8}(p+1)\right\rfloor$ as $K_{p+1}$ has pathwidth $p$.

Next, we shall construct for every integer $p \geq 1$ a graph $G = G_p$ of treewidth~$2$ together with edge weights $w$ so that every vertex ordering $\sigma$ of $G$ contains a $p$-inversion.
If
%Recall that if for a particular edge-weighting $w$ of $G$,
every vertex ordering of $\langle G,w \rangle$ contains a $p$-inversion, then $\pqn(G,w) \geq p$ and hence $\pqn(G) \geq p$.

\begin{restatable}[\restateref{thm:treewidth-2}]{theorem}{TreewidthTwo}
	\label{thm:treewidth-2}
    For every $p$ there is a graph $G_p$ of treewidth~$2$ and $\pqn(G_p) \geq p$.
\end{restatable}

\begin{proof}[Proof Sketch]
    Let $p \geq 1$ be a fixed integer.
    Our desired graph $G_p$ will be a \emph{rooted $2$-tree}, i.e., an edge-maximal graph of treewidth~$2$ with designated root edge, which are defined inductively through the following construction sequence:
    \begin{itemize}
        \item A single edge $e^* = v'v''$ is a $2$-tree rooted at $e^*$.
        \item If $G$ is a $2$-tree rooted at $e^*$ and $e = uv$ is any edge of $G$, then adding a new vertex $t$ with neighbors $u$ and $v$ is again a $2$-tree rooted at $e^*$.
        We say that $t$ is \emph{stacked onto~$uv$}.
%             In this case we say that $t$ is \emph{stacked onto the edge $uv$}, and vertices $u$ and $v$ are called the \emph{parents} of $t$.
    \end{itemize} 

    We define a vertex ordering $\sigma$ of a $2$-tree rooted at $e^* = v'v''$ to be \emph{left-growing} if no vertex (different from $v'$, $v''$) appears to the right of both its parents.
    First we show that it is enough to force a $p$-inversion (and hence $\pqn(G) \geq p$) in every left-growing vertex ordering.

    \begin{restatable}[\restateref{claim:wlog-left-growing}]{claim}{LeftGrowing}
    	\label{claim:wlog-left-growing}
        If $\langle G,w \rangle$ is an edge-weighted rooted $2$-tree so that every left-growing vertex ordering contains a $p$-inversion, then there exists an edge-weighted rooted $2$-tree $\langle \tilde{G},\tilde{w} \rangle$ so that every vertex ordering contains a $p$-inversion.
    \end{restatable}

    \begin{claimproof}[Proof Sketch]
        Intuitively, whenever in the construction sequence of $G$ a vertex $t$ is stacked onto an edge $uv$, in $\tilde{G}$ we instead stack $p^2$ ``copies'' of $t$ called $t_1,\ldots,t_{p^2}$ onto $uv$ (treating each $t_i$ like $t$ henceforth).
        The weights $\tilde{w}(ut_i)$ and $\tilde{w}(vt_i)$, $i=1,\ldots,p^2$, are chosen very close to $w(ut)$ and $w(vt)$ but increasing with $i$ for $ut_i$ and decreasing with $i$ for $vt_i$.
        This way, if all $p^2$ copies of $t$ lie right of $u$ and $v$, we get a $p$-inversion among the $ut_i$'s or $vt_i$'s.
    \end{claimproof}

	\begin{figure}[t]
		\centering
		\includegraphics{2-trees}
		\caption{Illustration of the $2$-tree $H_k$ with edge-weighting $w_k$, for $k\geq2$.}
		\label{fig:2-trees}
	\end{figure}

    We then construct a sequence $\langle H_1,w_1 \rangle, \langle H_2,w_2 \rangle, \ldots$ of edge-weighted rooted $2$-trees, so that for every $k$, every left-growing vertex ordering of $\langle H_k,w_k \rangle$ contains a $k$-inversion.
    The construction of $\langle H_k,w_k \rangle$ is recursive, starting with $\langle H_1,w_1 \rangle$ being just a single edge of any weight.
    For $k \geq 2$, we start with $d=k^2$ vertices $a_1,\ldots,a_d$ stacked onto the root edge $e^* = v'v''$, and stacking a vertex $b'_i$ onto each $v'a_i$, as well as a vertex $b''_i$ onto $v''a_i$ for $i=1,\ldots,d$.
    All these edges have weight~$0$.
    Then, each $b'_ia_i$ and $b''_ia_i$ is used as the base edge of two separate copies of $\langle H_{k-1},w_{k-1} \rangle$, where however the edge-weights $w_{k-1}$ of each copy are scaled and shifted to be in a specific half-open interval $[x,y) \subset \mathbb{R}$ depending on the current base edge ($b'_ia_i$ or $b''_ia_i$).
    See \cref{fig:2-trees} for an illustration.

    By induction, there is a $(k-1)$-inversion in each such copy of $H_{k-1}$.
    Using the pigeon-hole principle, and the Erd\H{o}s--Szekeres theorem, we then identify an edge $a_iv'$ (or $a_iv''$) which forms a $k$-inversion either together with $(k-1)$-inversion of one copy of $H_{k-1}$, or with $k-1$ edges, each from the $(k-1)$-inversion of a different copy of $H_{k-1}$.

    To finish the proof, it is then enough to take $\langle H_p,w_p \rangle$ as constructed above, and then apply \cref{claim:wlog-left-growing} to obtain the desired edge-weighted $2$-tree $\langle G_p,w_p \rangle$ with $\pqn(G_p,w_p) \geq p$.
\end{proof}

As graphs of treewidth $2$ are always planar graphs, we conclude with the following result that contrasts similar results for the queue and stack number~\cite{DBLP:journals/jacm/DujmovicJMMUW20,DBLP:journals/jcss/Yannakakis89}:

\begin{corollary}
The priority queue number of planar graphs is unbounded. In particular, there is a planar graph $G$ with $n$ vertices and $\pqn(G) \geq \log_4 n$.
\end{corollary}

\begin{proof}
We observe that $H_k$ in the proof of \cref{thm:treewidth-2} contains $4$ copies of $H_{k-1}$ while $H_1$ contains $2$ vertices. Thus, there are at least $4^p$ vertices in $G := H_p$, which has treewidth~$p$.
\end{proof}


