\begin{proof}
    Let $G=K_{2,3}$ and consult \cref{fi:k23} for an illustration.
    Let $\{u_1, u_2\}$ be the vertex partition with vertices of degree 3 and let $\{v_1, v_2, v_3\}$ be the vertex partition with vertices of degree 2.
    Let $w$ be any given edge-weight function and denote by $e_1$ the heaviest edge of $\langle G, w \rangle$ and by $e_2$ the second heaviest edge.
    We distinguish three main cases and, for each of them, we describe how to construct a PQ-layout $\Gamma$ such that $\pqn(\Gamma)=1$.

	\begin{itemize}
        \item {\bf Case~1: $e_1$ and $e_2$ are disjoint.} Refer to \cref{fi:k23-1}.
        We may assume that $e_1=u_1v_1$ and $e_2=u_2v_3$, and define the vertex ordering as $v_3 \prec u_1 \prec v_2 \prec u_2 \prec v_1$. Since $e_1$ and $e_2$ are the two heaviest edges, there are neither forbidden nestings nor forbidden pseudo-nestings in $\Gamma$. Also, the only two crossing edges are $e_1$ and $e_2$, and $w(e_2) \leq w(e_1)$. Since $e_2$ is pulled from the priority queue before $e_1$, there is no forbidden crossing configuration.
		\item {\bf Case~2: $e_1$ and $e_2$ share a degree-2 vertex.} Let $e_3$ be the third heaviest edge of $\langle G, w \rangle$. We consider two further subcases:
		\begin{itemize}
			\item {\bf Case~2.1: $e_3$ shares a vertex with $e_1$.} Refer to \cref{fi:k23-2-1}. Assume, w.l.o.g., that $e_1=u_1v_3$, $e_2=u_2v_3$, and $e_3=u_1v_1$. The linear ordering of $\Gamma$ is set as $v_1 \prec u_2 \prec v_2 \prec u_1 \prec v_3$. As for Case~1, there are no forbidden (pseudo-)nesting configurations. Also, the only two crossing edges are $e_2$ and $e_3$, and $w(e_3) \leq w(e_2)$. Since $e_3$ is pulled from the queue before $e_2$, there is no forbidden crossing~configuration.
			\item {\bf Case~2.2: $e_3$ shares a vertex with $e_2$.} Refer to \cref{fi:k23-2-2}.  Assume, w.l.o.g., that $e_1=u_1v_3$, $e_2=u_2v_3$, and $e_3=u_2v_1$. We define the linear ordering of $\Gamma$ as $v_1 \prec u_1 \prec v_2 \prec u_2 \prec v_3$. The argument is similar to the previous case.
		\end{itemize}
		\item {\bf Case~3: $e_1$ and $e_2$ share a degree-3 vertex.} Refer to \cref{fi:k23-3}. Assume, w.l.o.g., that $e_1=u_1v_3$ and $e_2=u_1v_1$. We define the linear ordering of $\Gamma$ as $v_3 \prec v_1 \prec u_2 \prec v_2 \prec u_1$. As in the previous cases, for the choice of $e_1$ and $e_2$, there are no forbidden nesting or pseudo-nesting configurations. Also, the only two crossing edges are $e_2$ and the edge $v_3u_2$; since $v_3u_2$ is pulled before $e_2$ from the priority queue, and since $w(v_3u_2) \le w(e_2)$, there is no forbidden crossing configuration. \qedhere
	\end{itemize}
\end{proof}


\LastEdgeHeavy*
\label{le:1pq-cycle-last-vertex*}

\begin{proof}
    Suppose for a contradiction that there is a PQ-layout~$\Gamma$ of $\langle C, w \rangle$ with $\pqn(\Gamma) = 1$ where the last vertex is incident to two edges that both do not have the maximum weight.
    Let $e = uv$ be an edge of maximum weight with $u \prec v$.
    (If there are multiple edges with maximum weight,
    pick $e$ such that $v$ is rightmost among all right endpoints
    of those heaviest edges.)
    We claim that there is an edge $e' = xy$ that is co-active with $e$
    and $v \prec y$ resulting in a forbidden configuration since $w(e) > w(e')$.
    Let $a$ be the leftmost vertex and $z$ be rightmost vertex of~$\Gamma$.
    There are two vertex-disjoint paths between $a$ and $z$.
    Only one of these paths can contain $v$, while the other needs to bridge $v$~-- this implies that $e'$ exists.
\end{proof}


\ForbiddenMinors*
\label{le:forbidden-minors-are-not-1pq*}

\begin{proof}[Proof of Cases $\mathcal{F}_4$--$\mathcal{F}_8$]
It remains to analyze $\mathcal{F}_4$--$\mathcal{F}_8$.
For an illustration, refer to \cref{fig:minors}.

\begin{description}
	\item[$\mathcal{F}_4$, $\mathcal{F}_5$]:
	By \cref{le:1pq-cycle-last-vertex} and symmetry, we may assume that $a,b \prec c$.		
	Since each edge \emph{not} in $\triangle abc$ has a weight strictly between $w(ab) = w(ac)$ and $w(bc)$, no such edge can start weakly left of $\min\{a,b\}$ and end strictly right of $\min\{a,b\}$.
	In particular, it follows that $d \prec a$ and, since also $w(ed) < w(ad)$, that $e \prec d$.
	In summary, we have $e \prec d \prec a \prec c$ and $b \prec c$.

	Now for $\mathcal{F}_4$ it follows that the right endpoint of edge $fg$ must be left of $e$.
	But then edge $ed$ nests below $af$; a contradiction, as $w(ed) > w(af)$.

	For $\mathcal{F}_5$, first note that if $a \prec b$, then either edge $bf$ ends below $ac$ (if $f \prec c$) or edge $bc$ ends below $bf$ (if $c \prec f$); either is not allowed.
	So we have $b \prec a$, and hence $f \prec a$, as argued in the beginning.
	But now either edge $bf$ ends below $ad$ (if $d \prec b$) or edge $ed$ ends below $ab$ (if $b \prec d$); either is not allowed.

