\title{Quantifying Bounded Rationality:\\
Formal Verification of Simon's Satisficing Through Flexible Stochastic Dominance}
\author{Jingyuan Li\footnote{Lingnan University, Department of Operations and Risk Management, Hong Kong SAR, China. Corresponding author. E-mail address:
jingyuanli@ln.edu.hk.}\and Jinali Wang\footnote{Nanjing University of Aeronautics and Astronautics, College of Economics and Management, China.} \and Lin Zhou\footnote{Lingnan University, Institute of Insurance and Risk Management, Hong Kong SAR, China.}}
