\section{Appendix: Lean 4 Implementations and Proof Sketches}\label{sec:appendix}

Throughout this appendix, Lean 4 code snippets are illustrative of the formal definitions and theorems discussed in the main text. Proof sketches aim to convey the logical structure of the formal proofs while abstracting away some implementation details.


\subsection{Definition \ref{def:robust_riemann_stieltjes_integral}: Robust Riemann-Stieltjes Integral}
\begin{lstlisting}[caption={Robust Riemann-Stieltjes Integral}, label={}]
noncomputable def robustRiemannStieltjesIntegral (u : R $\rightarrow$ R) (F : R $\rightarrow$ R) (a b : R) ($\varepsilon$ : R) : R :=
  -- Check if u is exactly an indicator function $1_{(x_0, \infty)}$ for some $x_0\in$  (a, b)
  let P_exact : Prop := $\exists$ $x_0\in$ Ioo a b, $\forall$ $x$ $\in$ Icc a b, u $x$ = if $x > x_0$ then 1 else 0

  -- Check if u is $\varepsilon$-close to an indicator function $1_{(x_0, \infty)}$ for some $x_0\in$ (a, b)
  let P_approx : Prop := $\exists$ $x_0\in$ Ioo a b, $\forall$ $x$ $\in$ Icc a b, |u $x$ - (if $x > x_0$ then 1 else 0)| $\leq\varepsilon$

  haveI : Decidable P_exact := Classical.propDecidable P_exact
  haveI : Decidable P_approx := Classical.propDecidable P_approx

  if h_exact : P_exact then
    -- Exact case: extract $x_0$ and return 1 - F $x_0$
    let $x_0$ := Classical.choose h_exact
    1 - F $x_0$
  else if h_approx : P_approx $\wedge$ $\varepsilon$ > 0 then
    -- Approximate case: extract $x_0$ and apply tolerance-adjusted computation
    let $x_0$ := Classical.choose h_approx.1
    -- Scale $\varepsilon$ by (b - a) to account for the interval length
    let tolerance_adjustment := $\varepsilon$ * (b - a)
    (1 - F $x_0$) + tolerance_adjustment
  else
    0 -- Fallback case
\end{lstlisting}

This formalization introduces several key Lean 4 constructs:

\begin{leanfeature}[Dependent Propositions]
The definition uses Lean's \texttt{Prop} type to encode mathematical propositions like \texttt{P\_{\text{exact}}} and \texttt{P\_{\text{approx}}}. These propositions depend on the function $u$ and parameters $a$, $b$, and $\varepsilon$, creating a formal representation of Simon's aspiration level concept.
\end{leanfeature}

\begin{leanfeature}[Classical Choice]
The \texttt{Classical.choose} operation extracts a witness from an existential proposition. When we have a proof that $\exists x_0 \in (a,b)$ satisfying some property, \texttt{Classical.choose} gives us the specific $x_0$ value—analogous to how Simon's decision-makers identify their aspiration levels.
\end{leanfeature}

\begin{remark}
The \texttt{noncomputable} designation signals that this definition may use classical reasoning principles that don't necessarily have computational content. In particular, determining whether a function exactly or approximately matches an indicator function may not be algorithmically decidable—mirroring Simon's observation that humans often cannot articulate their exact decision thresholds.
\end{remark}

\subsection{Lemma \ref{lem:uniqueness_x0_tolerance}: Uniqueness of Indicator Reference Point}
The Lean 4 proof of this lemma uses contradiction and careful case analysis:

\begin{lstlisting}[caption={Uniqueness of Indicator Reference Point}, label={}]
lemma uniqueness_of_indicator_$x_0$_tolerance {a b $x_1$ $x_2$ : R} {u : R $\rightarrow$ R} {$\varepsilon$ : R}
    (hab : a < b) (h$\varepsilon$_pos : $\varepsilon$ > 0)
    (h$x_1$_mem : $x_1$ $\in$ Ioo a b) (h$x_2$_mem : $x_2\in$ Ioo a b)
    (h_u_close_$x_1$ : $\forall$ $x\in$ Icc a b, |u $x$ - (if $x > x_1$ then (1 : R) else (0 : R))| $\leq\varepsilon$)
    (h_u_close_$x_2$ : $\forall$ $x\in$ Icc a b, |u $x$ - (if $x > x_2$ then (1 : R) else (0 : R))| $\leq\varepsilon$)
    (h$\varepsilon$_small : $\varepsilon$ < (1 : R) / 2) :
    $x_1$ = $x_2$ := by
  by_contra h_neq
  have h_lt_or_gt : $x_1$ < $x_2$ $\vee$ $x_2$ < $x_1$ := Ne.lt_or_lt h_neq
  rcases h_lt_or_gt with h_lt | h_gt
  $\cdot$ let z := ($x_1$ + $x_2$) / 2
    -- ... (details of proof for $x_1$ < $x_2$)
    linarith [this, h$\varepsilon$_small]
  $\cdot$ let z := ($x_1$ + $x_2$) / 2
    -- ... (details of proof for $x_2$ < $x_1$)
    linarith [this, h$\varepsilon$_small]
\end{lstlisting}

\begin{proof}
We proceed by contradiction. Assuming $x_1 \neq x_2$, we have either $x_1 < x_2$ or $x_2 < x_1$.

Case 1: If $x_1 < x_2$, let $z = (x_1 + x_2)/2$. Then:
\begin{align}
\indicatorIf{z}{x_1} &= 1 \text{ (since $z > x_1$)} \\
\indicatorIf{z}{x_2} &= 0 \text{ (since $z < x_2$)}
\end{align}

By the triangle inequality:
\begin{align}
1 = |1 - 0| &= |(\indicatorIf{z}{x_1} - u(z)) + (u(z) - \indicatorIf{z}{x_2})| \\
&\leq |u(z) - \indicatorIf{z}{x_1}| + |u(z) - \indicatorIf{z}{x_2}| \\
&\leq \varepsilon + \varepsilon = 2\varepsilon
\end{align}

This implies $1 \leq 2\varepsilon$, so $\varepsilon \geq 1/2$, contradicting our assumption that $\varepsilon < 1/2$.

Case 2: If $x_2 < x_1$, a symmetric argument leads to the same contradiction.

Therefore, $x_1 = x_2$.
\end{proof}

\begin{leanfeature}[Proof Structure in Lean 4]
This proof demonstrates Lean's structured proof style using tactic blocks:
\begin{itemize}
    \item \texttt{by\_contra h\_neq}: Sets up a proof by contradiction with hypothesis $x_1 \neq x_2$
    \item \texttt{rcases h\_lt\_or\_gt with h\_lt | h\_gt}: Pattern matches on disjunctions, creating separate cases
    \item Bullet notation (\texttt{·}) organizes the proof into separate cases
    \item \texttt{linarith} automatically proves linear arithmetic goals, handling complex inequalities
    \item \texttt{simp} simplifies expressions like \texttt{if true then 1 else 0} to \texttt{1}
\end{itemize}

The proof explicitly constructs the midpoint $z$ and develops the contradiction through careful manipulation of inequalities, making the mathematical argument fully precise and machine-checkable—a level of rigor that Simon advocated for in scientific models of behavior.
\end{leanfeature}

\begin{leanfeature}[Uniqueness and Classical Choice]
The uniqueness lemma addresses a subtle but crucial aspect of constructive mathematics in Lean 4. The \texttt{Classical.choose} operator extracts a witness from an existential statement, but doesn't guarantee which witness it selects when multiple possibilities exist. By proving uniqueness of $x_0$, we ensure that regardless of how \texttt{Classical.choose} is implemented, it will always return the same threshold value—a property essential for consistency in economic modeling.
\end{leanfeature}

\subsection{Lemma \ref{lem:integral_indicator_tolerance}: Integral Value for Approximate Indicators}
The formalization of this result illustrates how Lean 4 handles complex function definitions:
\begin{lstlisting}[caption={Integral Value for Approximate Indicators}, label={}]
lemma integral_for_indicator_tolerance {a b : R} (hab : a < b) {u : R $\rightarrow$ R} {F : R $\rightarrow$ R}
    {$x_0$ : R} {$\varepsilon$ : R} (h$\varepsilon$_pos : $\varepsilon$ > 0) (h$\varepsilon$_small : $\varepsilon$ < 1/2)
    (h$x_0$_mem : $x_0\in$ Ioo a b)
    (h_u_close : $\forall$ x $\in$ Icc a b, |u $x$ - (if $x > x_0$ then (1 : R) else (0 : R))| $\leq$ $\varepsilon$)
    (h_not_exact : $\neg$($\exists$ $x_0$' $\in$ Ioo a b, $\forall$ $x \in$ Icc a b, u $x$ = if $x > x_0$' then 1 else 0)) :
    robustRiemannStieltjesIntegral u F a b $\varepsilon$ =
    (1 - F $x_0$) + $\varepsilon$ * (b - a) := by
  have h_u_is_P_approx : $\exists$ $x_0$' $\in$ Ioo a b, $\forall$ $x \in$ Icc a b, |u $x$ - (if $x > x_0$' then 1 else 0)| $\leq$ $\varepsilon$ := by
    exact <$x_0$, h$x_0$_mem, h_u_close>
  dsimp [robustRiemannStieltjesIntegral]
  rw [dif_neg h_not_exact]
  rw [dif_pos <h_u_is_P_approx, h$\varepsilon$_pos>]
  have h_$x_0$_eq : Classical.choose h_u_is_P_approx = $x_0$ := by
    let $x_0$' := Classical.choose h_u_is_P_approx
    have h_spec' : $x_0$' $\in$ Ioo a b $\wedge$ $\forall$ ($x$ : R), $x \in$ Icc a b $\rightarrow$ |u $x$ - (if $x > x_0$' then 1 else 0)| $\leq$ $\varepsilon$:=
      Classical.choose_spec h_u_is_P_approx
    exact uniqueness_of_indicator_$x_0$_tolerance hab h$\varepsilon$_pos h_spec'.1 h$x_0$_mem h_spec'.2 h_u_close h$\varepsilon$_small
  rw [h_$x_0$_eq]
\end{lstlisting}
\begin{proof}
From Definition \ref{def:robust_riemann_stieltjes_integral}, since $u$ is not exactly an indicator function but is $\varepsilon$-close to one, and $\varepsilon > 0$, the integral falls into the second case of the definition. The uniqueness of $x_0$ is guaranteed by Lemma \ref{lem:uniqueness_x0_tolerance}.
\end{proof}

\begin{leanfeature}[Working with Definitions and Rewriting]
This proof showcases key techniques for working with complex definitions:
\begin{itemize}
    \item \texttt{dsimp [robustRiemannStieltjesIntegral]}: Unfolds the definition to expose its case structure
    \item \texttt{rw [dif\_neg h\_not\_exact]}: Rewrites using the fact that \texttt{P\_exact} is false
    \item \texttt{rw [dif\_pos ⟨h\_u\_is\_P\_approx, h$\varepsilon$\_pos⟩]}: Rewrites using the fact that \texttt{P\_approx $\land$ $\varepsilon > 0$} is true
    \item Handling of \texttt{Classical.choose}: The proof ensures that the point chosen by Lean's choice operator is indeed equal to our given $x_0$, using the uniqueness lemma
\end{itemize}

This demonstrates how Lean 4 handles the gap between non-constructive existence proofs and concrete computational values, a subtlety often glossed over in traditional mathematics.
\end{leanfeature}

Our formalization reveals subtleties that might be overlooked in traditional mathematical treatments. For instance, the uniqueness of the reference point $x_0$ is essential for ensuring that the robust Riemann-Stieltjes integral is well-defined. The Lean proof forces us to explicitly handle this issue, strengthening the theoretical foundation.

\subsection{Theorem \ref{thm:tfsd_iff_utility}: FFSD Equivalence to Expected Utility}

The Lean 4 implementation encodes Definition \ref{def:tolerance_fsd} directly as a proposition:

\begin{lstlisting}
def Flexible_FSD (F G : R $\rightarrow$ R) (a b $\varepsilon$ : R) : Prop :=
  ($\forall$ $x$ $\in$ Icc a b, F $x$ $\leq$ G $x$ + $\varepsilon$) $\wedge$
  F a = 0 $\wedge$
  G a = 0 $\wedge$
  F b = 1 $\wedge$
  G b = 1
\end{lstlisting}

The proof in Lean 4 demonstrates how formal verification can capture complex economic relationships:

\begin{lstlisting}[caption={FFSD Equivalence to Expected Utility}, label={}]
theorem Flexible_FSD_iff_integral_indicator_ge (F G : R $\rightarrow$ R) (a b $\varepsilon$ $\varepsilon_1$ $\varepsilon_2$ : R)
  (hab : a < b) (h$\varepsilon$_pos : $\varepsilon$ > 0) (h$\varepsilon$_small : $\varepsilon$ < 1/2)
  (h$\varepsilon_1$_pos : $\varepsilon_1$ > 0) (h$\varepsilon_1$_small : $\varepsilon_1$ < 1/2)
  (h$\varepsilon_2$_pos : $\varepsilon_2$ > 0) (h$\varepsilon_2$_small : $\varepsilon_2$ < 1/2)
  (hFa : F a = 0) (hGa : G a = 0) (hFb : F b = 1) (hGb : G b = 1)
  (h$\varepsilon$_eq : $\varepsilon$ = ($\varepsilon_1$ - $\varepsilon_2$) * (b - a)) :
  Flexible_FSD F G a b $\varepsilon$ $\leftrightarrow$
  ($\forall$ $x_0$ $\in$ Ioo a b, $\forall$ u : R $\rightarrow$ R,
    ($\forall$ $x$ $\in$ Icc a b, |u $x$ - (if $x > x_0$ then (1 : R) else (0 : R))| $\leq$ $\varepsilon_2$) $\rightarrow$
    ($\neg$($\exists$ $x_0$' $\in$ Ioo a b, $\forall$ $x$ $\in$ Icc a b, u $x$ = if $x > x_0$' then 1 else 0)) $\rightarrow$
    robustRiemannStieltjesIntegral u F a b $\varepsilon_1$ $\geq$
    robustRiemannStieltjesIntegral u G a b $\varepsilon_2$) := by
  constructor
  $\cdot$ intro h_tolerance_dominance
    -- ... (Proof of forward direction)
    linarith [h_dom $x_0$ (Ioo_subset_Icc_self h$x_0$_mem), h$\varepsilon$_eq]
  $\cdot$ intro h_integral_indicator
    constructor
    $\cdot$ intro $x_0$ h$x_0$_mem_Icc
      -- ... (Proof of backward direction main part)
      rw [h$\varepsilon$_eq]
      linarith [h_integral_indicator]
    $\cdot$ exact <hFa, hGa, hFb, hGb>
\end{lstlisting}

\begin{leanfeature}[Bidirectional Proof Structure]
This theorem demonstrates a bidirectional proof strategy in Lean 4:
\begin{itemize}
    \item \texttt{constructor} splits the iff ($\leftrightarrow$) goal into two implications
    \item In the forward direction ($\Rightarrow$), we assume FFSD and prove the integral inequality
    \item In the backward direction ($\Leftarrow$), we assume the integral inequality and prove FFSD
    \item The \texttt{calc} block in the forward direction builds an equational proof with explicit justifications
    \item The construction of a specific utility function in the backward direction demonstrates how to create mathematical objects that satisfy precise properties
\end{itemize}
This structured approach makes the logical flow of the proof explicit and verifiable.
\end{leanfeature}

\begin{proof}
We present a detailed mathematical proof that complements the Lean 4 formalization.

$(\Rightarrow)$ Assume $F \succeq_{\text{FFSD},\varepsilon} G$. Let $u$ be a function that is $\varepsilon_2$-close to an indicator function with reference point $x_0 \in (a,b)$ but is not exactly an indicator function.

Note that since $\varepsilon_2 < \varepsilon_1$, the function $u$ is also $\varepsilon_1$-close to the same indicator function. By Lemma \ref{lem:integral_indicator_tolerance}:

\begin{align}
\RSI(u, F, a, b, \varepsilon_1) &= (1 - F(x_0)) + \varepsilon_1 \cdot (b - a) \\
\RSI(u, G, a, b, \varepsilon_2) &= (1 - G(x_0)) + \varepsilon_2 \cdot (b - a)
\end{align}

For the inequality $\RSI(u, F, a, b, \varepsilon_1) \geq \RSI(u, G, a, b, \varepsilon_2)$ to hold, we need:
\begin{align}
(1 - F(x_0)) + \varepsilon_1 \cdot (b - a) &\geq (1 - G(x_0)) + \varepsilon_2 \cdot (b - a) \\
\Rightarrow 1 - F(x_0) + \varepsilon_1 \cdot (b - a) &\geq 1 - G(x_0) + \varepsilon_2 \cdot (b - a) \\
\Rightarrow -F(x_0) + \varepsilon_1 \cdot (b - a) &\geq -G(x_0) + \varepsilon_2 \cdot (b - a) \\
\Rightarrow -F(x_0) + G(x_0) &\geq (\varepsilon_2 - \varepsilon_1) \cdot (b - a) \\
\Rightarrow G(x_0) - F(x_0) &\geq (\varepsilon_2 - \varepsilon_1) \cdot (b - a) \\
\Rightarrow F(x_0) - G(x_0) &\leq (\varepsilon_1 - \varepsilon_2) \cdot (b - a) \\
\Rightarrow F(x_0) &\leq G(x_0) + \varepsilon
\end{align}

The last inequality holds by the FFSD condition, since $x_0 \in (a,b) \subset [a,b]$ and $\varepsilon = (\varepsilon_1 - \varepsilon_2) \cdot (b - a)$.

$(\Leftarrow)$ Assume the expected utility inequality holds for all appropriate functions $u$. We need to show $F \succeq_{\text{FFSD},\varepsilon} G$, which requires proving that $F(x) \leq G(x) + \varepsilon$ for all $x \in [a,b]$.

The boundary cases ($x=a$ and $x=b$) follow from the given conditions $F(a)=G(a)=0$ and $F(b)=G(b)=1$.

For $x_0 \in (a,b)$, we construct a specific function:
\[
u(x) = 
\begin{cases}
1 - \varepsilon_2/2 & \text{if } x > x_0 \\
\varepsilon_2/2 & \text{if } x \leq x_0
\end{cases}
\]

This function $u$ satisfies:
\begin{itemize}
    \item $\forall x \in [a,b]$, $\abs{u(x) - \indicatorIf{x}{x_0}} = \varepsilon_2/2 \leq \varepsilon_2$
    \item It is not an exact indicator function, since its values are $\varepsilon_2/2$ and $1-\varepsilon_2/2$, not $0$ and $1$
\end{itemize}

By our assumption, the integral inequality holds for this function:
\begin{align}
\RSI(u, F, a, b, \varepsilon_1) &\geq \RSI(u, G, a, b, \varepsilon_2) \\
(1 - F(x_0)) + \varepsilon_1 \cdot (b - a) &\geq (1 - G(x_0)) + \varepsilon_2 \cdot (b - a)
\end{align}

Through similar algebraic manipulation as in the forward direction, we derive:
\begin{align}
F(x_0) &\leq G(x_0) + (\varepsilon_1 - \varepsilon_2) \cdot (b - a) \\
\Rightarrow F(x_0) &\leq G(x_0) + \varepsilon
\end{align}

Since this holds for any $x_0 \in (a,b)$, and we've already established it for the boundary points, $F \succeq_{\text{FFSD},\varepsilon} G$.
\end{proof}


