noncomputable def survivalProbN {n : N} (F : RVector n $\rightarrow$ R) ($x_0$ b : RVector n) : R :=
  1 - $\sum$ s in (Finset.powerset (Finset.univ : Finset (Fin n))) \ {$\phi$},
    (-1) ^ (s.card + 1) * F (RVector.mixedVector $x_0$ b s)
\end{lstlisting}

