\begin{lstlisting}[caption={Robust Multi-dimensional Riemann-Stieltjes Integral}, label={}]
noncomputable def robustRiemannStieltjesIntegralND {n : N} (u : RVector n $\rightarrow$ R)
    (F : RVector n $\rightarrow$ R) (a b : RVector n) ($\varepsilon$ : R)
    (hab_lt : $\forall$ i, a i < b i) : R :=
  let P_exact : Prop := $\exists$ $x_0$ $\in$ Ioo_n a b, $\forall$ $x \in$ Icc_n a b, 
    u $x$ = indicatorUpperRightOrthant $x_0$ $x$
  let P_approx : Prop := $\exists$ $x_0$ $\in$ Ioo_n a b, $\forall$ $x \in$ Icc_n a b, 
    |u $x$ - indicatorUpperRightOrthant $x_0$ $x$| $\leq$ $\varepsilon$

