  haveI : Decidable P_approx := Classical.propDecidable P_approx

  if h_exact : P_exact then
    let $x_0$ := Classical.choose h_exact
    survivalProbN Dist $x_0$ b
  else if h_approx_all : P_approx $\wedge$ $\varepsilon$ > 0 then
    let $x_0$ := Classical.choose h_approx_all.1
    survivalProbN F $x_0$ b + $\varepsilon$ * Volume_n a b
  else 0
\end{lstlisting}

