    \item \texttt{linarith} automates linear arithmetic reasoning with inequalities
    \item \texttt{ring} handles algebraic simplifications and rearrangements
    \item Pattern-matching and case analysis handle different behaviors of indicator functions
    \item The structure closely parallels the one-dimensional proof, showing the power of our abstractions
\end{itemize}
These techniques allow us to manage the increased complexity of multi-dimensional settings while maintaining the logical clarity of the proof.
\end{leanfeature}

\begin{proof}
We present a detailed mathematical proof that complements the Lean 4 formalization.

$(\Rightarrow)$ Assume $F \succeq_{\text{NFFSD},\varepsilon_{\text{surv}}} G$. Let $u$ be a function that is $\varepsilon_2$-close to an indicator function with reference point $\Rvec{x}_0 \in (\Rvec{a}, \Rvec{b})$ but is not exactly an indicator function.

By Lemma \ref{lem:integral_indicator_tolerance_md}:

\begin{align}
\RSI_{\varepsilon_1}(u, F, \Rvec{a}, \Rvec{b}) &= \survivalProb(F, \Rvec{x}_0, \Rvec{b}) + \varepsilon_1 \cdot \Vol_n(\Rvec{a}, \Rvec{b}) \\
\RSI_{\varepsilon_2}(u, G, \Rvec{a}, \Rvec{b}) &= \survivalProb(G, \Rvec{x}_0, \Rvec{b}) + \varepsilon_2 \cdot \Vol_n(\Rvec{a}, \Rvec{b})
\end{align}

For the inequality $\RSI_{\varepsilon_1}(u, F, \Rvec{a}, \Rvec{b}) \geq \RSI_{\varepsilon_2}(u, G, \Rvec{a}, \Rvec{b})$ to hold, we need:
\begin{align}
\survivalProb(F, \Rvec{x}_0, \Rvec{b}) + \varepsilon_1 \cdot \Vol_n(\Rvec{a}, \Rvec{b}) &\geq \survivalProb(G, \Rvec{x}_0, \Rvec{b}) + \varepsilon_2 \cdot \Vol_n(\Rvec{a}, \Rvec{b}) \\
\Rightarrow \survivalProb(F, \Rvec{x}_0, \Rvec{b}) &\geq \survivalProb(G, \Rvec{x}_0, \Rvec{b}) - (\varepsilon_1 - \varepsilon_2) \cdot \Vol_n(\Rvec{a}, \Rvec{b}) \\
\Rightarrow \survivalProb(F, \Rvec{x}_0, \Rvec{b}) &\geq \survivalProb(G, \Rvec{x}_0, \Rvec{b}) - \varepsilon_{\text{surv}}
\end{align}

The last inequality holds by the NFFSD condition, since $\Rvec{x}_0 \in (\Rvec{a}, \Rvec{b})$ and $\varepsilon_{\text{surv}} = (\varepsilon_1 - \varepsilon_2) \cdot \Vol_n(\Rvec{a}, \Rvec{b})$.

$(\Leftarrow)$ Assume the expected utility inequality holds for all appropriate functions $u$. We need to show $F \succeq_{\text{NFFSD},\varepsilon_{\text{surv}}} G$.

For any $\Rvec{x}_0 \in (\Rvec{a}, \Rvec{b})$, we construct a specific function:
\[
u(\Rvec{x}) = 
\begin{cases}
1 - \varepsilon_2/2 & \text{if } \Rvec{x} \gg \Rvec{x}_0 \\
\varepsilon_2/2 & \text{otherwise}
\end{cases}
\]

This function $u$ satisfies:
\begin{itemize}
    \item $\forall \Rvec{x} \in [\Rvec{a}, \Rvec{b}]$, $|u(\Rvec{x}) - \indicator_{\{\Rvec{y} \mid \Rvec{y} \gg \Rvec{x}_0\}}(\Rvec{x})| = \varepsilon_2/2 \leq \varepsilon_2$
    \item It is not an exact indicator function, since its values are $\varepsilon_2/2$ and $1-\varepsilon_2/2$, not $0$ and $1$
\end{itemize}

By our assumption, the integral inequality holds for this function:
\begin{align}
\RSI_{\varepsilon_1}(u, F, \Rvec{a}, \Rvec{b}) &\geq \RSI_{\varepsilon_2}(u, G, \Rvec{a}, \Rvec{b}) \\
\survivalProb(F, \Rvec{x}_0, \Rvec{b}) + \varepsilon_1 \cdot \Vol_n(\Rvec{a}, \Rvec{b}) &\geq \survivalProb(G, \Rvec{x}_0, \Rvec{b}) + \varepsilon_2 \cdot \Vol_n(\Rvec{a}, \Rvec{b}) \\
\Rightarrow \survivalProb(F, \Rvec{x}_0, \Rvec{b}) &\geq \survivalProb(G, \Rvec{x}_0, \Rvec{b}) - (\varepsilon_1 - \varepsilon_2) \cdot \Vol_n(\Rvec{a}, \Rvec{b}) \\
\Rightarrow \survivalProb(F, \Rvec{x}_0, \Rvec{b}) &\geq \survivalProb(G, \Rvec{x}_0, \Rvec{b}) - \varepsilon_{\text{surv}}
\end{align}

Since this holds for any $\Rvec{x}_0 \in (\Rvec{a}, \Rvec{b})$, we have $F \succeq_{\text{NFFSD},\varepsilon_{\text{surv}}} G$.
\end{proof}


