	\begin{lemma} \label{obs2} Consider an initial path $P_{in}$ and a target path $P_{tar}$.
		\begin{itemize}
			\item[(a)] For every flip sequence from $P_{in}$ to $P_{tar}$  any bad happy diagonal needs to be removed.
			\item[(b)] For every subpath $R$ of consecutive happy edges that contains at least one good happy diagonal there exists a flip sequence from $P_{in}$ to $P_{tar}$ that preserves all edges of $R$.
		\end{itemize}
	\end{lemma}

