\section{Analysis}
 In this section, we will analyze the convergence guarantees for the NG flow (\Cref{eq:SR-VN-flow}) and SR-VN (\Cref{algo:TC}). We will do this by applying tools from convex optimization, considering a set of assumptions related to boundedness and convexity.  To prove convergence, we need \Cref{assum:strong-convexity} and part $2$ of \Cref{assum:bounded-iterates} for the NG flow, and Assumptions \ref{assum:init}--\ref{assum:bounded-iterates} for SR-VN.

\subsection{Flow Convergence with Riemannian PL}
% ----------------------------------------------------
We first show that, under the assumption of strongly convex NLL (\Cref{assum:strong-convexity}), the $\KLop$ functional satisfies a local Riemannian PL inequality in the square-root parameterization (refer to \Cref{lemma:PL}). This result paves the way for proving the convergence of the NG flow, as outlined in \Cref{theorem:FR-flow}. 

We first state the following lemma that ensures that the FIM is bounded, and thus well-behaved, which is crucial for our entire analysis. The detailed proof for all the stated results can be found in \Cref{app:ngd_conv}. 

\begin{lemma}[Bounded FIM eigenvalues]\label{lemma:bdd_FIM_eig}
    For $\btu = (\bmm, \bC)$, given Assumptions \ref{assum:bounded-iterates}, we conclude that 
    \begin{align*}
        \lambda^{g}_{\min}\begin{pmatrix}
      \Id_{d\times d} & 0 \\
       0 & \Id_{d^2\times d^2} \\
  \end{pmatrix} \preccurlyeq \bF_{\btu}^{-1} \preccurlyeq \lambda^{g}_{\max}\begin{pmatrix}
      \Id_{d\times d} & 0 \\
       0 & \Id_{d^2\times d^2} \\
  \end{pmatrix},
    \end{align*}where 
\begin{align}
    \lambda^{g}_{\min} = \min\left\{\lambda_{\min}, \frac{\lambda_{\min}^2}{2}\right\}, \quad \text{and} \quad \lambda^{g}_{\max} = \xi_u^2.
\end{align}
\end{lemma}
We know that any minimizer $q_{\btu_*}(\bt) = \cN(\bt|\bmm_*, \bV_*)$ satisfies \citep{khan2023bayesian, lambert2022recursive}
\begin{equation}
\begin{aligned}\label{eq:limit_pnts}
    \bbE_{\bt \sim q_{\btu_*}(\bt)}[\nabla_{\bt} \Bar \ell(\bt)] = 0, \quad \text{and} \quad
    \bV^{-1}_* = \bbE_{\bt \sim q_{\btu_*}(\bt)}[\nabla^2_{\bt} \Bar \ell(\bt)].
\end{aligned}
\end{equation}

\paragraph{Existence of limit points. }The limit points $\bmm^*, \bC^*$ exist because of the strong convexity assumption (\Cref{assum:strong-convexity}) which implies there exists a $\btu^* =(\bmm^*, \bC^*)$ that uniquely minimizes $\cL$. The existence of this $\btu^*$ can be argued using the fact that $\cL$ is continuous and coercive and  $\Omega$ (the set of $\btu'$s) can be extended to a closed set (but the minimizer can be shown to lie inside $\Omega$ due to \Cref{eq:limit_pnts}). Then, a global minimum exists due to the Weierstrass extreme value theorem.

As a consequence of \Cref{lemma:bdd_FIM_eig}, one can prove the following lemma, given that NLL is strongly-convex, which establishes a PL inequality where we measure the magnitude of the gradient in the (natural) Riemannian geometry. This will be needed to prove the convergence guarantees for the Riemannian gradient flow and descent.

\begin{lemma}[Riemannian PL Inequality]\label{lemma:PL}
    The KL functional satisfies a local Polyak-Łojasiewicz (PL) inequality with PL constant $\mu = \delta\lambda^g_{\min}$, that is,
    \begin{align}\label{eq:PL_KL}
        \norm{\nabla_{\btu}\KLop\bigg[q_{\btu}(\bt)\mid\mid p(\bt\mid\cD)\bigg]}_{\bF_{\btu}^{-1}}^2 \geq 2\mu \left(\KLop\bigg[q_{\btu}(\bt)\mid\mid p(\bt\mid\cD)\bigg] - \KLop\bigg[q_{\btu_*}(\bt)\mid\mid p(\bt\mid\cD)\bigg]\right) .
    \end{align}
\end{lemma}
\begin{remark}
    \Cref{lemma:PL} is a 'local` PL inequality because it only holds for the chosen parametrization. This is because of the use of strong-convexity of ELBO for its proof (see \Cref{app:PL}), which only holds for $(\bmm, \bC)$ parametrization. Since one does not know if convexity will hold in all parametrizations there is no guarantee that the PL inequality will hold globally.
\end{remark}
Once the Riemannian PL condition is established, we can derive a convergence rate using a standard Lyapunov function analysis. As mentioned earlier, this analysis can be modified to incorporate a bias term as shown in \Cref{app:ngd_w_bias}.

% ========================================================================
\begin{theorem}\label{theorem:FR-flow}
Under Assumptions \ref{assum:strong-convexity} and \ref{assum:bounded-iterates}, the NG flow dynamics defined in \Cref{eq:SR-VN-flow} satisfy
\begin{align*}
    &\KLop\bigg[q_{\btu_t}(\bt)\mid\mid p(\bt\mid\cD)\bigg] -  \KLop\bigg[q_{\btu_*}(\bt)\mid\mid p(\bt\mid\cD)\bigg] \\
    &\qquad \leq e^{-2\mu t} \bigg(\KLop\bigg[q_{\btu_0}(\bt)\mid\mid p(\bt\mid\cD)\bigg] - \KLop\bigg[q_{\btu_*}(\bt)\mid\mid p(\bt\mid\cD)\bigg]\bigg). 
\end{align*}
\end{theorem}

% -------------------------------------------------------------------
\subsection{Convergence of SR-VN}\label{sec:conv-result}

Under \Cref{assum:init}--\ref{assum:strong-convexity}, we give what we believe are the first rigorous convergence guarantees for optimizing \ref{eq:general-elbo} using \Cref{algo:TC}. 
Specifically, we show an exponential rate of convergence for \Cref{algo:TC}, as stated in Theorem \ref{theorem:global-tan-cholesky}, with a detailed proof provided in \Cref{app:proof-tan-chol}. The literature has suggested various updates, as seen in references \cite{lin2019fast, lin2021tractable, lin2021structured, khan2023bayesian}. It is also worth highlighting that our proof extends to generic NGD algorithms that use \emph{any} square-root parametrization. The proof technique used to derive Theorem~\ref{theorem:global-tan-cholesky} can easily be adapted to prove convergence for these other variants and is omitted here to avoid redundancy.

% ****************************************
\begin{theorem}[Global Convergence]
\label{theorem:global-tan-cholesky}
 Given Assumptions \ref{assum:init}--\ref{assum:bounded-iterates} and considering the limit points $\bmm_*$ and $\bC_*$ in \Cref{eq:limit_pnts}, the updates provided by Algorithm \ref{algo:TC} satisfy
\begin{equation}\label{eq:global_convergence}
\begin{aligned}
    &\cL(\bmm_{t+1}, \bC_{t+1})  - \cL(\bmm_*, \bC_*) \leq(1 - 2\eta\delta)^{t+1} (\cL(\bmm_0, \bC_0)  - \cL(\bmm_*, \bC_*)),
\end{aligned}
\end{equation}where
\begin{equation}
\eta = \min\left\{\lambda_{\min} \rho-\frac{M\rho^2\xi_u^4}{2},\quad \sqrt{\frac{5}{2}}\rho\xi_l^2 - \frac{5\rho^2\xi_u^4M}{4}\right\}.
\label{thm:eta}
\end{equation}
For convergence, we require that $0 < (1 - 2\eta\delta) < 1$. This constraints the step-size $\rho > 0$ to satisfy certain conditions. The permissible step-sizes satisfying the above constraint are discussed in \Cref{sec:adm-rho}, along with the time complexity of SR-VN in \Cref{eq:time_complexity}.
\end{theorem}





