\title{Collapses in quantum-classical probabilistically checkable proofs \\ and the quantum polynomial hierarchy}


\author{Kartik Anand\thanks{Indian Institute of Technology Goa, \href{mailto:kartik.anand.19031@iitgoa.ac.in}{kartik.anand.19031@iitgoa.ac.in}} 
