\begin{lemma}[Deterministic polynomial-time reduction from $\MTP$ to $\SAT$]\label{lem:mtp-sat}
    The $\MTP$ can be reduced to $\SAT$ deterministically and in polynomial time.
\end{lemma}

\begin{proof}
Let $P(y)$ denote the solution polynomial of the given $\MTP$ instance
\begin{equation}
    P(y) = \sum_{\substack{S \subseteq [p(n)],~|S| \leq 2q}} \beta_S \prod_{i \in S} y_i,
\end{equation}
where $\beta_S \in \mathbb{R}$ is represented using $\ell$-bit fixed-point encoding.

We assume the standard promise structure:
\begin{enumerate}[label=(\roman*)]
    \item (Correctness and Uniqueness) There exists at least a $y \in \{0,1\}^n$ such that $P(y) \geq a$.
    \item (Soundness) For all $y \in \{0,1\}^n$, $P(y) < a$.
\end{enumerate}

\paragraph{Transforming $P(y)$ into a Boolean formula.}
For each monomial $\prod_{i \in S} y_i$, define a clause:
\begin{equation}
    \phi_S := \bigwedge_{i \in S} y_i
\end{equation}
This is a conjunction over a subset of input variables. Each such clause $\phi_S$ can be encoded in CNF form via the Tseytin transformation.

\medskip\medskip

Each $\beta_S$ satisfies the bound (\cite[Lemma 3]{BuhrmanLeGallWeggemans2024}): $|\beta_S| \leq (1 + (1 + 2^{2q})^{2q - 1})\|P\|_{\infty}$, with $\|P\|_{\infty} \leq 1$. Thus, $\beta_S$ can be expressed as $v_S / 2^\ell$ with $v_S \in \mathbb{Z}$ represented using $k$-bit integers, where $k = \log_2 (1 + (1 + 2^{2q})^{2q - 1}) + \ell + 1$.

\medskip\medskip

Define the scaled polynomial:
\begin{equation}
    P'(y) := 2^\ell \cdot P(y) = \sum_{\substack{S \subseteq [p(n)],~|S| \leq 2q}} v_S \cdot \phi_S,
\end{equation}
where $v_S$ is a $k$-bit integer. Write $v_S$ in binary:
\begin{equation}
    v_S = \sum\limits_{i=1}^{k'} 2^i b_{S,i},
\end{equation}
with $b_{S,i} \in \{0,1\}$ and $k' = \log_2 (1 + (1 + 2^{2q})^{2q - 1})$.

\medskip\medskip

As $\phi_S \in \{0,1\}$, it acts like a Boolean variable. Thus:
\begin{align}
    P'(y) = \sum_{\substack{S \subseteq [p(n)],~ |S| \leq 2q}} \sum_i 2^i (b_{S,i} \land \phi_S) = \sum_S \left( \sum_i 2^i b_{S,i} \right) \cdot \phi_S.
\end{align}

\paragraph{Adder network construction.}
Each $v_S$ is represented in $k'$ bits. To compute $P'(y)$, we sum all such $k'$-bit numbers. This can be done using standard half-adder and full-adder networks, which can be encoded into CNF form using the Tseytin transformation. The total circuit has size polynomial in $|S| \cdot k'$ and logarithmic depth $\bigo(\log(|S| \cdot k'))$.

\paragraph{Threshold comparison circuit.}
We wish to enforce $\exists y\in\{0,1\}^n : P'(y) \geq 2^\ell a$, or in the soundness case, $\forall y\in\{0,1\}^n, \; P'(y) < 2^\ell a$. These threshold comparisons can be implemented by comparator circuits (in the class \textsf{CC}) and converted to CNF via Tseytin transformations.

\paragraph{Putting it all together.}
All parts of $P'(y)$—the monomials, the binary representations, the adder and comparator circuits—can be encoded into a Boolean formula in CNF with auxiliary variables $b_{S,i}$ and original variables $y_i$. This yields a deterministic and efficient reduction from $\MTP$ to $\SAT$.
\end{proof}

\begin{lemma}[Deterministic polynomial-time reduction from $\mathsf{UniqueSAT}$ to $\mathsf{UniqueMTP}$]
\label{lem:usat-to-umtp}
    There exists a deterministic polynomial-time reduction from $\mathsf{UniqueSAT}$ to $\mathsf{UniqueMTP}$.
\end{lemma}

\begin{proof}
    Given a CNF formula $\phi$ with clauses $C_1, C_2, \ldots, C_m$ over variables $x_1, x_2, \ldots, x_n$, we construct a multilinear polynomial as follows:
    \begin{equation}
        P(x_1, \ldots, x_n) = \sum_{j=1}^m \prod_{\ell \in C_j} \tilde{x}_\ell,
    \end{equation}
    where for each literal $\ell$ in clause $C_j$:
    \begin{equation}
        \tilde{x}_\ell = \begin{cases}
            x_i & \text{if } \ell = x_i, \\
            1 - x_i & \text{if } \ell = \neg x_i.
        \end{cases}
    \end{equation}

    \medskip\medskip

    We set the threshold to $a = m$.
    \begin{enumerate}[label=(\roman*)]
        \item (Completeness) If assignment $x$ satisfies $\phi$, then $x$ satisfies every clause $C_j$. For each clause $C_j$, at least one literal evaluates to true, making the corresponding product $\prod_{\ell \in C_j} \tilde{x}_\ell = 1$. Therefore, $P(x) = m \geq a$.
        \item (Soundness) If assignment $x$ does not satisfy $\phi$, then $x$ violates at least one clause $C_j$. For any violated clause, all literals evaluate to false, making the corresponding product $\prod_{\ell \in C_j} \tilde{x}_\ell = 0$. Thus, $P(x) \leq m - 1 < a$.
        \item (Uniqueness preservation) Since the reduction maps each satisfying assignment $x$ of $\phi$ to the same assignment $x$ for the polynomial $P$, uniqueness is preserved by the identity mapping.
    \end{enumerate}
    The reduction runs in polynomial time as constructing $P$ requires examining each clause and literal once.
\end{proof}

\begin{lemma}[\textsf{BQ} reduction from \(\mathsf{UniqueMTP}\) to \(\mathsf{UniqueQCPCP}\)]
\label{lem:umtptouqcpcp}
Let \(\Psi = (P(y),\, a,\, \delta_D)\) be an instance of the \(\mathsf{UniqueMTP}\) over Boolean variables \(y \in \{0,1\}^m\), where
\begin{equation}
    P(y) = \sum_{\substack{S \subseteq [m],\, |S| \le d}} \beta_S \prod_{i \in S} y_i,    
\end{equation}
and suppose that \(\Psi\) satisfies the following promise:
\begin{equation}
    \begin{cases}
        \exists!\, y^* \in \{0,1\}^m \textnormal{ such that } P(y^*) \ge a & \textnormal{(YES instance)}, \\
    \forall\, y \in \{0,1\}^m,\; P(y) < a & \textnormal{(NO instance)},
    \end{cases}    
\end{equation}
with a gap parameter \(\delta_D > 0\). Then there exists a polynomial-time deterministic quantum algorithm that outputs the description of a verifier $V_\Psi \in \mathsf{UniqueQCPCP}[p(m) = m,\, q = d,\, c,\, s]$, where
\[
c = \frac{a + \delta_D}{\sum_{j=1}^{N} |\beta_{S_j}|}
\quad \text{and} \quad
s = \frac{a - \delta_D}{\sum_{j=1}^{N} |\beta_{S_j}|},
\]
such that:

\begin{itemize}
  \item[(i)] If \(\Psi\) is a YES instance with unique witness \(y^*\), then \(V_\Psi\) accepts exactly on the proof \(y^*\) and rejects all other \(y\).
  \item[(ii)] If \(\Psi\) is a NO instance, then \(V_\Psi\) rejects every proof \(y\).
\end{itemize}
\end{lemma}

\begin{proof}
We describe the deterministic quantum reduction that maps \(\Psi\) to a verifier \(V_\Psi\). The following data is hardcoded into the description of \(V_\Psi\):
\[
\left\{S_j \subseteq [m] : |S_j| \le d \right\}, \quad
\{\beta_{S_j}\}_{j=1}^N, \quad 
a,\, \delta_D,
\]
where \(N = \sum_{i=0}^d \binom{m}{i} = \mathrm{poly}(m)\).

\paragraph{Verifier \(V_\Psi\).} On input proof \(y \in \{0,1\}^m\), the verifier proceeds as follows:

\begin{enumerate}[label=(\roman*)]
  \item Compute \(B := \sum_{j=1}^N |\beta_{S_j}|\) and sample a uniform real \(r \in [0, B)\) using \(\lceil \log (n) \rceil\) random bits.

  \item Find the unique index \(j\) such that
  \begin{equation}
    \sum_{i=1}^{j-1} |\beta_{S_i}| \le r < \sum_{i=1}^{j} |\beta_{S_i}|.    
  \end{equation}
  Let \(S = S_j\) and \(\sigma := \mathrm{sign}(\beta_{S_j}) \in \{\pm 1\}\).

  \item The verifier non-adaptively queries the qubits \(y_i\) for \(i \in S\) into an ancilla register via the unitary: $\ket{i}\ket{0} \mapsto \ket{i}\ket{y_i},~\forall i \in S$.    

  \item \textit{Phase kickback.} Apply a controlled-phase gate that multiplies the global phase by
  \begin{equation}
    \exp\left(i\pi \sigma \prod_{i \in S} y_i\right).
  \end{equation}

  \item \textit{Estimate contribution.} Use a Hadamard test subroutine on the ancilla to estimate the real part \(\Re[\beta_S \prod_{i \in S} y_i]\) up to additive error \(\delta_D/2\).

  \item To ensure this accuracy with high probability, repeat the Hadamard test subroutine \(T = O(1/\delta_D^2)\) times. This follows from Hoeffding's inequality: given bounded random variables \(X_1, \dots, X_T\) with \(|X_i| \le 1\) and mean \(\mu\), the empirical mean \(\hat{\mu} = \frac{1}{T} \sum_{i=1}^T X_i\) satisfies
  \begin{equation}
    \Pr[\, |\hat{\mu} - \mu| \ge \epsilon \,] \le 2 \exp(-2T\epsilon^2).    
  \end{equation}
  Setting \(\epsilon = \delta_D/2\), it suffices to take $T \ge {2\ln(2/\delta)}/{\delta_D^2}$ for failure probability \(\delta\). Since \(\delta_D\) is constant, this requires only a constant number of repetitions.

  \item \textit{Accept/reject.} Let \(\widehat{P}(y)\) be the empirical estimate of \(P(y)\) obtained by averaging the Hadamard test results over repeated monomial sampling. The verifier accepts if and only if \(\widehat{P}(y) \ge a\).

  To ensure correctness with respect to the \(\mathsf{QCPCP}\) gap, we normalize the thresholds by \(B = \sum_{j=1}^{N} |\beta_{S_j}|\), setting $c = {(a + \delta_D)}/{B}$, and $s = {(a - \delta_D)}/{B}$, which satisfies \(c - s = {2\delta_D}/{B} = {1}/{\mathrm{poly}(m)}\), sufficient for our \(\mathsf{QCPCP}\) setting.
\end{enumerate}

\paragraph{Analysis.} With this analysis, we conclude that $\mathsf{UniqueMTP} \le_{\mathsf{BQ}} \mathsf{UniqueQCPCP}$.

\begin{enumerate}[label=(\roman*)]
  \item (Bounded query) In each execution, \(V_\Psi\) queries at most \(|S| \le d\) bits of the proof \(y\), thus the query complexity is \(q = d\).

  \item (Completeness) If \(\Psi\) is a YES instance with unique satisfying assignment \(y^*\) such that \(P(y^*) \ge a\), then each monomial contributes exactly \(\beta_S \prod_{i \in S} y^*_i\), so \(\mathbb{E}[\widehat{P}(y^*)] = P(y^*) \ge a\). By concentration bounds, the empirical estimate \(\widehat{P}(y^*)\) exceeds \(a\) with high probability. No other \(y \ne y^*\) can satisfy \(P(y) \ge a\), hence only \(y^*\) is accepted.

  \item (Soundness) If \(\Psi\) is a NO instance, then for all \(y \in \{0,1\}^m\), we have \(P(y) < a\), so with high probability the estimate \(\widehat{P}(y)\) also satisfies \(\widehat{P}(y) < a\), and \(V_\Psi\) rejects all proofs.

  \item (Uniqueness preservation) The reduction \(\Psi \mapsto V_\Psi\) preserves the uniqueness of the satisfying assignment: the only proof that can be accepted by \(V_\Psi\) is the unique \(y\) such that \(P(y) \ge a\).
\end{enumerate}
This completes the proof.
\end{proof}


