\begin{theorem}[Reduction from \(\mathsf{QCPCP}\) to \(\mathsf{UniqueQCPCP}\)]
\label{thm:qcpcp-to-uqcpcp}
Let $V$ be a $\mathsf{QCPCP}$ verifier for a promise problem $\mathcal{A} = (A_{\mathrm{YES}}, A_{\mathrm{NO}})$, with completeness $c$, soundness $s$, proof length $l_n$, and running time $T_n$. Then there exists a randomized polynomial-time algorithm which, given $V$, outputs a verifier $V'$ for a $\mathsf{UniqueQCPCP}$ system with the following properties:
\begin{enumerate}[label=(\roman*)]
    \item $V'$ runs in time $\mathcal{O}(T_n)$ and expects proofs of length $l_n + \mathcal{O}(\log (l_n))$.

    \item \textnormal{(Completeness):} If $x \in A_{\mathrm{YES}}$, then with probability at least $\Omega(1/\textnormal{poly}(l_n))$ over the randomness of the reduction, there exists a unique proof $y^* \in \{0,1\}^{l_n + \mathcal{O}(\log (l_n))}$ such that $\Pr[V'(x, y^*) = 1] \ge c - \gamma$, and $\forall y' \ne y^*,\; \Pr[V'(x, y') = 1] \le \gamma$, where $\gamma = \operatorname{negl}(n)$ is negligible in $n$.

    \item \textnormal{(Soundness)} If $x \in A_{\mathrm{NO}}$, then with probability $1$ over the randomness of the reduction, it holds that for all $y \in \{0,1\}^{l_n + \mathcal{O}(\log (l_n))}$, $\Pr[V'(x, y) = 1] \le s + \gamma$.
\end{enumerate}

\end{theorem}

\begin{proof}
This follows by composing the reductions:
\begin{equation}
    \mathsf{QCPCP} \le_{\mathsf{BQ}} \mathsf{MTP} \le_p \mathsf{SAT} \le_{\mathsf{RP}} \mathsf{UniqueSAT} \le_p \mathsf{UniqueMTP} \le_{\mathsf{BQ}} \mathsf{UniqueQCPCP},    
\end{equation}
where the first step is given by  of~\cite[Theorem 4]{BuhrmanLeGallWeggemans2024}, and the remaining steps are covered in~\cref{lem:mtp-sat},~Valiant-Vazirani reduction~{\cite{ValiantVazirani1986}},~\cref{lem:usat-to-umtp}, and~\cref{lem:umtptouqcpcp}. The only degradation in completeness and soundness arises from the randomized reduction from \(\mathsf{SAT}\) to \(\mathsf{UniqueSAT}\), which incurs a loss of at most \(1/l_n\) in each. This completes the proof.
\end{proof}


\subsection{Search-to-decision reductions}
For $\mathsf{QCMA}$, \cite{anandchinmaysearchtodecision} established a one-query Bernstein-Vazirani-style reduction using an oracle of the form $f(x) = x \cdot y^*$, where $y^*$ is the desired witness and $x \cdot y^*$ denotes the inner product. This reduction exploits the fact that $\mathsf{QCMA}$ verifiers have access to the entire classical proof string.

The situation for $\mathsf{QCPCP}$ is fundamentally different. A $\mathsf{QCPCP}$ oracle can only provide information of the form ``there exists a proof $y$ such that the verifier accepts,'' rather than direct access to inner products with proof bits. This limitation arises because $\mathsf{QCPCP}$ verifiers query only a constant number of bits from the proof, rather than having access to the entire proof string as in $\mathsf{QCMA}$.

Consequently, witness extraction for $\mathsf{QCPCP}$ appears to require bit-by-bit reconstruction, leading to $\mathcal{O}(n)$ oracle queries where $n$ is the proof length. With current techniques, no one-query Bernstein-Vazirani-style reduction analogous to that of~\cite{anandchinmaysearchtodecision} seems feasible for $\mathsf{QCPCP}$.

\section{Towards the collapse of the quantum polynomial hierarchy}
\label{sec:qph}
In this section, we investigate two perspectives on the potential collapse of the quantum polynomial hierarchy ($\QPH$). First, we present a non-uniform version of the Karp--Lipton theorem for $\QPH$. Second, we introduce a new class of problems that is structurally closer to the standard $\QPH$: namely, the proofs are restricted to product states (in contrast to the entangled states allowed in $\mathsf{QEPH}$), but are still interdependent due to a consistency condition enforced by the interaction of two players.

\subsection{Definitions and preliminaries}
\subsubsection{Complexity classes}
We begin by introducing the necessary definitions for quantum complexity classes including $\mathsf{Q\Sigma}_i(c,s)$, $\mathsf{QPH}$, $\mathsf{BQP}/\mathsf{qpoly}$ and $\mathsf{Q\Sigma}_2/\mathsf{qpoly}$.
\begin{definition}[$\mathsf{Q\Sigma}_i(c,s)$]
\label{def:qsigma-i}
Let $\mathcal{A} = (A_{\mathrm{YES}}, A_{\mathrm{NO}})$ be a promise problem, and let $c, s : \mathbb{N} \rightarrow [0,1]$ be polynomial-time computable functions. Then $\mathcal{A} \in \mathsf{Q\Sigma}_i(c, s)$ if there exists:
\begin{enumerate}[label=(\roman*)]
    \item a polynomially bounded function $p : \mathbb{N} \to \mathbb{N}$, and
    \item a polynomial-time uniform family of quantum circuits $\{V_n\}_{n \in \mathbb{N}}$,
\end{enumerate}
such that for every input $x \in \{0,1\}^n$, the verifier $V_n$ takes $p(n)$-qubit quantum states $\rho_1, \ldots, \rho_i$ as input proofs and outputs a single qubit. The verifier measures the output qubit in the computational basis, and the acceptance probability is defined on input $\rho_1 \otimes \cdots \otimes \rho_i$.

\begin{enumerate}[label=(\roman*)]
    \item \textnormal{(Completeness)} If $x \in L_{\mathrm{YES}}$, then $\exists \rho_1 \; \forall \rho_2 \; \cdots \; Q_i \rho_i$ such that $\Pr[V_n \textnormal{ accepts}] \geq c(n)$.    

    \item \textnormal{(Soundness)} If $x \in L_{\mathrm{NO}}$, then $\forall \rho_1 \; \exists \rho_2 \; \cdots \; \overline{Q}_i \rho_i$ such that $\Pr[V_n \textnormal{ accepts}] \leq s(n)$.
\end{enumerate}
Here, $Q_i = \forall$ if $i$ is even and $Q_i = \exists$ if $i$ is odd; $\overline{Q}_i$ denotes the complementary quantifier. When the completeness and soundness parameters are not specified, we define the class
\begin{equation}
    \mathsf{Q\Sigma}_i := \bigcup_{c-s \in \Omega(1/\mathrm{poly}(n))} \mathsf{Q\Sigma}_i(c,s).
\end{equation}
\end{definition}

\begin{definition}[Quantum polynomial hierarchy, $\mathsf{QPH}$]
\label{def:qph}
The quantum polynomial hierarchy $\mathsf{QPH}$ is defined as
\begin{equation}
    \mathsf{QPH} := \bigcup_{i \in \mathbb{N}} \mathsf{Q\Sigma}_i = \bigcup_{i \in \mathbb{N}} \mathsf{Q\Pi}_i,
\end{equation}
where $\mathsf{Q\Pi}_i := \mathsf{co\text{-}Q\Sigma}_i$.
\end{definition}

\begin{definition}[$\mathsf{BQP}/\mathsf{qpoly}$]
\label{def:bqp-qpoly}
A promise problem $\mathcal{A} = (A_{\mathrm{YES}}, A_{\mathrm{NO}})$ is in $\mathsf{BQP}/\mathsf{qpoly}$ if there exist:
\begin{enumerate}[label=(\roman*)]
    \item a polynomial-size family of quantum circuits $\{C_n\}_{n \in \mathbb{N}}$, and
    \item a sequence of polynomial-size quantum advice states $\{|\psi_n\rangle\}_{n \in \mathbb{N}}$,
\end{enumerate}
such that for all $x \in \{0,1\}^n$, the circuit $C_n$ takes input $|x\rangle \otimes |\psi_n\rangle$ and satisfies:
\begin{enumerate}[label=(\roman*)]
    \item \textnormal{(Completeness)} If $x \in A_{\mathrm{YES}}$, then $\Pr[C_n(|x\rangle \otimes |\psi_n\rangle) = 1] \geq 2/3$.

    \item \textnormal{(Soundness)} If $x \in A_{\mathrm{NO}}$, then $\Pr[C_n(|x\rangle \otimes |\psi_n\rangle) = 1] \leq 1/3$.
\end{enumerate}
Note that $\mathsf{BQP}/\mathsf{qpoly}$ is the quantum analogue of $\mathsf{BPP}/\mathsf{poly}$, where quantum advice states replace classical advice strings.
\end{definition}

\begin{definition}[$\mathsf{Q\Sigma}_2/\mathsf{qpoly}$]
\label{def:qsigma2-qpoly}
A promise problem $\mathcal{A} = (A_{\mathrm{YES}}, A_{\mathrm{NO}})$ is in $\mathsf{Q\Sigma}_2/\mathsf{qpoly}(c,s)$ if there exist:
\begin{enumerate}[label=(\roman*)]
    \item a polynomial-time uniform family of quantum circuits $\{V_n\}_{n \in \mathbb{N}}$,
    \item a sequence of polynomial-size quantum advice states $\{|\psi_n\rangle\}_{n \in \mathbb{N}}$, and
    \item polynomial-time computable functions $c, s : \mathbb{N} \rightarrow [0,1]$,
\end{enumerate}
such that for all $x \in \{0,1\}^n$, the verifier $V_n$ takes $(x, |\psi_n\rangle, \rho_1, \rho_2)$ as input, where $\rho_1, \rho_2$ are polynomial-size quantum states, and satisfies:
\begin{enumerate}[label=(\roman*)]
    \item \textnormal{(Completeness)} If $x \in A_{\mathrm{YES}}$, then $\exists \rho_1 \; \forall \rho_2$ such that $\Pr[V_n(x, |\psi_n\rangle, \rho_1, \rho_2) = 1] \geq c(n)$.    

    \item \textnormal{(Soundness)} If $x \in A_{\mathrm{NO}}$, then $\forall \rho_1 \; \exists \rho_2$ such that $\Pr[V_n(x, |\psi_n\rangle, \rho_1, \rho_2) = 1] \leq s(n)$.
\end{enumerate}
When the completeness-soundness gap is not explicitly given, we define
\begin{equation}
    \mathsf{Q\Sigma}_2/\mathsf{qpoly} := \bigcup_{c-s \in \Omega(1/\mathrm{poly}(n))} \mathsf{Q\Sigma}_2/\mathsf{qpoly}(c,s).    
\end{equation}
\end{definition}

\begin{definition}[Quantum entangled polynomial hierarchy, $\mathsf{QEPH}$~\cite{grewaljustinqeph}]
\label{def:qeph}
The class $\mathsf{QEPH}$ is defined analogously to $\mathsf{QPH}$, except that the proof states $\rho_1, \ldots, \rho_i$ in the completeness and soundness conditions are allowed to be arbitrary entangled states over all proof registers, rather than being restricted to product states as in $\mathsf{QPH}$.
\end{definition}

\begin{remark}[Containment relations]
It is straightforward to verify that $\mathsf{QPH} \subseteq \mathsf{QEPH}$ and $\mathsf{BQP}/\mathsf{qpoly} \subseteq \mathsf{Q\Sigma}_2/\mathsf{qpoly}$. The relationship between quantum and classical advice in the hierarchy setting (e.g., whether $\mathsf{Q\Sigma}_i/\mathsf{qpoly} \subseteq \mathsf{Q\Sigma}_i/\mathsf{poly}$) remains an interesting open question.
\end{remark}

\subsubsection{Convexity and entanglement measures}

In this section, we collect key convexity-theoretic results that underpin our collapse arguments. In particular, we highlight structural properties of the state space of quantum systems and their implications for optimization over separable states.

\begin{theorem}[Sion's minimax theorem~\cite{sion1958minimax}]
\label{thm:sion}
Let $X$ and $Y$ be topological vector spaces, and let $A \subseteq X$ and $B \subseteq Y$ be convex and compact subsets. Suppose $f : A \times B \rightarrow \mathbb{R}$ is a function that is concave in its first argument and convex in its second argument. Then,
\begin{equation}
    \max_{a \in A} \min_{b \in B} f(a, b) = \min_{b \in B} \max_{a \in A} f(a, b).
\end{equation}
In the setting of quantum proof systems, the set of density matrices $\mathcal{D}(\mathcal{H})$ over a finite-dimensional Hilbert space $\mathcal{H}$ forms a convex and compact subset under the trace norm topology~\cite{watrous2018quantum}.
\end{theorem}

\begin{theorem}[Krein--Milman theorem~\cite{Krein1940}]
\label{thm:krein-milman}
Let \( K \) be a non-empty compact convex subset of a locally convex topological vector space \( X \). Then, $K = \overline{\mathrm{conv}}(\operatorname{ext}(K))$, where \( \operatorname{ext}(K) \) denotes the set of extreme points of \( K \), and \( \overline{\mathrm{conv}} \) denotes the closure of the convex hull of these extreme points with respect to the topology of \( X \).
\end{theorem}

\begin{definition}[Relative entropy of entanglement]\label{def:ree}
The relative entropy of entanglement of a bipartite quantum state \( \rho_{AB} \) is defined as
\begin{equation}
    \mathcal{E}(\rho_{AB}) = \inf_{\sigma_{AB} \in \mathbf{Sep}} S(\rho_{AB} \| \sigma_{AB}),
\end{equation}
where \( \mathbf{Sep} \) denotes the set of separable states and \( S(\rho \| \sigma) = \operatorname{Tr}[\rho \log (\rho)] - \operatorname{Tr}[\rho \log (\sigma)] \) is the quantum relative entropy between \( \rho \) and \( \sigma \).
\end{definition}


