\subsection{Non-uniform Karp--Lipton collapse for quantum polynomial hierarchy}
In this section, we prove the following quantum Karp--Lipton theorem by leveraging the quantum complexity classes defined in the previous section along with key convexity properties.
\begin{theorem}[Quantum Karp--Lipton]
\label{thm:quantum-Karp--Lipton}
If $\mathsf{QMA} \subseteq \mathsf{BQP}/\mathsf{qpoly}$, then the quantum polynomial hierarchy collapses to its second level with quantum advice:
\begin{equation}
    \mathsf{QPH} = \bigcup_{k \in \mathbb{N}} \mathsf{Q\Sigma}_k \subseteq \mathsf{Q\Sigma}_2/\mathsf{qpoly}.
\end{equation}
\end{theorem}

\begin{proof}
We prove the result by induction on $k$. Throughout the proof, we use the standard completeness and soundness parameters $c = 2/3$ and $s = 1/3$.

\paragraph{Base Case ($k = 3$).}  
Let $\mathcal{A} \in \mathsf{Q\Sigma_3}$. Then by~\cref{def:qsigma-i}, there exists a polynomial-time uniform family of quantum circuits $\{V_n^{(3)}\}$ such that for all $x \in \{0,1\}^n$:
\begin{align}
x \in A_{\mathrm{YES}} &\iff \exists \rho_1 \, \forall \rho_2 \, \exists \rho_3 : \Pr[V_n^{(3)}(x; \rho_1, \rho_2, \rho_3) = 1] \geq 2/3, \\
x \in A_{\mathrm{NO}} &\iff \forall \rho_1 \, \exists \rho_2 \, \forall \rho_3 : \Pr[V_n^{(3)}(x; \rho_1, \rho_2, \rho_3) = 1] \leq 1/3.
\end{align}

\medskip\medskip

Define a quantum promise problem $\mathsf{P}_x$ with input $(\rho_1, \rho_2)$ as follows:
\begin{align}
(\rho_1, \rho_2) \in \mathsf{P}_{x,\text{YES}} &\iff \exists \rho_3 : \Pr[V_n^{(3)}(x; \rho_1, \rho_2, \rho_3) = 1] \geq 2/3, \\
(\rho_1, \rho_2) \in \mathsf{P}_{x,\text{NO}} &\iff \forall \rho_3 : \Pr[V_n^{(3)}(x; \rho_1, \rho_2, \rho_3) = 1] \leq 1/3.
\end{align}

\medskip\medskip

By construction, $\mathsf{P}_x \in \mathsf{QMA}$ for each fixed $x$. By the assumption $\mathsf{QMA} \subseteq \mathsf{BQP}/\mathsf{qpoly}$, there exists a polynomial-time quantum circuit family $\{C_n\}$ and a polynomial-size quantum advice sequence $\{|\alpha_n\rangle\}$ (depending only on $n = |x|$) such that:
\begin{align}
(\rho_1, \rho_2) \in \mathsf{P}_{x,\text{YES}} &\implies \Pr[C_n(x, \rho_1, \rho_2, |\alpha_n\rangle) = 1] \geq 2/3, \\
(\rho_1, \rho_2) \in \mathsf{P}_{x,\text{NO}} &\implies \Pr[C_n(x, \rho_1, \rho_2, |\alpha_n\rangle) = 1] \leq 1/3.
\end{align}
Substituting this characterization into the original quantifier expressions:
\begin{align}
x \in A_{\mathrm{YES}} &\iff \exists \rho_1 \, \forall \rho_2 : \Pr[C_n(x, \rho_1, \rho_2, |\alpha_n\rangle) = 1] \geq 2/3, \\
x \in A_{\mathrm{NO}} &\iff \forall \rho_1 \, \exists \rho_2 : \Pr[C_n(x, \rho_1, \rho_2, |\alpha_n\rangle) = 1] \leq 1/3.
\end{align}
This defines a $\mathsf{Q\Sigma_2}$ protocol with quantum advice $|\alpha_n\rangle$. Therefore, $\mathcal{A} \in \mathsf{Q\Sigma_2}/\mathsf{qpoly}$.

\paragraph{Inductive Step.}  
Assume the conditional inclusion holds for all $\mathsf{Q\Sigma}_j$ with $j \leq k-1$, i.e., $\mathsf{Q\Sigma}_j \subseteq \mathsf{Q\Sigma_2}/\mathsf{qpoly}$. We prove that $\mathsf{Q\Sigma}_k \subseteq \mathsf{Q\Sigma_2}/\mathsf{qpoly}$ for $k \geq 4$.

\medskip\medskip

Let $\mathcal{A} \in \mathsf{Q\Sigma}_k$. By definition:
\begin{equation}
    x \in A_{\mathrm{YES}} \iff \exists \rho_1 \, \forall \rho_2 \, \exists \rho_3 \cdots Q_k \rho_k : \Pr[V_n^{(k)}(x; \rho_1, \ldots, \rho_k) = 1] \geq 2/3.
\end{equation}
We can restructure this as:
\begin{equation}
    x \in A_{\mathrm{YES}} \iff \exists \rho_1 \, \forall \rho_2 : (x, \rho_1, \rho_2) \in \mathcal{A}',    
\end{equation}
where the quantum language $\mathcal{A}' \in \mathsf{Q\Sigma}_{k-2}$ is defined by:
\begin{equation}
    (x, \rho_1, \rho_2) \in A'_{\mathrm{YES}} \iff \exists \rho_3 \cdots Q_k \rho_k : \Pr[V_n^{(k)}(x; \rho_1, \ldots, \rho_k) = 1] \geq 2/3.
\end{equation}

\medskip\medskip

By the induction hypothesis, $\mathcal{A}' \in \mathsf{Q\Sigma_2}/\mathsf{qpoly}$. Therefore, there exists a verifier $N_n$ and advice state $|\beta_n\rangle$ such that:
\begin{equation}
    (x, \rho_1, \rho_2) \in A'_{\mathrm{YES}} \iff \exists \sigma_1 \, \forall \sigma_2 : \Pr[N_n(x, \rho_1, \rho_2, \sigma_1, \sigma_2, |\beta_n\rangle) = 1] \geq 2/3.    
\end{equation}
Substituting back:
\begin{equation}
    x \in A_{\mathrm{YES}} \iff \exists \rho_1 \, \forall \rho_2 \, \exists \sigma_1 \, \forall \sigma_2 :
    \Pr[N_n(x, \rho_1, \rho_2, \sigma_1, \sigma_2, |\beta_n\rangle) = 1] \geq 2/3.    
\end{equation}

\medskip\medskip

The inner three quantifiers $\forall\rho_2\exists\sigma_1\forall\sigma_2$ form a $\mathsf{Q\Pi_3/qpoly}$ predicate. Using base case and $\mathsf{Q\Sigma_2=Q\Pi_2}$, we have 
\begin{align}
    \mathsf{Q\Pi}_3/\mathsf{qpoly}&=\mathsf{co\text{-}(Q\Sigma}_3/\mathsf{qpoly)}\subseteq\mathsf{co\text{-}(Q\Sigma}_2/\mathsf{qpoly)}\\
    &=\mathsf{Q\Pi}_2/\mathsf{qpoly}=\mathsf{Q\Sigma}_2/\mathsf{qpoly}.
\end{align}
Thus this predicate can be squeezed to a $\mathsf{Q\Sigma_2/qpoly}$ as follows, where $M_n$ is a $\mathsf{Q\Sigma_2/qpoly}$ verifier and quantum promise language $\mathcal{A}''\in\mathsf{Q\Pi_3/qpoly}$.
\begin{equation}
    (x,\rho_1)\in A_\textnormal{YES}'' \iff \forall\rho_2\exists\sigma_1\forall\sigma_2 : \operatorname{Pr}[N_n(x,\rho_1,\rho_2,\sigma_1,\sigma_2,\ket{\beta_n})=1]\geq2/3.
\end{equation}
\begin{equation}
    (x,\rho_1)\in A''_\textnormal{YES} \iff \exists\rho_1'\forall\sigma_1' : \operatorname{Pr}[M_n(x,\rho_1,\rho_1',\sigma_1',\ket{\gamma_n})=1] \geq 2/3.    
\end{equation}
Substituting back,
\begin{equation}
    x \in A_\textnormal{YES} \iff \exists\rho_1\exists\rho_1'\forall\sigma_1' : \operatorname{Pr}[M_n(x,\rho_1,\rho_1',\sigma_1',\ket{\gamma_n})=1]\geq2/3,    
\end{equation}
which is a $\mathsf{Q\Sigma_2/qpoly}$ predicate with existential proof $\rho_1\otimes\rho_1'$ and universal proof $\sigma_1'$. The soundness condition follows by similar reasoning.

\medskip\medskip
Hence, $\mathsf{Q\Sigma}_k \subseteq \mathsf{Q\Sigma_2}/\mathsf{qpoly}$ for all $k \geq 3$, and the result follows for $k \leq 2$ trivially.
\end{proof}
