% \begin{equation}
%     \exists \sigma_1 \, \forall \sigma_2 : \Pr[N_n(\cdots)] \geq 2/3
% \iff \Pr[R_n(x, \rho_1, \rho_2, |\gamma_n\rangle) = 1] \geq 2/3.
% \end{equation}

% Therefore:
% \begin{equation}
%     x \in L_{\mathrm{YES}} \iff \exists \rho_1 \, \forall \rho_2 : \Pr[R_n(x, \rho_1, \rho_2, |\gamma_n\rangle) = 1] \geq 2/3,    
% \end{equation}
% which is a $\mathsf{Q\Sigma_2}/\mathsf{qpoly}$ predicate. The soundness condition follows by similar reasoning.


\subsection{Bounded-entanglement quantum polynomial hierarchy}

We introduce a variant of the quantum polynomial hierarchy that enforces structural consistency across rounds of interaction, along with an upper bound on the entanglement of the proof state as measured by the von Neumann entropy.

\begin{definition}[Consistent extension property]
\label{def:consistent-extension}
Let $\mathcal{H}_1, \mathcal{H}_2, \ldots, \mathcal{H}_k$ be finite-dimensional Hilbert spaces. A sequence of quantum states $\{\rho_i\}_{i=1}^k$ satisfies the \emph{consistent extension property} if, for each $i \geq 2$, there exists a state $\rho_i$ on $\mathcal{H}_1 \otimes \cdots \otimes \mathcal{H}_i$ such that $\mathrm{Tr}_{\mathcal{H}_i}(\rho_i) = \rho_{i-1}$.
\end{definition}

In a $\mathsf{BEQPH}$ protocol, each prover is required to submit states that satisfy the \emph{consistent extension property}. Specifically, if the prover's $i$-th message is a quantum state on registers $\mathsf{A}_1 \otimes \cdots \otimes \mathsf{A}_i$, then tracing out register $\mathsf{A}_i$ must yield exactly the $(i{-}1)$-th message. In addition, the von Neumann entropy at each round $i$ is upper bounded by a constant $B_i$, where $b_{i-1} < B_{i-1}$. Here, $B_{i-1}$ denotes the maximum entanglement entropy achievable between register $\mathsf{A}_i$ and the joint system $\mathsf{A}' := \mathsf{A}_1 \otimes \cdots \otimes \mathsf{A}_{i-1}$, upon the introduction of $\mathsf{A}_i$ at round $i$. We measure the entanglement between $\mathsf{A}_i$ and $\mathsf{A}'$ using the relative entropy of entanglement, as defined in~\cref{def:ree}.



\begin{definition}[Bounded-entanglement quantum polynomial hierarchy, $\mathsf{BEQPH}^{\mathbf{b}, \mathbf{d}}$]
\label{def:beqph}
Let $c, s : \mathbb{N} \to [0,1]$ be polynomial-time computable functions satisfying $c(n) - s(n) \geq 1/\mathrm{poly}(n)$, where $n = |x|$. A promise problem $\mathcal{A} = (A_{\mathrm{YES}}, A_{\mathrm{NO}})$ belongs to $\mathsf{BEQ\Sigma}_k^{\mathbf{b},\mathbf{d}}(c,s)$ if there exists a polynomial-time uniform family of quantum circuits $\{V_n\}$ such that:
\begin{enumerate}[label=(\roman*)]
    \item \textnormal{(Completeness)} For all $x \in A_{\mathrm{YES}}$, there exists a sequence of quantum proofs satisfying the consistent extension property such that $\exists \rho_1 \, \forall \sigma_1 \, \exists \rho_2 \, \forall \sigma_2 \, \cdots \, Q_k \tau_k :
        \Pr[V_n(\tau_{k-1}, \tau_k) = 1] \geq c(n)$.

    \item \textnormal{(Soundness)} For all $x \in A_{\mathrm{NO}}$, any sequence of proofs satisfying the consistent extension property must satisfy $\forall \rho_1 \, \exists \sigma_1 \, \forall \rho_2 \, \exists \sigma_2 \, \cdots \, \overline{Q}_k \tau_k :
        \Pr[V_n(\tau_{k-1}, \tau_k) = 1] \leq s(n)$.
\end{enumerate}
Here, $\rho_j$ and $\sigma_j$ are chosen from the admissible sets
\[
S_j :=
\begin{cases}
    \left\{
    \rho \in \mathcal{D}(\mathsf{A}_1 \otimes \cdots \otimes \mathsf{A}_j)
    \;\middle|\;
    \begin{array}{l}
    \mathrm{Tr}_{\mathsf{A}_j}(\rho) = \rho_{j-1}, \\[2pt]
    \mathcal{E}_{\mathsf{A}_j, \mathsf{A}'_j}(\rho) \leq b_{j-1} < \max \mathcal{E}_{\mathsf{A}_j, \mathsf{A}'_j}(\rho)
    \end{array}
    \right\} & \textnormal{(Prover A)} \\[12pt]

    \left\{
    \sigma \in \mathcal{D}(\mathsf{B}_1 \otimes \cdots \otimes \mathsf{B}_j)
    \;\middle|\;
    \begin{array}{l}
    \mathrm{Tr}_{\mathsf{B}_j}(\sigma) = \sigma_{j-1}, \\[2pt]
    \mathcal{E}_{\mathsf{B}_j, \mathsf{B}'_j}(\sigma) \leq d_{j-1} < \max \mathcal{E}_{\mathsf{B}_j, \mathsf{B}'_j}(\sigma)
    \end{array}
    \right\} & \textnormal{(Prover B)}
\end{cases}
\]
with $\mathsf{A}'_j := \mathsf{A}_1 \otimes \cdots \otimes \mathsf{A}_{j-1}$ and $\mathsf{B}'_j := \mathsf{B}_1 \otimes \cdots \otimes \mathsf{B}_{j-1}$. The quantifier $Q_k$ is $\exists$ if $k$ is odd and $\forall$ if $k$ is even. All proof states must satisfy the consistent extension property at each round and adhere to the entanglement bounds $\mathbf{b} = \{b_j\}_{j=1}^{k}$ and $\mathbf{d} = \{d_j\}_{j=1}^{k}$. We define
\begin{equation*}
    \mathsf{BEQ\Sigma}^{\mathbf{b},\mathbf{d}}_k := \bigcup_{c,s} \mathsf{BEQ\Sigma}^{\mathbf{b},\mathbf{d}}_k(c,s)
    \quad \text{and} \quad
    \mathsf{BEQPH}^{\mathbf{b},\mathbf{d}} := \bigcup_{k=1}^{\infty} \mathsf{BEQ\Sigma}^{\mathbf{b},\mathbf{d}}_k.
\end{equation*}
In what follows, we will omit the superscripts $\mathbf{b}, \mathbf{d}$ whenever they are clear from context.
\end{definition}

\begin{definition}[Separable quantum polynomial hierarchy]
\label{def:sepqph}
The separable quantum polynomial hierarchy, denoted by $\mathsf{SepQPH}$, is the special case of $\mathsf{BEQPH}^{\mathbf{b}, \mathbf{d}}$ in which all proof states are required to be separable. That is, $\mathsf{SepQPH} := \mathsf{BEQPH}^{\mathbf{0}, \mathbf{0}}$, where $b_i = d_i = 0$ for all $i$.
\end{definition}



% \begin{definition}[Pure-state variant of $\mathsf{CQPH}$ and {$\mathsf{CQ\Sigma}_i$}]
% \label{def:pure_cqph}
% We define the complexity class $\mathsf{pure\text{-}CQPH}$ analogously to $\mathsf{CQPH}$, with the distinction that all quantum proofs are required to be pure states over their respective Hilbert spaces. That is, the verifier must accept a collection of pure quantum states as input proofs, rather than general (possibly mixed) quantum states. Similarly, we define $\mathsf{pure\text{-}CQ\Sigma}_i$ as the variant of $\mathsf{CQ\Sigma}_i$ in which all quantum proofs are restricted to be pure states.
% \end{definition}

\begin{theorem}[Collapse of the bounded-entanglement quantum polynomial hierarchy]
\label{thm:beqph-collapse}
Each level of $\mathsf{BEQPH}$ collapses to a two-round entanglement-bounded convex optimization problem. Moreover, for all $i > 4$, it holds that $\mathsf{BEQ\Sigma}_i = \mathsf{BEQ\Sigma}_4$.
\end{theorem}


\begin{proof}
To show that each level of $\mathsf{BEQPH}$ reduces to a two-round convex optimization problem, we begin by analyzing the case of $\mathsf{BEQ\Sigma}_3$, and then generalize to higher levels.

\medskip

Let the acceptance probability of a $\mathsf{BEQ\Sigma}_3$ protocol be given by the min-max expression
\begin{equation}
\label{eq:mixed_optim_prob}
v^*_3 = \max_{\rho_1 \in \mathcal{D}(\mathsf{A}_1)} \min_{\sigma_1 \in \mathcal{D}(\mathsf{B}_1)} \max_{\rho_2 \in \mathcal{S}(\rho_1)} \operatorname{Tr}(R(\rho_2 \otimes \sigma_1)),
\end{equation}
where $\mathcal{S}(\rho_1)$ denotes the set of consistent extensions of $\rho_1$ under bounded entanglement:
\begin{equation}
    \mathcal{S}(\rho_1) := \left\{ \rho \in \mathcal{D}(\mathsf{A}_1 \otimes \mathsf{A}_2) \;\middle|\; \operatorname{Tr}_{\mathsf{A}_2}(\rho) = \rho_1,\; \mathcal{E}_{\mathsf{A}_2, \mathsf{A}_1}(\rho) \leq b_2 < \max \mathcal{E}_{\mathsf{A}_2, \mathsf{A}_1}(\rho) \right\}.    
\end{equation}

In the absence of entanglement bounds, this reduces to a $\mathsf{QEPH}$ protocol, which is known to collapse to its second level~\cite{grewaljustinqeph}. The set $\mathcal{S}(\rho_1)$ is convex and compact: convexity follows from the convexity of relative entropy, and compactness follows from standard arguments in~\cite{grewaljustinqeph}.

\medskip

Hence, by Sion's minimax theorem (\cref{thm:sion}), the quantifiers can be swapped:
\begin{equation}
    v^*_3 = \max_{\rho_1} \min_{\sigma_1} \max_{\rho_2 \in \mathcal{S}(\rho_1)} \operatorname{Tr}(R(\rho_2 \otimes \sigma_1))
= \max_{\rho_1} \max_{\rho_2 \in \mathcal{S}(\rho_1)} \min_{\sigma_1} \operatorname{Tr}(R(\rho_2 \otimes \sigma_1)).    
\end{equation}
Defining $\mathcal{T}^{(1)}_{\rho,\mathbf{b}} := \left\{ \rho \in \mathcal{D}(\mathsf{A}_1 \otimes \mathsf{A}_2) \;\middle|\; \mathcal{E}_{\mathsf{A}_1, \mathsf{A}_2}(\rho) \leq b_1 < \max \mathcal{E}_{\mathsf{A}_1, \mathsf{A}_2}(\rho) \right\}$, we obtain the simplified form:
\begin{equation}
    v^*_3 = \max_{\rho_2 \in \mathcal{T}^{(1)}_{\rho,\mathbf{b}}} \min_{\sigma_1 \in \mathcal{D}(\mathsf{B}_1)} \operatorname{Tr}(R(\rho_2 \otimes \sigma_1)).    
\end{equation}
This is a single-round convex optimization problem with convex domains and a linear objective, hence efficiently solvable via semidefinite programming.

\medskip

A similar argument yields the expression for $\mathsf{BEQ\Sigma}_4$:
\begin{equation}\label{eq:4level}
    v^* = \max_{\rho_1} \min_{\sigma_1} \max_{\rho_2 \in \mathcal{S}(\rho_1)} \min_{\sigma_2 \in \mathcal{S}(\sigma_1)} \operatorname{Tr}(R(\rho_2 \otimes \sigma_2))
= \max_{\rho_2 \in \mathcal{T}^{(2)}_{\rho,\mathbf{b}}} \min_{\sigma_2 \in \mathcal{T}^{(2)}_{\sigma,\mathbf{d}}} \operatorname{Tr}(R(\rho_2 \otimes \sigma_2)),    
\end{equation}
where the sets are defined as
\begin{align}
    \mathcal{T}^{(1)}_{\rho,\mathbf{b}} &:= \left\{ \rho \in \mathcal{D}(\mathsf{A}_1 \otimes \mathsf{A}_2) \;\middle|\; \mathcal{E}_{\mathsf{A}_1, \mathsf{A}_2}(\rho) \leq b_1 \right\},    \\
    \mathcal{T}^{(1)}_{\sigma,\mathbf{d}} &:= \left\{ \sigma \in \mathcal{D}(\mathsf{B}_1 \otimes \mathsf{B}_2) \;\middle|\; \mathcal{E}_{\mathsf{B}_1, \mathsf{B}_2}(\sigma) \leq d_1 \right\}.
\end{align}

\medskip

For general $i > 2$, the $(i+2)$-th level of $\mathsf{BEQPH}$ reduces to the following convex-concave bilinear minimax problem:
\begin{equation}
\label{eq:general_i}
v^*_{i+2} = \max_{\rho \in \mathcal{T}^{(k)}_{\rho,\mathbf{b}}} \min_{\sigma \in \mathcal{T}^{(l)}_{\sigma,\mathbf{d}}} \operatorname{Tr}\left( R(\rho \otimes \sigma) \right),
\end{equation}
where the parameters $k$ and $l$ are given by
\[
k = l = \frac{i}{2} \quad \text{if } (i+2) \text{ is even}, \qquad
k = \frac{i+1}{2}, \; l = k - 1 \quad \text{if } (i+2) \text{ is odd}.
\]
The feasible set $\mathcal{T}^{(m)}_{\tau,\mathbf{c}}$ denotes the collection of density operators over $\mathsf{R}_1 \otimes \cdots \otimes \mathsf{R}_{m+1}$ with bounded relative entropy of entanglement between the last register $\mathsf{R}_{m+1}$ and the rest:
\[
\mathcal{T}^{(m)}_{\tau,\mathbf{c}} := \left\{ 
\tau \in \mathcal{D}(\mathsf{R}_1 \otimes \cdots \otimes \mathsf{R}_{m+1}) 
\;\middle|\;
\mathcal{E}_{\mathsf{R}_{m+1}, \mathsf{R}_1 \otimes \cdots \otimes \mathsf{R}_m}(\tau) \leq c_{m+1}
\right\},
\]
where $\tau \in \{\rho, \sigma\}$, $\mathbf{c} \in \{\mathbf{b}, \mathbf{d}\}$, and $\mathsf{R} \in \{\mathsf{A}, \mathsf{B}\}$ depending on the prover. We set $\mathcal{T}^{(0)}_{\tau,\mathbf{c}} := \mathcal{D}(\mathsf{R}_1)$.

\medskip

If $b_i = b$ and $d_i = d$ for all $i$, then~\cref{eq:4level} and~\cref{eq:general_i} define equivalent optimization problems. Since the feasible regions are convex and compact, and the objective function is bilinear, the optimal value can be computed by a $\mathsf{BEQ\Sigma}_4$ verifier. Consequently, for all $i > 4$, we obtain $\mathsf{BEQ\Sigma}_i^{\{b\},\{d\}} = \mathsf{BEQ\Sigma}_4^{\{b\},\{d\}}$, where the notation $\{b\}, \{d\}$ indicates that $b_i = b$ and $d_i = d$ for all $i$.
\end{proof}

\begin{corollary}[Equivalence of quantum interactive proof classes at the second level]
\label{cor:hierarchy-equality} $\mathsf{QEPH} = \mathsf{QE\Sigma}_2 = \mathsf{BEQ\Sigma}_2 = \mathsf{Q\Sigma}_2 = \mathsf{QRG}(1)$.
\end{corollary}

\begin{proof}
The equality $\mathsf{QEPH} = \mathsf{QE\Sigma}_2$ follows from~\cite{grewaljustinqeph}. By definition, $\mathsf{BEQ\Sigma}_2 = \mathsf{QE\Sigma}_2 = \mathsf{Q\Sigma}_2$. The equivalence with $\mathsf{QRG}(1)$ follows from the known correspondence between constant-round quantum refereed games and second-level quantum interactive proofs~\cite{qrg1}.
\end{proof}

\begin{corollary}[Collapse of separable quantum polynomial hierarchy]
\label{cor:separable-classes}
The class $\mathsf{SepQPH}$ collapses to a two-round convex optimization problem. Moreover, for all $i > 4$, it holds that $\mathsf{SepQ\Sigma}_i = \mathsf{SepQ\Sigma}_4$.
\end{corollary}

\begin{proof}
This follows directly by setting all entanglement bounds to zero in~\cref{thm:beqph-collapse}, thereby enforcing separability at each round, in accordance with~\cref{def:ree}.
\end{proof}

\begin{corollary}[Separable hierarchies do not simulate the quantum polynomial hierarchy]
\label{cor:sepqph_cant_simulate_qph}
$\mathsf{SepQPH}$ cannot simulate $\mathsf{QPH}$.
\end{corollary}


\begin{proof}
Setting entanglement bounds to zero ensures that all states are separable, forming a convex set. However, the optimization problem for $\mathsf{QPH}$ is generally non-convex, as the set of product states is non-convex. Hence, $\mathsf{SepQPH}$ cannot simulate the full power of $\mathsf{QPH}$.
\end{proof}


\subsection{Structural comparison of hierarchy collapses}

\cref{cor:hierarchy-equality} establishes that the $\mathsf{BEQPH}$ hierarchy can be collapsed to corresponding two-round convex optimization problems, analogous to the collapse of $\mathsf{QEPH}$ to its second level. This demonstrates that constraining the \emph{quality} of relative entropy of entanglement at each round still preserves the tractability of the quantum hierarchy, including the zero-entanglement case. At zero entanglement, we obtain the class $\mathsf{SepQPH}$, whose associated optimization problem is also convex due to the convexity and compactness of the set of separable quantum states. In $\mathsf{QEPH}$, the collapse mechanism relies crucially on the ability of provers to share entanglement across rounds~\cite{grewaljustinqeph}. The structure of games in that setting allows for quantum correlations that effectively ``short-circuit'' higher-level quantifier alternations, collapsing the hierarchy to the second level. Since the second level is expressible as a convex optimization problem, this yields tractability.

In contrast, for the bounded-entanglement version of $\mathsf{QEPH}$, denoted by $\mathsf{BEQPH}$, we do not observe a full collapse to the second level. However, we still achieve tractability at every level: each level of $\mathsf{BEQPH}$ can be effectively reduced to a corresponding two-round max-min optimization problem over convex sets. Moreover, we show that for all $i > 4$, the class $\mathsf{BEQ\Sigma}_i$ has the same formulation as $\mathsf{BEQ\Sigma}_4$, thereby implying an unconditional collapse of the hierarchy to the fourth level. Furthermore, as established in~\cref{cor:separable-classes}, setting the entanglement bounds $\mathbf{b}, \mathbf{d}$ to zero yields the hierarchy $\mathsf{SepQPH}$, in which each of the sets $\mathcal{T}_{\tau,\mathbf{c}}^{(m)}$ consists of separable states over $\mathsf{R}_1 \otimes \cdots \otimes \mathsf{R}_{m+1}$. As shown in~\cref{cor:sepqph_cant_simulate_qph}, this restriction prevents $\mathsf{SepQPH}$ from simulating the full power of $\mathsf{QPH}$, whose optimization problems are generally non-convex. However, if we further restrict the sets $\mathcal{T}_{\tau,\mathbf{c}}^{(m)}$ to contain only pure product states, we can in fact simulate $\mathsf{QPH}$—a fact that is essentially \emph{trivial} to verify.



\paragraph{Implications for quantum complexity theory.}
Our results offer a refined perspective on the structure of the quantum entangled polynomial hierarchy. While the unconditional collapse of $\mathsf{QEPH}$ to its second level has been attributed to the unbounded entanglement permitted between rounds, we show that introducing upper bounds on the allowed relative entropy of entanglement at each round still yields a form of structural simplification. In particular, the bounded-entanglement quantum polynomial hierarchy retains tractability at every level: although it does not collapse completely to the second level, each level reduces to a two-round convex optimization problem.

When the entanglement bounds are set to zero, we obtain the separable quantum polynomial hierarchy, where all intermediate states are separable across rounds. In this regime, the computational simplicity of $\mathsf{BEQPH}$ persists, though $\mathsf{SepQPH}$ is strictly more computationally expressive than $\mathsf{QEPH}$, as it does not collapse unconditionally to its second level. Nonetheless, both $\mathsf{SepQ\Sigma_2}$ and $\mathsf{SepQ\Sigma_3}$ remain tractable, as the corresponding optimization problems are convex and hence efficiently solvable via semidefinite programming.


    % The collapse of $\mathsf{CQPH}$ through classical optimization techniques, as opposed to quantum entanglement, suggests that certain aspects of quantum complexity may be more amenable to classical analysis than previously thought. This observation could inform the design of new quantum protocols and provide insight into the fundamental limits of quantum advantage in interactive settings.

\section{Open problems and future directions}
Our results naturally lead to several intriguing open questions that we believe merit further investigation. We organize these into two main categories corresponding to our primary contributions.

\subsection{Uniqueness in quantum-classical probabilistically checkable proofs}
The equivalence $\mathsf{UniqueQCPCP} = \mathsf{QCPCP}$ established in~\cref{sec:uqcpcp_eq_qcpcp} opens several natural avenues for future research, particularly concerning the robustness of this collapse and its extensions to broader quantum proof systems.

\paragraph{Relation between \(\mathsf{QPCP}\) and \(\mathsf{UniqueQPCP}\).} 
A natural question arising from our work is whether similar results hold in the quantum proof setting as well. 
Currently, the only known result is a quantum oracle separation between \(\mathsf{UniqueQMA}\) and \(\mathsf{QMA}\), shown in~\cite{anshu2024uniqueqmavsqmaoracle}, 
which itself appears to be a highly nontrivial and challenging problem.


\paragraph{Stronger reductions for the $\mathsf{UniqueQCPCP} = \mathsf{QCPCP}$ equivalence.}
    A natural direction is to investigate whether this equivalence remains true under stronger or more restricted reduction models. Our proof relies on $\mathsf{BQ}$-operator and randomized reductions, but it would be interesting to establish the equivalence under $\mathsf{BQP}$-truth-table reductions (i.e., non-adaptive quantum polynomial-time reductions), or even deterministic polynomial-time reductions. Establishing this would demonstrate that the collapse to $\mathsf{UniqueQCPCP}$ holds under more conservative assumptions about how the reduction accesses the verifier. Conversely, proving a separation would highlight fundamental structural distinctions between the two systems that are obscured by more powerful reduction models.

\paragraph{Extension to multi-prover and entangled variants.}
    Another compelling direction is to investigate whether the equivalence between $\mathsf{UniqueQCPCP}$ and $\mathsf{QCPCP}$ extends to broader classes of quantum proof systems. For instance, in the multi-prover setting, does a similar collapse hold between uniqueness and generality for $\mathsf{MIP}^*$-style variants of $\mathsf{QCPCP}$, where the verifier interacts with multiple (possibly entangled) provers? In such settings, uniqueness constraints may behave quite differently due to entanglement and non-local correlations, making it unclear whether the collapse still holds. Moreover, the notion of ``uniqueness'' itself becomes more subtle when multiple provers are involved. Exploring these extensions could yield new insights into the role of entanglement and prover non-locality in quantum PCP constructions.

\paragraph{Parallel repetition for $\mathsf{UniqueQCPCP}$.}
    In classical PCP theory, parallel repetition theorems are crucial for amplifying soundness while preserving completeness~\cite{Raz1998}. A natural question is whether there exists a quantum analogue of the parallel repetition theorem for $\mathsf{UniqueQCPCP}$ systems. Specifically, if a quantum verifier checks multiple independent copies of a $\mathsf{UniqueQCPCP}$ proof in parallel, does the soundness error decrease exponentially with the number of repetitions while completeness remains unaffected? Such a result would significantly amplify the reliability of $\mathsf{UniqueQCPCP}$ verifiers and could potentially be used to derive stronger quantum hardness-of-approximation results. However, the quantum setting presents unique challenges: entangled cheating strategies across multiple proof copies and the delicate structure of quantum measurements may disturb classical intuitions, making the existence of such a theorem highly non-trivial and potentially impactful.

\subsection{Structure of the quantum polynomial hierarchy}
Our investigation of $\mathsf{QPH}$ and its entanglement-bounded variant $\mathsf{BEQPH}$, presented in~\cref{sec:qph}, reveals a rich structure that invites further exploration. Several fundamental questions remain open regarding the relationships between these hierarchies and other quantum complexity classes.

\paragraph{Towards a uniform Karp–Lipton theorem for $\mathsf{QPH}$.}
    One of the most significant open questions in quantum complexity theory is whether there exists a uniform (advice-free) Karp–Lipton collapse theorem for $\mathsf{QPH}$. Our non-uniform result shows that $\mathsf{QMA} \subseteq \mathsf{BQP}/\mathsf{qpoly}$ implies $\mathsf{QPH} \subseteq \mathsf{Q\Sigma}_2/\mathsf{qpoly}$, but the uniform case remains elusive. A uniform collapse would require showing that $\mathsf{QMA} \subseteq \mathsf{BQP}$ implies $\mathsf{QPH} \subseteq \mathsf{Q\Sigma}_2$. Such a result currently seems out of reach, as it would likely imply $\mathsf{QMA}(2) \subseteq \mathsf{PSPACE}$ proving which appears beyond the scope of existing techniques~\cite{qph_original}.

\paragraph{Relating $\mathsf{QPH}$ to other quantum complexity classes.}
    A fundamental research direction is to better understand how various levels of $\mathsf{QPH}$ relate to other well-studied quantum complexity classes such as $\mathsf{QRG}(2)$, $\mathsf{PSPACE}$, $\mathsf{QMA}(2)$, $\mathsf{QMA}$, and $\mathsf{QCMA}$. Of particular interest is whether any level of $\mathsf{QPH}$ captures the full computational power of $\mathsf{PSPACE}$. While we know that $\mathsf{QPH} \subseteq \mathsf{PSPACE}$ by definition, the reverse inclusion remains a tantalizing open problem that would provide a complete characterization of quantum hierarchical proof systems.

% \paragraph{Full collapse and connections between $\mathsf{BEQPH}$ and $\mathsf{QRG}(2)$.} 
%     Given our result that all levels above four in the bounded-entanglement quantum polynomial hierarchy collapse to the fourth level, an important open question is whether a stronger collapse to the second level is possible. If such a collapse were established, we would obtain $\mathsf{BEQPH} = \mathsf{BEQ\Sigma_2} = \mathsf{QRG}(1)$, indicating a complete alignment between bounded-entanglement interactive proof systems and constant-round quantum refereed games. Further investigation into the connection between $\mathsf{BEQPH}$ and two-round quantum refereed games, known to be equivalent to $\mathsf{PSPACE}$, may yield new insights into the computational gap between $\mathsf{QRG}(1)$ and $\mathsf{QRG}(2)$.

\paragraph{Formal containment of $\mathsf{BEQPH}$ in $\mathsf{QPH}$.}
    Another central open problem is to determine whether the class $\mathsf{BEQPH}$, defined by its consistent proof structure and bounded entanglement, is strictly contained within the general quantum polynomial hierarchy. We conjecture that $\mathsf{BEQPH} \subsetneq \mathsf{QPH}$ and $\mathsf{SepQPH} \subsetneq \mathsf{QPH}$, as the structural constraints and the collapse to the fourth level observed in $\mathsf{BEQPH}$ suggest a significant reduction in expressive power. However, establishing such a separation formally remains challenging, due to the inherent difficulty of characterizing the full complexity of $\mathsf{QPH}$.


\paragraph{Comparison with oracular quantum hierarchies.}
    An intriguing direction for future work is to compare the bounded-entanglement quantum polynomial hierarchy  with oracular quantum hierarchies, such as the iterated quantum Merlin-Arthur hierarchy $\mathsf{QMAH} := \mathsf{QMA}^{\mathsf{QMA}^{\mathsf{QMA}^{\cdots}}}$, where the $\mathsf{QMA}$ oracle is applied polynomially many times. It remains an open question whether the structural consistency constraints and entanglement bounds imposed in $\mathsf{BEQPH}$ make it as computationally powerful as $\mathsf{QMAH}$, or whether the iterated access to $\mathsf{QMA}$ oracles provides strictly greater computational power. As noted in~\cite{grewaljustinqeph}, resolving this question could shed light on the internal structure of $\mathsf{QRG}(1)$. Since our work establishes $\mathsf{BEQPH} \subseteq \mathsf{QRG}(1)$ and it is known that $\mathsf{QMAH} \subseteq \mathsf{CH}$~\cite{Vinkhuijzen2018}, a proof of the containment $\mathsf{BEQPH} \subseteq \mathsf{QMAH}$ would imply that $\mathsf{QRG}(1) \subseteq \mathsf{CH}$ as well, thereby placing tighter constraints on the computational power of constant-round quantum refereed games.



