\begin{tcolorbox}[width=\textwidth, colback=gray!5!white, colframe=black!75!black, title=Prompt Used for Classification Task (AlgebraNation)]
\small
\textbf{System:} You are a math teacher who tutors student on a variety of problems.

\textbf{Dialogue ID: 10520899}

\textbf{Task:} Classify the last tutor move into one or more of the following categories: \textit{confirmatory\_feedback}, \textit{negative\_feedback}, \textit{correcting}, \textit{giving\_instruction}, \textit{giving\_explanation}, \textit{providing\_further\_references}, \textit{questioning}, \textit{asking\_for\_elaboration}, \textit{praising\_and\_encouraging}, \textit{managing\_frustration}, \textit{managing\_discussions}, \textit{giving\_answers}, \textit{encouraging\_peer\_tutoring}, \textit{guiding\_peer\_tutoring}, \texttt{acknowledging\_tutor\_issue}, and \textit{other}. These categories are described below:

\begin{itemize}
  \item \textbf{confirmatory\_feedback:} Whether a reply provides confirmatory feedback about an answer's correctness.
  \item \textbf{negative\_feedback:} Whether a reply states that an answer is incorrect.
  \item \textbf{correcting:} Whether a reply addresses errors in the student's problem-solving approach.
  \item \textbf{giving\_instruction:} Whether a reply breaks down a task, performs a part, or initiates a task for the student to complete.
  \item \textbf{giving\_explanation:} Whether a reply explains concepts, principles, or provides additional information.
  \item \textbf{providing\_further\_references:} Whether a reply includes additional resources or references related to the topic.
  \item \textbf{questioning:} Whether a reply asks questions to stimulate thought or constructive discussion.
  \item \textbf{asking\_for\_elaboration:} Whether a reply requests further details or explanation from the student.
  \item \textbf{praising\_and\_encouraging:} Whether a reply praises or encourages the student for their efforts or successes.
  \item \textbf{managing\_frustration:} Whether a reply addresses the student's negative emotions or frustration.
  \item \textbf{managing\_discussions:} Whether a reply organizes the flow of discussion or adjusts the direction of inquiry.
  \item \textbf{giving\_answers:} Whether a reply directly provides an answer to the posed question.
  \item \textbf{encouraging\_peer\_tutoring:} Whether a reply promotes tutoring interactions among peers.
  \item \textbf{guiding\_peer\_tutoring:} Whether a reply provides feedback on peer tutoring interactions.
  \item \textbf{acknowledging\_tutor\_issue:} Whether the tutor expresses uncertainty in their reply.
  \item \textbf{other:} Binary indicator for tutoring strategies not classified under the existing labels.
\end{itemize}

