	\section{Preliminaries}\label{prelim}
	This section is the recap of some definitions and few notations that we used throughout in this paper. We define $\GG(\VV, \EE)$ as the graph with the set of vertices $\VV$ and the set of edges $\EE$, where $|\VV|=n$ and $|\EE|=m$. The size of the knapsack and the target value are represented as $s$ and $d$ respectively. The weight and profit of a vertex $u\in\VV$ are denoted as $w(u)$ and $\alpha(u)$ respectively. We denote the closed interval $[1,n]=\{x\in\mathbb{Z}:1\leq x \leq n\}$.

	\begin{definition}[\dos]\label{dos}
		Given a graph $\GG=(\VV,\EE)$ and a positive integer $k$, compute if there exists a subset $\VV' \subseteq \VV$ such that every vertex of $\VV'$ is adjacent with all the vertices of $\VV$ and $|\VV'|\leq k$. We denote an arbitrary instance of \dos by $(\GG,k)$.
	\end{definition}



	\begin{definition}[\vc]\label{vc}
		Given a graph $\GG=(\VV,\EE)$ and a positive integer $k$, compute if there exists a subset $\VV' \subseteq \VV$ such that at least one end point of every edge belongs to $\VV'$ and $|\VV'|\leq k$. We denote an arbitrary instance of \vc by $(\GG,k)$.
	\end{definition}
	\begin{definition}[\kp]
		Given a set $\XX=[1,n]$ of $n$ items with sizes $\theta_1,\ldots,\theta_n,$ values $p_1,\ldots,p_n$, capacity $b$ and target value $q$, compute if there exists a subset $\II \subseteq \XX$ such that $\sum_{i\in \II} \theta_i \leq b$ and $\sum_{i\in \II} p_i \geq q$. We denote an arbitrary instance of \kp by $(\XX,(\theta_i)_{i\in\XX}, (p_i)_{i\in\XX}, b,q)$.
	\end{definition}

	\begin{definition}[\vcknapsack]\label{def:vckp}

		Given an undirected graph $\GG=(\VV,\EE)$,  weight and profit of vertices are defined as the functions $w:\VV \rightarrow \mathbb{Z}_{\geq 0} $ and $\alpha:\VV \rightarrow \mathbb{R}_{\geq 0} $ respectively, size $s(\in \mathbb{Z^+})$ of the knapsack and target value $d(\in \mathbb{R^+})$, compute if there exists a subset $\UU\subseteq\VV$ of vertices such that:
		\begin{enumerate}
			\item \UU is a \vc,
			\item $\sum_{u\in\UU} w(u) \le s$,
			\item $\sum_{u\in\UU} \alpha(u) \ge d$.
		\end{enumerate}
		We denote an arbitrary instance of \dosknapsack by $(\GG,(w(u))_{u\in\VV},(\alpha(u))_{u\in\VV},s,d)$.

	\end{definition}


	%\begin{theorem}\label{thm:dos-W[2]-Complete}(~\cite{niedermeier2006invitation})
	%\dos is $W[2]$-complete parameterized by solution size.
	%\end{theorem}


	\begin{definition}[\udos]\label{udos}
		Given a graph $\GG=(\VV,\EE)$ and a positive integer $k$, compute if there exists a subset $\VV' \subseteq \VV$ such that $\VV'$ is a \dos of size at least $k$ i.e., $|\VV'|\geq k$. We denote an arbitrary instance of ~\udos by $(\GG,k)$.
	\end{definition}

	Maximum cardinality among all Minimal \dos problem or Upper Domination (UD) (denoted as $\Gamma(\GG)$) problem is \NPC (Th 4.4)~\cite{cheston1990computational}. UD is polynomial time solvable for Bipartite graphs (Th 5)~\cite{cockayne1981contributions},(Th 7)~\cite{jacobson1990chordal} and Chordal graphs (Th 9)~\cite{jacobson1990chordal}. Thus it indicates that some times finding max-min problem is more 'easy' than the finding of minimization problem.\\

	\noindent
	We define \td, \ntd and \tw as follows (see ~\cite{alber2002fixed}):
	\begin{definition}[\td]\label{def:td}

		Given a graph $\GG=(\VV,\EE)$. The set of vertices $\chi=\{X_i\}_{i\in V}$, where each $X_i\subseteq \VV$ is called a bag such that $T=(V, E)$ is a tree structure for the graph $\GG$ with $i$ as the nodes of $~T$. We define a \td $T^\chi$ of $~\GG$ having the following properties:
		\begin{itemize}
			\item[$\bullet$] $\bigcup\limits_{i\in V}X_i= \VV$.
			\item[$\bullet$] For each edge $e=\{v_1,v_2\} \in \EE$ there must be a bag $X_k$ such that $\{v_1,v_2\} \subseteq X_k$, where $k=|V|$.
			\item[$\bullet$] If a node $j$ lies on the path between the nodes $i$ and $k$, then $X_i \cap X_k\subseteq X_j $, which means that the set $\{i, j, k\}$ induces a connected subtree of $~T$,  $\forall~ i, j, k \in V$.
		\end{itemize}
		We denote an arbitrary instance of ~\td $T^\chi$ of~ $~\GG$ by the pair $\langle \chi, T \rangle$. The \textbf{width} of~ $T^\chi$ is equal to $\max_{i\in V}|X_i| -1$ and the \textbf{treewidth}$(tw)$ holds the minimum width value among all $T^\chi$ of~ $\GG$.
	\end{definition}
	From later on, we use the term 'vertices' for the vertices of the graph $\GG$ and 'nodes' for the vertices of $~T$.
	\begin{definition}[\ntd]\label{def:ntd}
		A \td $T^\chi_r$ rooted at a node $r$ is called a \ntd if the following properties holds:
		\begin{itemize}
			\item[$\bullet$] Every node of $~T$ has at most two children.
			\item[$\bullet$] A node with no children is called \textbf{leaf node}. 
			\item[$\bullet$] A node $i$ with one child $j$ is either called\\ 
			(i) \textbf{insert $\backslash$ introduce node} if ~$X_i=X_j\setminus\{v\} $ and $|X_i|=|X_j|+1$ or \\
			(ii) \textbf{forget node} if~ $X_j=X_i\setminus\{v\}$ and $|X_j|=|X_i|+1$ , where $v\in \VV$.
			\item[$\bullet$] A node $i$ with two children $j$ and $k$ is called \textbf{join node} if~ $X_i=X_j=X_k$.
		\end{itemize}

	\end{definition}
	\begin{lemma}\label{lm:ntd}(\cite{kloks1994treewidth})
		If the \td of width $k$ and $\OO(n)$ nodes are given for a graph $\GG$ with $n$ vertices, one can transform it into a \ntd of width  $k$ in time $\OO(n)$ having $\OO(n)$ number of nodes. 
	\end{lemma}
	For the proof we refer lemma 13.1.3~\cite{kloks1994treewidth}.
	\begin{definition}[\fsc]\label{def:fsc}(\cite{bjorklund2007fourier})
		Let ~$f,g :2^\VV \rightarrow \mathbb{Z}$ be two functions defined on latice of subsets on vertex set $V$, the \textit{subset convolution} function $(f*g) :2^\VV \rightarrow \mathbb{Z}$ is defined on every subset $Y\subseteq V$  as
		$(f*g)(Y)=\sum_{X\subseteq Y}f(X)g(Y\setminus X )$. 

	\end{definition}
	The \fsc is widely used to improve the running time bound for different algorithms, like,parameterized algorithms. Any straightforward algorithms takes $\OO(3^n)$ time to compute the additions and multiplications for the \textit{subset convolution} function, whereas the following lemma is an improvement of the running time.
	\begin{lemma}(\cite{cygan2015parameterized})
		For two fiven functions ~$f,g :2^\VV \rightarrow \mathbb{Z}$ on latice of subsets on vertex set $V$, then all $2^{|\VV|}$ subset of \textit{subset convolution} function $(f*g) :2^\VV \rightarrow \mathbb{Z}$ computed by arithmetic operations in time $\OO(2^{|\VV|}\cdot |\VV|^3)$.
	\end{lemma}


	\begin{definition}[\ETH]\label{def:eth}
		\ETH states that there exists an algorithm solving 3-SAT problem in time $\OO^*(2^{cn})$, where $\delta_3(>0)$ is the infimum of the set of constants $c$. Equivalently, there is no sub-exponential $2^{o(n)}$time algorithm for 3-SAT problem.
	\end{definition}
	\begin{definition}[\wcs]\label{def:wcs}
		Given a circuit $\CC$ and a positive integer $k$, compute if there exists a satisfying assignment with weight exactly $k$. We denote an arbitrary instance of \wcs(WCS) as $(\CC,k)$.
	\end{definition}
	\begin{definition}[\wh]\label{def:w-hierarchy} 
		A parameterized problem $P$ is in the class $W[t]$ if there is a parameterized reduction form $P$ to $WCS_{(t,d)}$, where $t\geq 1$ for some $d\geq 1$. $d$ denotes the depth of the circuit and $t$ (weft) denotes the maximum number of large nodes (nodes with indegree $> 2$) on a path from input to the output node.
	\end{definition}

