	\section{\textbf{Our Problem Definitions}}\label{sec:prob-def}
	We define our problem here formally. They are as follows:

	\begin{definition}[\dosknapsack]\label{def:doskp}

		Given an undirected graph $\GG=(\VV,\EE)$,  weight and profit of vertices are defined as the functions $w:\VV \rightarrow \mathbb{Z}_{\geq 0} $ and $\alpha:\VV \rightarrow \mathbb{R}_{\geq 0} $ respectively, size $s(\in \mathbb{Z^+})$ of the knapsack and target value $d(\in \mathbb{R^+})$, compute if there exists a subset $\UU\subseteq\VV$ of vertices such that:
		\begin{enumerate}
			\item \UU is a \dos,
			\item $\sum_{u\in\UU} w(u) \le s$,
			\item $\sum_{u\in\UU} \alpha(u) \ge d$.
		\end{enumerate}
		We denote an arbitrary instance of \dosknapsack by $(\GG,(w(u))_{u\in\VV},(\alpha(u))_{u\in\VV},s,d)$.

	\end{definition}

	\dos problem is strongly \NPC as the reduction is done from \vc \cite{DBLP:conf/stoc/GareyJS74}. For proving \NP-completeness of \dosknapsack we reduce \dos to \dosknapsack. 

	\begin{definition}[\kdosknapsack]\label{def:kdoskp}

		Given an undirected graph $\GG=(\VV,\EE)$,  weight and profit of vertices are defined as the functions $w:\VV \rightarrow \mathbb{Z}_{\geq 0} $ and $\alpha:\VV \rightarrow \mathbb{R}_{\geq 0} $ respectively, size $s(\in \mathbb{Z^+})$ of the knapsack, target value $d(\in \mathbb{R^+})$ and $k \in  \mathbb{Z^+} $, compute if there exists a subset $\UU\subseteq\VV$ of vertices such that:
		\begin{enumerate}
			\item \UU is a \dos of size $k$,
			\item $\sum_{u\in\UU} w(u) \le s$,
			\item $\sum_{u\in\UU} \alpha(u) \ge d$.
		\end{enumerate}
		We denote an arbitrary instance of \dosknapsack by $(\GG,(w(u))_{u\in\VV},(\alpha(u))_{u\in\VV},s,d,k)$.



		\begin{definition}[\minimaldosknapsack]\label{thm:minimaldoskp-npc}

			Given an undirected graph $\GG=(\VV,\EE)$,  weight and profit of vertices are defined as the functions $w:\VV \rightarrow \mathbb{Z}_{\geq 0} $ and $\alpha:\VV \rightarrow \mathbb{R}_{\geq 0} $ respectively, size $s(\in \mathbb{Z^+})$ of the knapsack, target value $d(\in \mathbb{R^+})$ and $k \in  \mathbb{Z^+} $, compute if there exists a subset $\UU\subseteq\VV$ of vertices such that:
			\begin{enumerate}
				\item \UU is a Minimal \dos,
				\item $\sum_{u\in\UU} w(u) \le s$,
				\item $\sum_{u\in\UU} \alpha(u) \ge d$.
			\end{enumerate}
			We denote an arbitrary instance of \dosknapsack by $(\GG,(w(u))_{u\in\VV},(\alpha(u))_{u\in\VV},s,d,k)$.

		\end{definition}



		Maximum cardinality among all Minimal \dos problem or Upper Domination (UD) problem is \NPC ~\cite{cheston1990computational} and denoted as $\Gamma(\GG)$.


		\section{\textbf{Results on Classical NP-hardness }}\label{Sec: Res-C-NPH}
		\begin{theorem}\label{thm:doskp-npc}
			\dosknapsack is strongly \NPC.\textcolor{red}{~[Finalized]}
		\end{theorem}

		\begin{proof}
			Clearly, \dosknapsack $\in$ \NP. Let us construct the following instance $(\GG^\pr(\VV^\pr=\{u_i: i\in[1,n]\},\EE^\pr),(w(u))_{u\in\VV^\pr},(\alpha(u))_{u\in\VV^\pr},s,d)$ of \dosknapsack from an given arbitrary instance  $(\GG(\VV=\{v_i: i\in [1,n]\},\EE),k)$ of \dos of size $k$.
			\begin{align*}
				&\VV^\pr = \{u_i : v_i\in \VV, \forall i\in[1,n]\}\\
				&\EE^\pr = \{\{u_i,u_j\}: \{v_i, v_j\} \in\EE, i\neq j, \forall i, j\in[1,n]\}\\
				&w(u_i) = 1, \alpha(u_i)=1 \qquad \forall i\in[1,n]\\
				&s =d = k
			\end{align*}
			The \dosknapsack problem has a solution iff \dos has a solution.\\

			\noindent
			Let $(\GG^\pr,(w(u))_{u\in\VV^\pr},(\alpha(u))_{u\in\VV^\pr},s,d)$ be an instance of \dosknapsack such that $\WW^\pr$ be the resulting subset of $\VV^\pr$ with (i) $\WW^\pr$ is a \dos, (ii) $\sum_{u\in \WW^\pr} w(u) = k$, (iii) $\sum_{u\in \WW^\pr} \alpha(u) = k$\\
			\noindent
			This means that the set $\WW^\pr$ is a \dos which gives the maximum profit $k$ for the bag capacity of size $k$. In other words, $\WW^\pr$ is a \dos of size $k$, as $\sum_{u\in \WW^\pr} w(u) = \sum_{u\in \WW^\pr} \alpha(u) = k$. Since $\WW' =\{u_i: v_i \in \WW, \forall i \in[1,n]\}$, $\WW$ is a \dos of size $k$. Therefore, the \dos instance is an \yes instance.\\

			\noindent
			Conversely, let us assume that \dos instance $(\GG,k)$ is an \yes instance.\\ 
			Then there exists a subset $\WW\subseteq \VV$  of size $k$ such that it outputs a \dos. \\	
			\noindent
			Consider the set $\WW^\pr=\{u_i: v_i \in \WW, \forall i \in[1,n]\}$.
			Since each vertex of $\WW^\pr$ is involved with weight 1 and produces profit amount 1, $\WW^\pr$ is a \dos of max bag size and total profit $k$. 
			\noindent
			Therefore, the \dosknapsack instance is an \yes instance.\\
		\end{proof}



		\begin{theorem}\label{thm:kdoskp-npc}
			\kdosknapsack is strongly \NPC. %\textcolor{red}{~[Finalized]}
		\end{theorem}

		\begin{proof}
			Clearly, \kdosknapsack $\in$ \NP. Let us construct the following instance $(\GG^\pr(\VV^\pr=\{u_i: i\in[1,n]\},\EE^\pr),(w(u))_{u\in\VV^\pr},(\alpha(u))_{u\in\VV^\pr},s,d, k')$ of \kdosknapsack from an given arbitrary instance  $(\GG(\VV=\{v_i: i\in [1,n]\},\EE),k)$ of \dos of size $k$.
			\begin{align*}
				&\VV^\pr = \{u_i : v_i\in \VV, \forall i\in[1,n]\}\\
				&\EE^\pr = \{\{u_i,u_j\}: \{v_i, v_j\} \in\EE, i\neq j, \forall i, j\in[1,n]\}\\
				&w(u_i) = 1, \alpha(u_i)=1 \qquad \forall i\in[1,n]\\
				&s =d = k' =k
			\end{align*}
			The \kdosknapsack problem has a solution iff \dos has a solution.\\

			\noindent
			$(\GG^\pr(\VV^\pr,\EE^\pr),(w(u))_{u\in\VV^\pr},(\alpha(u))_{u\in\VV^\pr},s,d,k')$ of \kdosknapsack such that $\WW'$ be the resulting subset of $\VV'$ with (i) $\WW'$ is a \dos of size $k'$, (ii) $\sum_{u\in \WW'} w(u) \leq s = k' $, (iii) $\sum_{u\in \WW'} \alpha(u) \geq d = k'$.\\
			\noindent
			This means that the set $\WW'$ is a \dos which gives the maximum profit $k'$ for the bag capacity of $k'$.  Now, since $k'=k$ and $\WW' =\{u_i: v_i \in \WW, \forall i \in[n]\}$ , we can say that  $\WW$ is a \dos of size $k$. Therefore, the \dos instance is an \yes instance.\\

			\noindent
			Conversely, let us assume that \dos instance $(\GG,k)$ is an \yes instance.\\ 
			Then there exists a subset $\WW\subseteq \VV$  of size $k$ such that it outputs a \dos. \\	
			\noindent
			Since $\WW' =\{u_i: v_i \in \WW, \forall i \in[n]\}$ and each vertex of $\WW'$ is involved with weight 1 and produces profit amount 1 in the reduced graph $\GG'$, $\WW'$ is a \dos of max bag size and total profit $k$. Also we have, $k=k'$.
			Therefore, the \kdosknapsack instance is an \yes instance.\\
