		\begin{theorem}\label{thm:doskp-bipt-npc}
			\dosknapsack is strongly \NPC even when the instances are restricted to a bipartite graph. \textcolor{red}{~[Need verification by sir]} %\textcolor{red}{~[Finalized]}
		\end{theorem}

		\begin{proof}
			We already proved that \dosknapsack is \NPC for general graph. Now we reduce an arbitrary instance of general graph $(\GG(\VV,\EE),(w(u))_{u\in\VV},(\alpha(u))_{u\in\VV}, s, d)$ for \dosknapsack to the instance of a bipartite graph $(\BB(\hat{\VV},\hat{\EE}),(w(v))_{v\in\hat{\VV}},(\alpha(v))_{v\in\hat{\VV}}, \hat{s}, \hat{d})$ for \dosknapsack. The reduction is as follows:  %with \dosknapsack of size $\leq s$ to the instance of a bipartite graph $(\BB(\hat{\VV},\hat{\EE}),(w(v))_{v\in\hat{\VV}},(\alpha(v))_{v\in\hat{\VV}})$ that also has a \dosknapsack of size $\leq s+1$. 
			\begin{align*}
				&\hat{\VV} = X \cup Y \cup \{z\}\\  
				&X=\{v_i : u_i\in \VV, \forall i\in[1,n]\}\\
				&Y=\{v_i' : u_i\in \VV, \forall i\in[1,n]\}\\
				&\hat{\EE} = \{\{v_i,v_i'\}\cup \{\{v_i, v_j'\}\cup \{v_i', v_j\}:\{u_i,u_j\} \in\EE\} \cup  \{z,v_i'\}: i\neq j, \forall i, j\in[1,n]\}\\
				&w(v_i)=0, \alpha(v_i)=0 \quad \forall i\in[1,n]\\
				&w(v_i')=w(u_i), \alpha(v_i')=\alpha(u_i)  \quad \forall i\in[1,n]\\
				&w(z) = 0, \alpha(z)=0\\
				&\hat{s}=s, \hat{d}=d
				%\{\alpha(v_k): \alpha(v_k)>\alpha(v_i), i\neq k, \forall i, k\in[1,n]\}
			\end{align*}


			Now, we can proof that the arbitrary graph $\GG$ has a solution for \dosknapsack iff the corresponding bipartite graph $\BB$ has a solution for \dosknapsack.\\
			\noindent
			Suppose \dosknapsack for is \yes instance for general graph $\GG$. That means $\GG$ has a \dosknapsack $\WW \subseteq \VV$ such that $\sum_{u\in \WW} w(u)\leq s$ and  $\sum_{u\in \WW} \alpha(u) \geq d$. Let $\hat{\WW}(\subseteq \hat{\VV})=\{v_i' : u_i\in \WW\}\cup \{z\}$  is the \dos in $\BB$, as $\{v_i' : u_i\in \WW\}$ dominates all the vertices of $X$ and $z$ dominates all the vertices of $Y$ and itself. Now,
			\[\sum_{v\in \hat{\WW}} w(v) = w(z) + \sum_{u\in\WW} w(u) \leq s =\hat{s}, \quad \text{since} \quad w(z) = 0\]
			\[\sum_{v\in \hat{\WW}} \alpha(v) = \alpha(z)+ \sum_{u\in\WW} \alpha(u) \geq d =\hat{d},\quad \text{since} \quad \alpha(z) = 0\]
			Hence, \dosknapsack is \yes instance for bipartite graph $B$.\\

			Conversely, let \dosknapsack has \yes instance for the bipartite graph $B$ and $\hat{\WW}$ be any of its arbitrary solution such that $\sum_{v\in \hat{\WW}} w(v)\leq \hat{s}$ and  $\sum_{v\in \hat{\WW}} \alpha(v) \geq \hat{d}$. Without loss of generality, let $X\cap \hat{\WW} \neq \phi $ and/or $Y\cap \hat{\WW} \neq \phi $. Then choose the vertices $u_i$ from $\VV$ of $\GG$ corresponding to $v_i\in X\cap \hat{\WW}$ and/or $v_i'\in Y\cap \hat{\WW}$ from $\BB$, for some $i\in[1,n]$. Let $\WW=\{u_i:v_i\in (X\cap \hat{\WW}) \text{~or~} v_i'  (Y\cap \hat{\WW}) \text{~or both}, \text{~for some~} i\in[1,n] \} \subseteq \VV$. Then,
			\[\sum_{u\in\WW} w(u)=\sum_{v\in \hat{\WW}} w(v) \leq \hat{s}  =s,\]
			\[\sum_{u\in\WW} \alpha(u)=\sum_{v\in \hat{\WW}} \alpha(v) \geq \hat{d}=d\]

			Therefore,  \dosknapsack is \yes instance for general graph $\GG$.
		\end{proof}

