		\begin{theorem}\label{thm:doskp-FPT-reduction} 
			There is a parameterized reduction from \dos to \dosknapsack \textcolor{red}{~[Finalized]}
		\end{theorem}

		\begin{proof}
			Let $(\GG(\VV=\{v_i: i\in [1,n]\},\EE),k)$ be an instance of parameterized problem \dos of size $k$. Now, we construct the instance $((\GG^\pr(\VV^\pr=\{u_i: i\in[1,n]\},\EE^\pr),(w(u))_{u\in\VV^\pr},(\alpha(u))_{u\in\VV^\pr},s,d),k')$ of  \dosknapsack parameterized by $k'$ as follows: 
			\begin{align*}
				&\VV^\pr = \{u_i : v_i\in \VV, \forall i\in[1,n]\}\\
				&\EE^\pr = \{\{u_i,u_j\}: \{v_i, v_j\} \in\EE, i\neq j, \forall i, j\in[1,n]\}\\
				&w(u_i) = 1, \alpha(u_i)=1 \qquad \forall i\in[1,n]\\
				&s =d = k'= k
			\end{align*}
			$\bullet$ This computation to get the output instance works in polynomial time.\\ 
			$\bullet$ The parameter $k'$ is upper bounded by some computable function $f$ of k as here, $f(k)=k$.\\
			$\bullet$ Now we need to show the \dosknapsack is an \yes-instance iff \dos is an \yes-instance.\\
			Let $((\GG^\pr(\VV^\pr=\{u_i: i\in[1,n]\},\EE^\pr),(w(u))_{u\in\VV^\pr},(\alpha(u))_{u\in\VV^\pr},s,d),k')$ be an instance of the parameterized problem \dosknapsack such that $\WW^\pr$ be the resulting subset of $\VV^\pr$ with (i) $\WW^\pr$ is a \dos of size $k'=k$, (ii) $\sum_{u\in \WW^\pr} w(u) = k'= k$, (iii) $\sum_{u\in \WW^\pr} \alpha(u) = k' = k$\\
			\noindent
			This means that the set $\WW^\pr$ is a \dos which gives the maximum profit $k$ for the bag capacity of size $k$. In other words, $\WW^\pr$ is a \dos of size $k$, as $\sum_{u\in \WW^\pr} w(u) = \sum_{u\in \WW^\pr} \alpha(u) = k$. Since $\WW' =\{u_i: v_i \in \WW, \forall i \in[1,n]\}$, $\WW$ is a \dos of size $k$. Therefore, the \dos instance is an \yes instance.\\
			\noindent
			Conversely, let us assume that \dos instance $(\GG,k)$ is an \yes instance.\\ 
			Then there exists a subset $\WW\subseteq \VV$  of size $k$ such that it outputs a \dos. \\	
			\noindent
			Consider the set $\WW^\pr=\{u_i: v_i \in \WW, \forall i \in[1,n]\}$.
			Since each vertex of $\WW^\pr$ is involved with weight 1 and produces profit amount 1, $\WW^\pr$ is a \dos of size $k$ with max bag size and total profit $k$. 
			\noindent
			Therefore, the \dosknapsack instance is an \yes instance.\\
		\end{proof}

