		\begin{observation}(~\cite{cygan2015parameterized})\label{obs:reduction-for-ETH}
			Suppose $A$, $B$ $\subseteq \sum^*\times \mathbb{N}$ be two problems with instances $(x,k)$ and $(x',k')$ respectively. There is a parameterized reduction from $A$ to $B$. Then $B$ has an $f(k)|x|^{\OO(g(k))}$-time algorithm implies an $f(k')|x|^{\OO(g(k'))}$-time algorithm for $A$ for some computable function $f$ and non-decreasing function $g$.
		\end{observation}

		\begin{theorem}(~\cite{cygan2015parameterized})\label{thm:dos-ETH}
			Assuming ETH, there is no $f(k)n^{\OO(k)}$-time algorithm for the \dos problems, where f is any computable function.
		\end{theorem}
		\begin{theorem}\label{thm:doskp-ETH}
			Unless ETH fails, there is a no $f(k)n^{o(k)}$ -time algorithm for \dosknapsack for any non-decreasing function $f$ parameterized by the solution size k.
		\end{theorem}
		\begin{proof}
			Let $(G,k)$ and $(G',k)$ be the instances of the \dos and \dosknapsack  respectively. From the above Theorem\ref{thm:doskp-FPT-reduction}, we have parameterized reduction from \dos to \dosknapsack. Now, we prove this theorem by contradiction. Suppose \dosknapsack has a sub-exponential time algorithm with complexity $f(k)n^{o(k)}$. Now, from the observation \ref{obs:reduction-for-ETH} we can say that \dos problem also admits $f(k)n^{o(k)}$-time algorithm which contradicts the Theorem \ref{thm:dos-ETH}.
		\end{proof}







