		\begin{lemma}\label{lm:ntd}(\cite{kloks1994treewidth})
			If the \td of width $k$ and $\OO(n)$ nodes are given for a graph $\GG$ with $n$ vertices, one can transform it into a \ntd of width  $k$ in time $\OO(n)$ having $\OO(n)$ number of nodes. 
		\end{lemma}

		%\break
		\begin{theorem}\label{thm:doskp-treewidth}
			There is an algorithm of \dosknapsack with running time $\OO(4^{tw}\cdot n^{\OO(1)} \min\{s^2,{\alpha(\VV)}^2\})$ parameterized by treewidth $tw$, where $s$ is the size of the knapsack and $\alpha(\VV)=\sum_{v\in\VV}\alpha(v)$.\\
		\end{theorem}

		\begin{proof}
			Let $((\GG,(w(u))_{u\in\VV},(\alpha(u))_{u\in\VV},s,d),tw)$ be the given instance of our problem and $T^\chi=\langle \chi, T \rangle$ be the \ntd  of $\GG$ with width at most $\OO(tw)$ computed from a given \td of $\GG$ with width at most $\OO(tw)$ in polynomial time according to the lemma \ref{lm:ntd}.

			Suppose $\VV=\{v_1, v_2, \ldots, v_n\}$ is the set of vertices of the graph $\GG$. We represent $\GG_t=(\VV_t,\EE_t)$ as the subgraph corresponding to the tree decomposition $(T_t)$ rooted at $t$ such that $\VV(\GG) \cap V(T_t)=\VV_t(\GG_t)$ and $\EE_t$ are the edges induced by $\VV_t$. Now, a bag $X_i$ as $X_i=(v_{i_1}, v_{i_2},\ldots, v_{i_{n_i}})$ and the colors of the vertices of a bag with the following colors: 
			\begin{itemize}
				\item[$\bullet$] \textbf{Black:} These vertices are in the partial solution in $G_t$ that forms dominating set. In our algorithm, we represent these vertices  as "1".
				\item[$\bullet$] \textbf{White:} These vertices are dominated by some vertices which are in partial solution. Thus "white" vertices are not the part of partial solution. we represent these vertices with "0".
				\item[$\bullet$]\textbf{Gray:} These vertices are not in the partial solution and not even dominated at the current state of algorithm. We represent "gray" vertices with "$\hat{0}$".
			\end{itemize}
			Here, we define a function $\tilde{c}:v_{i_t}\rightarrow \{1, 0, \hat{0}\}$ such that $\tilde{c}(v_{i_t})=c_{i_t}\in \{1,0,\hat{0}\}$. Thus, the vector $c=(c_{i_1}, c_{i_2},\ldots, c_{i_{n_i}}) \in \{1,0,\hat{0}\}^{n_i}$ of dimension $|X_i|=n_i$ corresponding to the bag $X_i=(v_{i_1}, v_{i_2},\ldots, v_{i_{n_i}})$ represents a  \textit{coloring} of the bag $X_i$. A coloring $\hat{c}=\{\hat{c}_{i_1}, \hat{c}_{i_2}, \ldots, \hat{c}_{i_{n_i}}\}$ leads to \textit{no valid solution} for the bag $X_i$ if for all vertex $v_x \in X_i$ with \hl{color $\hat{c}_x \in \{0, \hat{0}\}$,} where $x\in\{i_1,i_2,\ldots,i_{n_i}\}$ such that  $\tilde{c}(n(v_{x})\cap \VV_i) \neq 1 \forall$  $ n(v_{x})\in N(v_{x})$. Here, $N(v_{x})= \{n(v_{x}): \{n(v_{x}), v_{x}\}\in \EE(\GG) \}$ denoted as the set of neighbors of $v_{x}$ and  $\VV_i$ is the set of vertices of the partial solution in $\GG_i$ such that corresponding tree decomposition $T^\chi_i$ rooted at $i$.

			For finding the solution \dosknapsack our goal is to find \dos along with the condition that it gives us optimal profit i.e., maximum $\alpha(\VV)=\sum_{v\in\VV}\alpha(v)$ within our budget $s$ constraint. The existing treewidth algorithm gives \dos with minimum cardinality but it is possible that may or mot not give the maximum profit. On the other hand each vertex is associated with some weight and our budget $s$ is fixed. So, it is not possible to add more vertices to the \kp to maximize the profit.

			We use dynamic programming and define the table $D$. The table entry $D[i,c]$ represents the set of undominated weight-profit pairs for the coloring $c$ and the node $i\in V(T)$ associated with the bag $X_i$. Algorithm chooses a node $i$ by applying dfs on $T^\chi_r$ rooted at $r$.
			\begin{itemize}
				\item[$\bullet$] If $i$ is \textit{leaf node}, the initialization for all the \textit{coloring} $c=(c_{i_1}, c_{i_2},\ldots, c_{i_{n_i}}) \in \{1,0,\hat{0}\}^{|X_i|}$, where  $X_i=(v_{i_1}, v_{i_2},\ldots, v_{i_{n_i}})$ :
				%\begin{align*}

				{\scriptsize\[D[i,c] = \begin{cases}
						\emptyset & \text{if $c$ loads to \textit{no valid solution}}\\
						\left(\mathlarger{\sum}_{\substack{c_j=1\\j\in \{i_1,\ldots, i_{n_i}\} }} w(v_j), \mathlarger{\sum}_{\substack{c_j=1\\j\in \{i_1,\ldots, i_{n_i}\} }} \alpha(v_j)\right) & \text{if $c$ valid and $\mathlarger{\sum}_{\substack{c_j=1\\j\in \{i_1,\ldots, i_{n_i}\} }} w(v_j)\leq s$}\\ \emptyset & \text{otherwise}
					\end{cases}\]

					%\end{align*}
				}
				Here, computing summations for each $c\in {\{1,0,\hat{0}\}^{|X_i|}}$ executes $\OO(|X_i|)$ times. That is, in total $\OO(3^{|X_i|}\cdot |X_i|)$ time required to compute summations. Also checking each weight-profit pair for all $D[i,c]$ takes $\OO(3^{|X_i|})$ times for all coloring $c$, as each $D[i,c]$ contains at most 1 such pair, in this step. Thus the total time for this initialization step takes $\OO(3^{|X_i|}\cdot |X_i|)$.\\


				\item[$\bullet$] If $i$ is \textit{forget node} with one child $j$:\\ 
				Let the bag corresponding to the node $i$ be $X_i$ and the child bag of $X_i$ is $X_j=X_i\cup\{x\}$. Suppose $c$ and $c'=(c\times\{x\})$ is the colorings for $X_i$ and $X_j$ respectively and the possible colors for $x:\tilde{c}(x)\in \{1,0,\hat{0}\}$. Then we updated $D[i,c]$ according to as follows: \[D[i,c]=\bigcup_{\tilde{c}(x)\in \{1,0\}} D[j,c']\] 
				We can refrain to gather the values of $D[j,c']$ for the color $\hat{0}$ of $x$ as according to the definition \ref{def:td} of \td that if a vertex $x$ which is unresolved $(\hat{0})$ and removed for a node at the current state, will never appear again for the rest of the algorithm to contribute a role to compute the \dos. Computation of $D[i,c]$ for all coloring $c$ takes $\OO(3^{|X_i|})$ times. Then we remove all \textit{undominated weight-profit pairs} from each $D[i,c]$ that contains at most $\min\{s,\alpha(\VV)\}$ pairs takes $\OO(3^{|X_i|}\cdot \min\{s,\alpha(\VV)\})$ times $\forall c\in \{1,0,\hat{0}\}^{|X_i|}$. Thus, the execution of the \textit{forget node} operation takes $\OO(3^{|X_i|}\cdot \min\{s,\alpha(\VV)\})$ times in total.\\

				\item[$\bullet$] If $i$ is \textit{introduce node} with one child $j$:\\ 
				The corresponding bags for the node $i$ and $j$ are $X_i$ and $X_j$ respectively and $X_i=X_j\cup \{x\}$. So, $X_j\subset X_i$. Let $c'$  and $c=(c'\times\{x\})$ are the colorings of $X_j$ and $X_i$ respectively. The coloring for $x$ are: $\tilde{c}(x)\in \{1,0,\hat{0}\}$. Then
				{\scriptsize\[D[i,c] = \begin{cases}
						D[j,c'] & \text{if} ~\{\tilde{c}(x)=\hat{0}\}\lor\{\exists ~n(x)\in N(x)\cap X_j: \tilde{c}(x)=0\land  \tilde{c}(n(x))=1\}\\ (w'+w(x),\alpha'+\alpha(x)), & \text{if} ~\{\tilde{c}(x)=1\}\land \{w'+w(x)\leq s~\forall(w',\alpha')\in D[j,c'_{0\rightarrow\hat{0}}]\} \\\emptyset & \text{otherwise}
					\end{cases}\]}
				Here, $c'_{0\rightarrow\hat{0}}$ is a coloring that we get by replacing  all 0 colors  in $c'$ with $\hat{0}$, which means that for finding $D[i,c]$, we use the coloring $c'_{0\rightarrow\hat{0}}$ instead of $c'$ corresponding to the coloring of $c$. For example, consider $c=(\hat{0},0,1,0)$ and $(\hat{0},\hat{0},1,\hat{0})$ for both of these the corresponding vector will be chosen from $c'_{0\rightarrow\hat{0}}$ is $(\hat{0},\hat{0},1,\hat{0})$ .   We need to fill the table $D[i,c]$ for all $c\in \{1,0,\hat{0}\}^{|X_i|}$ and check the validity of each vertex in $X_i$ for the color $\tilde{c}(x)\in \{0,\hat{0}\}$. For the color $\tilde{c}(x)=1$, $D[j,c'_{0\rightarrow\hat{0}}]$ contains at most $\min\{s,\alpha(\VV)\}$ pairs. So total time to compute $D[i,c]$ is $\frac{2}{3}\cdot3^{|X_i|}\cdot|X_i|+\frac{1}{3}\cdot3^{|X_i|}\cdot \min\{s,\alpha(\VV)\}=\OO(3^{|X_i|}\cdot \min\{s,\alpha(\VV)\})$. At the end, removing all undominated weight-profit pairs also takes takes time $\OO(3^{|X_i|}\cdot \min\{s,\alpha(\VV)\})$. So total runtime for introduce node $\OO(3^{|X_i|}\cdot \min\{s,\alpha(\VV)\})$\\

				\item[$\bullet$] If $i$ is \textit{join node} with two children $j$ and $k$:\\ 
				The corresponding bags for $i,j,k$ are $X_i,X_j,X_k$ respectively. By definition $X_i=X_j=X_k=(v_{i_1}, v_{i_2},\ldots, v_{i_{n_i}})$. Let $c\in \{1,0,\hat{0}\}^{|X_i|}$ a coloring for $X_i$. Similarly, $c',c''\in \{1,0,\hat{0}\}^{|X_i|}$ are represent coloring for $X_j$ and $X_k$ respectively. Now we define \textit{consistency} of the colorings $c'$ and $c''$ with the color $c$. To do so, consider $c_t,c_t'$ and $c_t''$ are single components (or "a color") of the vectors $c, c', c''$ respectively. If $c'$ and $c''$ are \textit{consistent} with the color $c$ then the following conditions hold:
				\begin{itemize}
					\item[1.] $c_t'$ = $c_t'' = c_t$ iff $c_t\in \{1,\hat{0}\}$ and
					\item[2.] $(c_t',c_t'')\in\{(0,\hat{0}),(\hat{0},0)\}$ iff $c_t=0$
				\end{itemize}
				Now, we update $D[i,c]$ for all coloring $c$ and for all undominated weight-profit pairs $(w_{c'},\alpha_{c'})\in D[j,c']$ and $(w_{c''},\alpha_{c''})\in D[k,c'']$ as follows:
				{\scriptsize\[ D[i,c] = \{ (w_{c'}+w_{c''}-\mathlarger{\sum}_{\substack{c_l=1\\l\in \{i_1,\ldots, i_{n_i}\} }} w(v_l),\alpha_{c'}+\alpha_{c''}-\mathlarger{\sum}_{\substack{c_l=1\\l\in \{i_1,\ldots, i_{n_i}\} }}\alpha(v_l)): c' \text{and} c'' \text{are consistent with}~ c   \}\]}\\
				Here, $w(v_l)$ and $\alpha(v_l)$ represents the weight and profit for the vertex $v_l\in X_i$ respectively. 

				The complexity of finding consistency of $(c',c'')$ with $c$ for each coloring $c$ we need $\OO(4^{|X_i|})$ operations  as from the above conditions 1 and 2, we process four 3-tuples $(c_t,c_t',c_t'')$ with the values $(1,1,1)$,$(\hat{0},\hat{0},\hat{0})$,$(0,0,\hat{0})$,$(0,\hat{0},0)$~\cite{alber2002fixed}. Now, each table $D[j,c']$ and $D[k,c'']$ for the two children of node $i$ contains at most $\min\{s,\alpha(\VV)\}$ pairs.
				The complexity of finding $D[i,c]$ based on consistency of $(c',c'')$ with $c$ is $\OO(4^{|X_i|}\cdot \min\{s^2,{\alpha(\VV)}^2\})$.  Then we remove all such pairs from $D[i,c]$ such that $(w'+w''-\sum_{\substack{c_l=1\\l\in \{i_1,\ldots, i_{n_i}\} }} w(v_l))\leq s~ \forall ~c$. Execution of this condition takes $\OO(3^{|X_i|}\cdot \min\{s,\alpha(\VV)\})$. Then we remove all dominated and duplicated pairs for $D[i,c]~ \forall~ c$. This removal also takes $\OO(3^{|X_i|}\cdot \min\{s,\alpha(\VV)\})$ time. Join node operations takes total time $\OO(4^{|X_i|}\cdot \min\{s^2,{\alpha(\VV)}^2\})$.\\



				Once we get $D[r,c]$ for the root node $r$ of the tree decomposition $T^\chi_r$ and the algorithm outputs the weight-profit pairs such that each of them a \dos. According to lemma\ref{lm:ntd} $T^\chi_r$ has $\OO(n)$ nodes. So, the runtime of the algorithm for $\OO(n)$ nodes is $\OO(4^{|X_i|}\cdot n^{\OO(1)} \min\{s^2,{\alpha(\VV)}^2\})$. We compute our final result  $(\hat{w},\hat{\alpha})$, where $\mathlarger{\max}_{\hat{\alpha}\geq \alpha} ~\{\mathlarger{\bigcup}_{\substack{ (w,\alpha)\in D[r,c]\forall c\\c_t\in\{0,1\}}} (w,\alpha) \}$. This additional step takes $\OO(3^{|X_i|}\cdot \min\{s,\alpha(\VV)\})$ time. As  $|X_i|=\OO(tw)$, thus the total runtime of this algorithm is $\OO(4^{tw}\cdot n^{\OO(1)} \min\{s^2,{\alpha(\VV)}^2\})$ .\\

				%\fsc counts proper coloring for all induced subgraph of a graph with vertex set $\VV$.\\
				%Let us define two sets $S_1, S_0\subseteq X_i$ such that $\tilde{c}(v_z)=1~ if~ v_z \in S_1$, $\tilde{c}(v_z)=0 ~if~ v_z \in S_0$ and $\tilde{c}(v_z)=\hat{0}~ if~ v_z \in X_i\setminus\{S_1\cup S_0\}$.\\
			\end{itemize}



		\end{proof}
		\section{Conclusion}

		In this paper we proved that \dosknapsack is strongly \NPC for general graph (Theorem \ref{thm:doskp-npc}), Bipartite graph (Theorem \ref{thm:doskp-bipt-npc}) Weekly \NPC for star graph (Theorem \ref{thm:doskp-star-npc}). we provided Pseudo-polynomial time algorithm for Trees (Theorem \ref{thm:doskp-trees-pseudo-poly}). Also proved that$W[2]$-complete parameterized by the solution size (Theorem \ref{thm:doskp-W[2]-Complete}) by proving\dosknapsack is $W[2]$-hard parameterized by the solution size (Theorem \ref{thm:doskp-npc}) and It belongs to $W[2]$ (Theorem \ref{thm:doskp-WCS-reduction}). Another proof is that, Unless ETH fails, there is a no $f(k)n^{o(k)}$ -time algorithm parameterized by the solution size $k$ (Theorem \ref{thm:doskp-ETH}). \dosknapsack is FPT parameterized by Treewidth (Theorem \ref{thm:doskp-treewidth}) and by the size of \vcknapsack solution. (Theorem \ref{thm:doskp-vc_kp}).



