\subsection{Mathematical Model}
The mathematical model focuses primarily on the %\textit{Risk Scenario Development} step of the 
\textit{Quantitative Assessment} as the employment of a specific approach, including event trees for this phase, has been proposed.

\begin{definition} [\textbf{Event}]
    An event encompasses all possible occurrences of interest. It can represent a specific experiment, a physical process, a natural phenomenon, a human action, a reaction to a question, and more \cite{sys62}. It is represented by \textit{e} in this manuscript. 
\end{definition}

\begin{definition} [\textbf{Outcome}]
    The outcome of an event refers to its result, which determines the consequences of the event's occurrence within the context of analysis \cite{sys62}.  It is represented by \textit{`i'} in this manuscript.
\end{definition}

\begin{definition} [\textbf{Event Outcome Space}]
    The outcome of an event can be any specific element within a defined set, where the elements are both distinct and finite. An event space has \textit{n} distinct outcomes, the outcome space encompasses all potential outcomes of an event (i.e., complete), and each individual outcome is mutually exclusive, meaning only one outcome can occur with each instance of the event \cite{sys62}. It is represented by \textit{I} in this manuscript.
\end{definition}

\begin{equation}
\label{eq:event_space}
    I = \{i_x\}, ~ ~ x = 1,2,...,n,
\end{equation}

\noindent where $I$ is the event outcome space, $i$ is an outcome, and $n$ is the total number of outcome options.

\begin{definition} [\textbf{Cartesian product of two event outcome spaces}]
    For two events $e_1$ and $e_2$ with event outcome spaces $I_1$ and $I_2$, with ${i_{1y}},~y = 1,2,...,n_1$ and ${i_{2y}},~y = 1,2,...,n_2$, respectively, the Cartesian product of the two outcome spaces is defined as the set whose elements consist of the $n_1\times n_2$ potential pairs (combinations) of the individual outcomes ${i_{1y}}$ and ${i_{2y}}$. The product of outcome spaces encompasses all potential outcomes of an event (i.e., complete), and each individual outcome is mutually exclusive, i.e., for any two unique elements of the product space $(i_{1a}i_{2b})$ and $(i_{1c}i_{2d})$, $a \neq c$ and/or $b \neq d$ \cite{sys62}. 
\end{definition}

\begin{definition} [\textbf{Cartesian product of N event outcome spaces}]
    The Cartesian product of $N$ event outcome spaces is created by taking an outcome of each space, combining it with all outcomes of every other space, and it includes all possible combinations of the outcomes of the $N$ events. It has k elements, encompasses all potential outcomes of an event (i.e., complete), and each individual outcome is mutually exclusive \cite{sys62}.
\end{definition}

\begin{equation}
\label{eq:n_outcomespace}
    I = I_1 \otimes I_2 \otimes \cdots \otimes I_N = I^{N-1}\otimes I_N,
\end{equation}

\noindent where $I^{N-1}$ represents the Cartesian product of N-1 events.

\begin{equation}
\label{eq:n_outcomespace_elements}
    k = \prod y = 1Nn_y,
\end{equation}

\noindent where $n_y$ is the number of elements on the \textit{y}th event outcome space.

\begin{definition} [\textbf{Joint event of N events}]
    A joint event of $N$ events, i.e., $e_1,e_2,...,e_N$ is the event having outcome space equivalent to the Cartesian product of N individual outcome spaces, i.e., $I_1,I_2,...,I_N$  \cite{sys62}.
\end{definition}

\begin{equation}
\label{eq:jointevent}
    e = e_1.e_2\cdots e_N.
\end{equation}


\begin{definition} [\textbf{Event base}]
    A set of $N$ events forms an event base $E$ if it includes all events whose outcomes are required to describe the state of the domain. Anything of interest should be expressible in terms of the outcomes of these $N$ events. The $N$ events that make up the event base are referred to as basic events or elements of the base \cite{sys62}. 
\end{definition}

\begin{definition} [\textbf{Outcome space of an event base}]
    The outcome space of the domain $D$ is the outcome space of the joint event formed by its event base, wherein the event outcome space of a domain is the Cartesian product of the $N$ event outcome spaces of the event base, has finite elements, encompasses all potential outcomes of an event (i.e., complete), each individual outcome is mutually exclusive, the elements are points in an N-dimensional discrete space, and a single point in the outcome space consists of $N$ individual outcomes of the $N$ events \cite{sys62}.
\end{definition}

\begin{definition} [\textbf{Event tree}]
An event tree is a visual diagram that maps out all possible outcomes of a specific event. The event's name serves as the title of the tree, and each potential outcome is represented by a branch extending from a central node \cite{sys62}.
\end{definition}

\begin{definition} [\textbf{Event tree path}]
    A path is a set of branches, one from each event in the base. Each path in an event tree represents an outcome of the joint event (or the event base). The number of paths in the tree equals the number of outcomes in the outcome space of the event base. These paths are mutually exclusive, as they correspond to mutually exclusive outcomes in the outcome space \cite{sys62}. It is represented by $\pi$ in this manuscript.
\end{definition}

\begin{equation}
\label{eq:probofoutcome}
   0\leq P[i_x] \leq 1,
\end{equation}

\noindent where $i_x$ is an outcome and $P[i_x]$ is the probability of that outcome $i_x$ and is a nonnegative real number, and %Moreover, any probability assignment $P$ must satisfy the condition $P[i_x]=1$.

\begin{equation}
\label{eq:sumproboutcome}
    \sum_{x=1}^{n} P[i_x]   = 1.
\end{equation}

Let an event be $e_j$,~$j=1,2,\cdots,N$ and an outcome of an event be $e_{jx}$,~$x=1,2,\cdots,n$, the probability of a path $\pi$ where events are independent can be depicted by the example of a fire in a building. The initiating event $e_1$ is the fire breaking out, the next event is related to the fire alarm activation $e_2$, followed by the activation of sprinklers $e_3$, and so on. The outcomes of the event $e_2$ include (i) $e_{21}$: Yes, where the alarm is triggered, and (ii) $e_{22}$: No, in the case the alarm is not triggered. Similarly, the outcomes related to $e_3$ will include $e_{31}$, $e_{32}$, and so on. The probability of a success path, wherein the alarm was triggered, the sprinklers were activated, the evacuation was successful, and the fire was extinguished, can be calculated by taking the product of all probabilities of individual events on this path. In general, the probability of a path $\pi$ where events are independent is computed as:
\begin{equation}
\label{eq:pathprobind}
    P[\pi] = P[e_{jx}] \times P[e_{(j+1)x}] \times P[e_{(j+2)x}] \times \cdots = \prod_{j=1}^{N} P[e_{jx}], 
\end{equation}

\noindent where $P[e_{jx}]$ is the probability of the $j$th event, $P[e_{(j+1)x}]$ is the probability of the $(j+1)$th event, and $P[e_{(j+2)x}]$ is the probability of the $(j+2)$th event \cite{addmodel1}.
%https://www.usbr.gov/ssle/damsafety/risk/BestPractices/Chapters/A5-EventTrees.pdf
%exerpt: The conditional structure of the event tree satisfies the probability calculus for the multiplication rule of basic probability theory; therefore, branch probabilities can be multiplied along a pathway to obtain the probability for the intersection of events along the pathway. 

Let an event be $e_j$,~$j=1,2,\cdots,N$ and an outcome of an event be $e_{jx}$, ~$j=1,2,\cdots,N$, and $x=1,2,\cdots,n$, the conditional probability of a path $P[\pi]$ is computed as:

\begin{equation}
\label{eq:pathprobcond}
    P[\pi] = P[e_{jx}] \times P[e_{(j+1)x}|e_{jx}] \times P[e_{(j+2)x}|e_{jx}\cap e_{(j+1)x}] \times \cdots
\end{equation}

\noindent where $P[e_{jx}]$ is the probability of the $j$th event, $P[e_{(j+1)x}|e_{jx}]$ is the probability of the $(j+1)$th event given the $j$th event, and $P[e_{(j+2)x}|e_{jx}\cap e_{(j+1)x}]$ is the probability of the $(j+2)$th event given the $j$th and $(j+1)$th events \cite{addmodel2}.
%https://www.ntnu.edu/documents/624876/1277590549/chapt03-eta.pdf/6f3e1b19-4824-4812-adc8-9762d2201c22
%slide 23

The impact \cite{sys63} associated with an event tree path is computed as:

\begin{equation}
    \label{eq:impact}
\gamma_\pi = 1 - [(1 - C_\gamma) \times (1 - G_\gamma) \times (1 - A_\gamma)],  
\end{equation}

\noindent where $\gamma_\pi$ is the impact or consequence associated with a path $\pi$, $C_\gamma$ is the impact on confidentiality, $G_\gamma$ is the impact on integrity, and $A_\gamma$ is the impact on availability.

\begin{comment}
\begin{equation}
    \label{eq:impactnorm}
{\gamma_\pi}^N = \frac{\gamma_\pi - \gamma_{min_T}}{\gamma_{max_T} - \gamma_{min_T}}   %i is the specific event/entry %max and min are for impact column.
\end{equation}
\end{comment}

The risk score $R$ associated with a path $\pi$ is computed as:
\begin{equation}
    \label{eq:risk}
R_\pi = P[\pi] \times \gamma_\pi,   
\end{equation}

\noindent where $P[\pi]$ is the likelihood, and $\gamma_\pi$ is the impact associated with a path.

