\begin{algorithm}[!tb]
\caption{Risk Assessment: CVE-TELSAFE}
\label{algorithm:RiskAssess}
\SetInd{0.25em}{0.1em} %to decrease indentation
\footnotesize{
\textbf{Input}: Dataset $\mathcal{D}$. \\
\textbf{Output}: Numeric Risk Scores $R_\pi$. \\
\For{$t \gets cycle$}{
    Initialize timer $t_i$\;
    $dataArray \gets \mathcal{D}$\;
    % Initializing the likelihood columns array
    $LhdCol \gets \textup{cell}(\text{size}(dataArray,1), \text{size}(N,2))$\;
    % N is the number of likelihood columns (e_1, e_2, ..., e_N)
    $q \gets 1$\;
    % Creating/combining columns for likelihood.
    \For{$colx \in [1 \dots N]$}{ % Selected column numbers for likelihood
        $LhdCol(:,q) \gets dataArray(:, colx)$\;
        $q \gets q+1$\;
    }
    % Run till number of columns of LhdCol array
    \For{$j \gets 1 \text{ to } N$}{
        % Taking each column one by one
        $colData \gets LhdCol(:, j)$\;
        % Unique values, and their first appearance indices.
        $(unqVal, idx) \gets \text{unique}(colData)$\;
        % numel(unqVal): number of unique values
        \For{$x \gets 1 \text{ to } \textup{numel}(\text{unqVal})$}{
            $value \gets unqVal(x)$\;
            % Count occurrences of each unique value
            $occurrences \gets \text{sum}(\text{idx} == x)$\;
            % Divide by number of elements of the column
            $P[i_x] \gets \frac{occurrences}{\text{numel}(colData)}$\;
            $P[e_{jx}](\text{idx} == x, j) = P[i_x]$\;
        }
    }
    \For{$row \gets 1 \text{ to } \textup{size}(dataArray, 1)$}{
        $P[\pi] \gets \prod_{j=1}^{N} P[e_{jx}]$\;
        $\gamma^{\textup{N}}_{\pi} \gets \frac{\gamma_\pi - \gamma_{\min_T}}{\gamma_{\max_T} - \gamma_{\min_T}}$\;
        $R_\pi \gets P[\pi] \times \gamma_\pi$\;
        $R^{\textup{N}}_{\pi} \gets \frac{R_\pi - R_{\min_T}}{R_{\max_T} - R_{\min_T}}$\;
    }
    End timer $t_f$\;
}
}
\end{algorithm}



