\subsubsection{Overview and Pseudo-Code}

The following Algorithm \ref{alg:matcher} outlines the full column-to-target-attribute matching process described above. For each extracted table column it is scored against every target attribute in the template schema. The matching is done using a combination of schema-based and instance-based metrics. The final assignment to target attributes is determined via the Hungarian Matching Algorithm with a threshold.

\begin{algorithm}
\caption{Column-to-Target-Schema}
\label{alg:matcher}
\KwIn{DataFrame $T$ from CSV with headers $H$; target schema attributes $S$; metric weights $w_m$; alpha $\alpha$; threshold $\theta$}
\KwOut{Mapping $M: H \rightarrow S$}
\ForEach{header $h \in H$}{
    \ForEach{attribute $a \in S$}{
        $s_{\text{schema}}   \leftarrow \sum_{m \in M_{\text{schema}}} w_m \cdot m(h, a)$ \;
        $s_{\text{instance}} \leftarrow \sum_{m \in M_{\text{instance}}} w_m \cdot m(T[h], a)$ \;
        $s_{\text{hybrid}}   \leftarrow \alpha \cdot s_{\text{schema}} + (1 - \alpha) \cdot s_{\text{instance}}$ \;
        \If{$s_{\text{hybrid}} \geq \theta$}{
            $C[h, a] \leftarrow s_{\text{hybrid}}$ \;
        }
        \Else{
            $C[h, a] \leftarrow -\infty$ \;
        }
    }
}

$(\mathit{rows}, \mathit{cols}) \leftarrow \text{Hungarian Algorithm}(-C)$ \;
$M \leftarrow \{ h_i \mapsto a_j \mid (i, j) \in (\mathit{rows}, \mathit{cols}) \ \wedge \ C[i, j] \neq -\infty \}$ \;
\Return $M$
\end{algorithm}
