\caption{Average metric weight by data type}
\label{tab:metric_gap}
\begin{tabular}{lccc}
\toprule
\textbf{Type} & \textbf{Schema Avg} & \textbf{Instance Avg} & \textbf{Gap} \\
\midrule
STRING & 0.1500 & 0.2579 & 0.108 \\
