\section{Metrics}
\label{app_metrics}
\subsection{Schema-Based Metrics}
\textbf{Levenshtein Similarity:}
Measure the normalized edit distance between the cleaned source column header and the target attribute's synonyms.

\textbf{Formula:}
\[\text{Sim}_{\text{lev}}(s_1, s_2) = \max \left(1 - \frac{\text{EditDist}(s_1, s_2)}{\max(|s_1|, |s_2|)}\right)\]

\textbf{Jaccard Token Overlap:}
Measure set-based token similarity between column header and each synonym of target attribute.

\textbf{Formula:}
\[\text{Sim}_{\text{jaccard}}(T_1, T_2) = \frac{|T_1 \cap T_2|}{|T_1 \cup T_2|}\]\[\text{Schema}_{Jaccard}(h, a) = \max_{s_2 \in \{\text{name, synonyms}\}}\text{Sim}_{\text{jaccard}}(T_1, T_2)\]

\textbf{Synonym Matching:}
Use fuzzy token-set ratio to compare column header with all known synonyms of target attribute.

\textbf{Formula:}
\[\text{Sim}_{Syn}(h, a) = \max_{s \in \{\text{name, synonyms}\}} \frac{\text{FZS}(h, s)}{100}\]
\textit{*FZS = Fuzzy Token Set}

\subsection{Instance-Based Metrics}
\textbf{Numeric Data Type:}
Estimates how likely the column is to contain numerical data, based on content of its cell.
This metric checks (1) how many cells contains a digit and (2) how many cells start with a digit. Combines this in a weighted score.

\textbf{Formula:}
\[N(C) = 0.7 \cdot \text{HasDigit}(C) + 0.3 \cdot \text{StartsWDigit}(C)\]

\textbf{Date Type:}
Calculates the proportion of cells that match into a date pattern.

\textbf{Formula:}
\[\text{Sim}_{Date} = \frac{1}{N} \sum_{i=1}^N \mathbb{1}_{\text{is\_date}}(d_i)\]

\textbf{Numerical Range Comparison:}
Evaluate how close the mean of source column is to mean of target attribute and how many values lie within IQR.

\textbf{Formula:}
\[\text{Sim\_Range} = 0.5 \cdot \max\left(0, 1 - \frac{|\mu_s - \mu_t|}{\text{IQR}}\right) + 0.5 \cdot \frac{1}{N} \sum_{i=1}^N \mathbb{1}_{[q_1, q_3]}(x_i)\]

\textbf{KS-Test (Kolmogorov–Smirnov test):}
Compares the distribution of the source column to a normal distribution generated using the target's mean and IQR.

\textbf{Formula:}
\[D = \sup_x |F_s(x) - F_t(x)| \quad \text{where } F_s, F_t \text{ are empirical CDFs}\]
\[
\text{KS\_Score} = 1 - D
\]
\textit{CDF = Cumulative Distribution Function}

\end{appendices}

