The \emph{directed power graph} of a group $G$, denoted by $DPow(G)$, is the directed graph with vertex set $G$, and edge set $\{(x,y): y = x^m$ \textrm{ for some positive integer} m\}. The \emph{power graph}, denoted by $Pow(G)$, is the underlying undirected graph of $DPow(G)$, i.e., the undirected graph obtained from $DPow(G)$ after removing directions, self-loops and double arcs.

\medskip 

% \end{definition}
 \begin{remark}\label{remark power graph} 
 %(i) In $DPow(G)$, the out-degree of a vertex $u$ is the order of $u$ in $G$; (ii) 
 If $\{x,y\}$ $\in E(Pow(G))$, then either $ord(x)|ord(y)$ or $ord(y)|ord(x)$. If $G$ is a cyclic group, then %the opposite direction also holds, i.e., 
 $\{x,y\}$ is an edge in $Pow(G)$ if and only if either $ord(x)|ord(y)$ or $ord(y)|ord(x)$.
 \end{remark}

 We define an equivalence relation $\sim$ on $G$ as follows: for $x,y\in G$, $x\sim y$ if and only if $\langle x \rangle = \langle y \rangle$, i.e., $x$ and $y$ generate the same cyclic subgroup of $G$. The equivalence class containing $x$ is denoted by $[x]$. So, all the elements of a class have the same order. Note that the size of $[x]$ is $\phi(ord(x))$.

\medskip 

\begin{remark}\label{equivalence classes form a clique} In $Pow(G)$, the following two facts hold:
    (\textit{$i$}) Each equivalence class $[x]$ of $G$ is a clique of size $\phi(ord(x))$ in $Pow(G)$;
    (\textit{$ii$}) For two classes $[x]$ and $[y]$, if an element $x\in [x]$ is adjacent to an element $y\in [y]$ in $Pow(G)$, then every element of $[x]$ is adjacent to every element of $[y]$. 
\end{remark}
\medskip 
\begin{lemma}\cite{chakrabarty2009undirected}\label{complete power}
    The power graph of a finite group is complete if and only if the group is a cyclic group of prime-power order.
\end{lemma}


