% For $f$ to be one-to-one, the following two properties need to be satisfied:
We begin by identifying two inequalities, that must be satisfied for \( f \) to be one-to-one. Subsequently, we show that \( b = O(\log n) \) satisfies these inequalities.


% \begin{itemize}
%     \item[(1)]  
(1) First, $f_\mathcal{P}$ has to be one-to-one. For that, we need the following: %$\binom{b-1}{\frac{b-1}{2}} \geq 2n   $.
\begin{equation}\label{variables_1}
\binom{b-1}{\frac{b-1}{2}} \geq 2n
% \makebox[0.8\textwidth][c]{\text{$
% \displaystyle
% \binom{b-1}{\frac{b-1}{2}} \geq 2n
% $} }
\end{equation}


(2)  For each vertex $u \in \{x_i,\overline{x}_i \ | \ 1 \leq i \leq n \}$, we must have: $|[h]| \geq |N(u)| - 1$, where $h$ is a neighbour of $f(u)$ in $Pow(\mathbb{Z}_N)$. Note that $|N(u)|$ is at most the number of clauses $m$ in $\Phi$ and $m=O(n^3)$. From the definition of $f$, one can see that $|[h]|$ is at least $\phi(p_2p_3\dots p_{\frac{b+1}{2}})$, as $|[h]|=\phi(ord(h))$. Hence, 
satisfying the following inequality is sufficient: 

\begin{equation}\label{clauses2}
    cn^3 \leq \phi(p_2p_3\dots p_{\frac{b+1}{2}}), \text{ where $c$ is some constant}    
\end{equation}


% \end{itemize}
%In \Cref{app: calculation of b=O(logn)}, 
We now show that for $b=2\log(2n)+1$ and for sufficiently large $n$, both the above inequalities, \Cref{variables_1} and \Cref{clauses2}, %$\binom{b-1}{\frac{b-1}{2}} \geq 2n   $ and  $cn^3 \leq \phi(p_2p_3\dots p_{\frac{b+1}{2}})$,
are satisfied.

