\begin{lemma}\label{color iso in enough}
 Let $DPow(G)$ and $DPow(H)$ be two directed power graphs. Then $R(DPow(G))$ is colour-isomorphic to $R(DPow(H))$ if and only if $DPow(G) \cong DPow(H)$. 
\end{lemma}

