\begin{theorem}\label{summary}
There are polynomial time algorithms $\mathcal{A}_{ab}$, $\mathcal{A}_{polycyc}$, and $\mathcal{A}_{sqfr}$ that take a graph $\Gamma$ as input and decide if $\Gamma$ is isomorphic to the power graph of an abelian group, a nilpotent group of bounded polycyclic length, or a nilpotent group of squarefree exponent, respectively.
\end{theorem}

\subsection{Abelian Groups}\label{sec: recognition abelian p-groups}

