\medskip 

\begin{restatable}{lemma}{abelian}\label{enumerating abelian p-groups in poly}
    There is a polynomial time algorithm that, given a number $p^m$, outputs all non-isomorphic abelian groups of order $p^m$.
          % There is a polynomial time algorithm that, given a directed graph $\overrightarrow{\Gamma}$, recognizes whether $\overrightarrow{\Gamma}$ is isomorphic to the

\end{restatable}
\begin{proof}
%Let $|V(\overrightarrow{\Gamma})|=p^m$. 
By the Fundamental Theorem of Abelian Groups, any abelian group of order $n=p^{m}$ %$n=p_1^{\al_1}p_2^{\al_2}\dots p_k^{\al_k}$ is isomorphic to $A_1 \times A_2 \times \dots \times A_k$, where each $A_i$ 
    is isomorphic to $\ZZ_{p^{r_{1}}}\times \ZZ_{p^{r_{2}}} \times \dots \times \ZZ_{p^{r_{k}}}$, such that each $r_{i} \geq 1$, for all $1\leq i\leq k$, and $r_{1}+r_{2}+\dots + r_{k}=m$. %Any abelian $p$-group $G$ of order $p^m$ is isomorphic to $\ZZ_{p^{i_1}}\times \ZZ_{p^{i_2}}\times \dots \times \ZZ_{p^{i_k}}$, where $i_1,i_2,\dots,i_k$ are natural numbers and $i_1+i_2+\dots + i_k =m$. 
    Hence, the number of non-isomorphic abelian groups of order $p^m$ is the number of partitions of $m$, which is upper bounded by $2^{c \sqrt{m}}$, for some constant $c$ (see \cite{apostol2013introduction}). Observe that, $2^{c\sqrt{m}} < (|G|)^c$. %\jinia{it can be easily seen th $2^{c\sqrt{m}} < (|G|)$}. 
Let $Part(m)=\{Part_1,Part_2,\dots,Part_k\}$ be the set of all possible partitions of $m$. For each possible partition $Part_i$ in $Part(m)$, we construct the Cayley table of the corresponding abelian $p$-group $G_{Part_i}$, i.e., if $Part_i=\{m_1,m_2,\dots,m_s\}$, then $G_{Part_i}:= \ZZ_{p^{m_1}}\times \ZZ_{p^{m_2}}\times \dots \times \ZZ_{p^{m_s}}$. %Next, we check whether $\DG$ is isomorphic to $DPow(G_{Part_i})$ by using \Cref{iso: nil}, which runs in polynomial in $|V(\DG)|$. We do the above isomorphism testing for all $1 \leq i \leq |Part(m)|$.
Since $|Part(m)|< (p^m)^c$, the algorithm/enumeration process runs in time polynomial in $p^m$. %\hfill$\lhd$
\end{proof} 


\subsection{Nilpotent Groups of Bounded Polycyclic Length}\label{sec: recognition nilpotent subclass}
% \textcolor{red}{*********polycyclic strating**********}

A \textit{polycyclic series} of a group $G$ is a finite series $G=G_0 \geq G_1 \geq \dots \geq G_l=\{1\}$ such that for each $0\leq i \leq l-1$, $G_{i+1} \lhd G_{i}$ and the factor $G_{i+1}/G_i$ is cyclic. A group with a polycyclic series is called a \textit{polycyclic group}. %For finite groups, polycyclic groups and solvable groups are the same. Hence, e
Every finite nilpotent group is a polycyclic group. The \textit{polycyclic length} (see \cite{fisher1974polycyclic})  of a polycyclic group is the number of non-trivial factors of a polycyclic series of shortest length. The main result of this section follows as a consequence of \Cref{bounded polycyclic length: presentation and enumerating} and \Cref{pow(nil) reducible to dpow(p)}. As a consequence, \Cref{summary} for nilpotent groups of bounded polycyclic length follows.

 % \textcolor{magenta}{Let $\mathcal{X}$ be the set of groups from $\mathcal{G}_{PP}$ of bounded polycyclic length. For the purpose of enumerating polycyclic groups in $\mathcal{X}$ in polynomial time (see \Cref{p-group of bounded polycyclic length: enumerating}), we use the concept of \textit{presentation} (for a detailed definition, see \Cref{app: recognition}) of groups, which is constructed here using the polycyclic series of groups in $\mathcal{X}$. We first show that a standard process of generating presentations (see e.g., \cite{higman1960enumerating}, \cite{arvind2011solvable}) yields logarithmic sized presentations of groups in $\mathcal{X}$. From that, using a polynomial time \emph{process} of constructing a Cayley table from a presentation (similar to \cite{arvind2011solvable}), we conclude the next lemma. A detailed proof is in \Cref{app: recognition}.}\jinia{proper reference}

 \medskip 

 \begin{theorem}\label{recognition bounded polycyclic}
There is a polynomial time algorithm that takes a reduced directed graph $\Gamma$ as input and checks whether $\Gamma$ is isomorphic to the reduced directed power graph of a nilpotent group with bounded polycyclic length.
\end{theorem}


Let $\mathcal{X}$ denote the class of groups in $\mathcal{G}_{PP}$ with bounded polycyclic length. To enumerate these groups in polynomial time (see \Cref{bounded polycyclic length: presentation and enumerating}), we use the concept of group \emph{presentations}, which is derived here from their polycyclic series. %(see \Cref{app: recognition nilpotent subclass} for a detailed definition). 
Let $X$ be a finite set and $R$ is a set of words over $X\cup X^{-1}$, i.e., $R$ is a subset of $(X\cup X^{-1})^*$, where $A^*$ is the set of all strings $x_1x_2\dots x_r$ with each $x_i \in A$. The \textit{presentation} of a group $G$ is the pair $(X,R)$ in the sense that $G$ is isomorphic to the quotient group $ F_X / N$, where $F_X$ is the free group on $X$ and $N$ is the normal closure of $R$ in $F_X$. %A \textit{presentation} of a group $G$ is a pair $(X, R)$ where $X$ is a generating set for $G$ and $R$ is a set of words over $X \cup X^{-1}$ such that $w \in R$ defines the equation $w = 1$ and $(X, R)$ defines the group $G$ in the sense that there is an algorithm that, on input a presentation of a group $G$, computes the Cayley table of a group $G'$ isomorphic to $G$. 
The length of a presentation $(X,R)$ is denoted by $||(X,R)||$.

We first show that standard methods (e.g., \cite{higman1960enumerating}, \cite{1313808}) yield logarithmic-size presentations for groups in $\mathcal{X}$. Using these, and a polynomial time \emph{procedure} for constructing a Cayley table from a presentation (cf. \cite{1313808}), we establish the next lemma. %The full proof appears in \Cref{app: recognition nilpotent subclass}.





% The proof of \Cref{p-group with bounded polycyclic length: short presentation} (proof is in \Cref{app: presentation}) shows that a standard process of generating presentations (see e.g., \cite{higman1960enumerating}, \cite{arvind2011solvable}) yields logarithmically sized presentations of groups in $\mathcal{G}_{PP}$ of bounded polycyclic length. Then, using the algorithm due to Arvind and Toran \cite{arvind2011solvable}: that takes a presentation of the form used in \Cref{p-group with bounded polycyclic length: short presentation} and outputs a Cayley table of an isomorphic group, \Cref{p-group of bounded polycyclic length: enumerating} is proved (see \Cref{app: recognition} for details). \jinia{proper reference} 

%  Arvind and Toran \cite{arvind2011solvable} showed that there is a polynomial time algorithm that takes a presentation $(X,R)$ of a solvable group $G$ which is obtained from a process described in the proof of the above lemma and outputs the Cayley table of a group $G'$ isomorphic to $G$. %With a similar approach (see \cite[Theorem 3.3]{arvind2011solvable} for details) to theirs, 
% On all strings of length at most $O(\log N)$, we run the algorithm due to Arvind and Toran and generate the Cayley tables of all non-isomorphic groups of order $N$. \Cref{p-group with bounded polycyclic length: short presentation} guarantees that this works.\hfill $\lhd$

\medskip 


\begin{restatable}{lemma}{polycyclic}\label{bounded polycyclic length: presentation and enumerating}
  Let $c>0$ be a constant and $\mathcal{X}$ be the set of groups $G$ from $\mathcal{G}_{PP}$ such that the polycyclic length of $G$ is bounded by $c$. Then, each $G\in \mathcal{X}$ has a presentation of length $O(\log |G|)$. Moreover, there is an algorithm that generates Cayley tables of all non-isomorphic groups of $\mathcal{X}$ of order $N$ in time polynomial in $N$.
% \end{lemma}
\end{restatable}
\begin{proof}
We first show that $G\in \mathcal{X}$ has a logarithmic-size presentation. %\textcolor{blue}{Here to calculate the length of the presentation $(X,R)$ of $G$, we mainly focus on the length of $R$. Each relation is stored as a vector of dimension at most $c$, where the vector stores the powers of generators of $G$.}


Let $|G|=p^n$. Suppose\footnote{A \textit{subgroup} $H$ of $G$ is denoted by $H \leq G$, and a \textit{normal subgroup} $H$ of $G$ is denoted by $H \lhd G$.}, $G=G_0 \geq G_1 \geq \dots \geq G_{c-1} \geq G_c=\{1\}$ is the polycyclic series of $G$, where $G_{i+1} \lhd G_{i}$, and $G_{i}/G_{i+1}$ is cyclic, for all $0\leq i \leq c-1$. We inductively construct a presentation of $(X_i,R_i)$ of $G_i$, $0\leq i \leq c-1$, where the elements of $R_i$ will be encoded as tuples of length $i$. Moreover, by induction on $i$, we show that $||R_i||\leq 2i^3 \log |G|$. 

%$\textcolor{blue}{Jinia: Or, we can just write $|R_i| \leq A_i \log |G|$, where $A_i$ is dependent on $i$, but not on $|G|$.}

 \textit{Base case:} For the base case, we give a representation $(X_1,R_1)$ of $G_{c-1}$. %\textcolor{red}{Let $(X_1,R_1)$ be a short representation of $G_{c-1}$.} 
Let $[G_{c-1}: G_c]=r_c$ and $G_{c-1}= \langle g_{c}\rangle$. We take $X_{1}= \{g_{c}\}$. Since $G_{c-1}$ is cyclic, we have $g_{c}^{{r_c}}=1$. This relation forms the set $R_1$ and $||R_1|| \leq \log r_c < 2\log|G|$ (as $r_c \leq p^n=|G|$). Note that, to store $R_1$, storing the power of the generator $g_c$ is enough at this step.


\textit{Inductive case:} Let $(X_i,R_i)$ be a presentation for $G_{c-i}$, where $X_i=\{g_{c},g_{c-1},\dots,g_{c-i+1}\}$ and $||R_i||\leq 2i^3 \log |G|$. We now construct a presentation $(X_{i+1},R_{i+1})$ for $G_{c-i-1}$ such that $||R_{i+1}||\leq 2(i+1)^3\log |G|$. Elements of the set $R_i$ are represented as tuples of length $i$, encoding the exponents of the generators $g_c, g_{c-1}, \ldots, g_{c-i+1}$ \emph{in that order}. Accordingly, elements in $R_{i+1} \setminus R_i$ are tuples of length $i+1$, with the final component representing the exponent of the newly introduced generator $g_{c-i}$ in $X_{i+1}$.

    Since $G_{c-i-1}/G_{c-i}$ is cyclic, let $[G_{c-i-1}:G_{c-i}] =r_{c-i}$ and $G_{c-i-1}/G_{c-i}= \langle g_{c-i}G_{c-i} \rangle$. We set $X_{i+1}=X_i \cup \{g_{c-i}\}$. Now we define the relations of $R_{i+1}\setminus R_{i}$. %In order to define $R_{i+1}$, we need to represent the following properties: ($i$) $G_{c-i}$ is normal in $G_{c-i-1}$, ($ii$) The group $G_{c-i-1}/Z_{c-i} $ is cyclic.

    Since $G_{c-i}$ is normal in $G_{c-i-1}$, we have $g_{c-i}G_{c-i}=G_{c-i}g_{c-i}$. Therefore, we have the following set of relations:
    \begin{equation}
    \label{label 1}
        g_{c-i}g_{r}=w_{c-i,r}g_{c-i}, \ c \geq r \geq c-i+1\\
        \text{ for some $w_{c-i,r} \in G_{c-i}$}
    \end{equation}
  Note that here $w_{c-i,r}$ is an word of the form $g_{c}^{l_{c}}g_{c-1}^{l_{c-1}} \dots g_{c-i+1}^{l_{c-i+1}}$ where $0 \leq l_{u} \leq r_{u}$, for each $ c-i+1 \leq u \leq c$. Since $X_i$ is a generating set for $G_{c-i}$ and the order of $g_{u} \in X_i$ is $r_u$, any arbitrary element of $G_{c-i}$ can be represented by an word of the form $w_{c-i,r}$. %defining elements of $Z_i$.
    There are $i$ relations of the form \Cref{label 1}, and the length of the presentation for each relation is at most $i.n. \log p$.

    Now since $G_{c-i-1}/G_{c-i} \cong \ZZ_{p^{r_{c-i}}}$, we have the following relation:
    % \begin{equation}\label{label 2}
    %     g_{i+1,s}g_{i+1,t}g_{i+1,s}^{-1}g_{i+1,t}^{-1}=w'_{i} \text{ for all } 1 \leq s <t \leq k_{i+1}, \text{for some $w'_i\in Z_i$} 
    % \end{equation}
    \begin{equation} \label{label 3}
        g_{c-i}^{p^{r_{c-i}}}=w''_{c-i}, \text{for some $w''_i \in Z_i$}
    \end{equation}

    Here also $w''_{i}$ is a word defining element of $Z_i$. Note that the above relation has presentation of length at most $i. n. \log p$.

    We define $R_{i+1}$ as the union of the above relations \Cref{label 1}, \Cref{label 3} and $R_i$. %We claim \textcolor{red}{(???????)} that $(X_{i+1},R_{i+1})$ defines the group $Z_{i+1}$.\jinia{do we need to prove this?}
Since $\log (|G|)=n .  \log p$, we have the following: $||R_{i+1}||\leq ||R_i|| + (i+1). i. \log |G| \leq ||R_i|| + 2i^2\log (|G|)$, for $i \geq 1$. By the induction hypothesis, this implies $||R_{i+1}||\leq 2(i+1)^3\log(|G|)$.

By induction, the length of the presentation for $(X_c,R_c)$, which defines $G_0=G$, is at most $2c^3\log (|G|)$. Hence, $G$ has a presentation of length $O(\log |G|)$. This proves the first part of the lemma. %\hfill$\lhd$\end{proof}


We now prove the second part of the lemma.


Arvind and Toran \cite{1313808} showed that there is a polynomial time algorithm that takes a presentation $(X,R)$ of a solvable group $G$ which is obtained from a process described in the proof of the above lemma and outputs the Cayley table of a group $G'$ isomorphic to $G$. %With a similar approach (see \cite[Theorem 3.3]{arvind2011solvable} for details) to theirs, 
On all strings of length at most $O(\log N)$, we run the algorithm due to Arvind and Toran and generate the Cayley tables of all non-isomorphic groups of order $N$. The process of generating a presentation of length $\log(|G|)$ of each $G\in \mathcal{X}$ guarantees that this works.%\hfill $\lhd$
\end{proof}

A number $n\in \mathbb{N}$ is \textit{$d$-powerfree} if for each prime $p$, $p^d$ does not divide $n$. Note that a $p$-group of order $p^{d-1}$ has polycyclic length at most $(d-1)$. The next corollary follows from \Cref{summary} of nilpotent groups of bounded polycyclic length.

\medskip 

\begin{corollary}\label{bounded power}
Let $d$ be a fixed number. Let $ n \in \mathbb{N} $ be $ d$-powerfree . Then, there exists a polynomial time algorithm that determines whether an undirected graph is isomorphic to the power graph of a nilpotent group of order $n$.
\end{corollary}


\subsection{Nilpotent Groups of Squarefree Exponent}\label{sec: recognition nilpotent square free}

We begin with a lemma that follows from a result by \cite{pourgholi2015undirected}.

\medskip 

\begin{lemma}\label{exponet p} Let $p$ be a prime. A reduced directed graph $\DG$ is the reduced directed power graph of a finite $p$-group of order $p^n$ of exponent $p$ if and only if $\DG$ is colour-isomorphic to a directed star having $(p^n-1)/(p-1)$ vertices each with colour $p$, out-degree 1 and in-degree 0, and one vertex with colour $1$, out-degree 0 and in-degree $(p^n-1)/(p-1)$.
\end{lemma}

From the above lemma %(\Cref{exponet p}) 
and \Cref{pow(nil) reducible to dpow(p)}, the next result can be easily observed by considering the group class $\mathcal{X}=\{G \in \mathcal{G}_{PP} :\text{ exponent of $G$ is } p\}$.

\medskip 


\begin{theorem}\label{recognition squarefree exponent}
There is a polynomial time algorithm that takes a reduced directed graph $\Gamma$ as input, checks whether $\Gamma$ is isomorphic to the reduced directed power graph of a nilpotent group with squarefree exponent.
\end{theorem}

From the above theorem, one can easily observe that \Cref{summary} for nilpotent groups of squarefree exponent holds.

