We next show a quadratic lower bound for $(\conc+,\conc |)$-intersection testing with a reduction from Orthogonal Vectors (\ov). 

\begin{definition}[Orthogonal Vectors]
\label{def:ov}
    Given two sets $A, B \subseteq \{ 0,1 \}^d$ such that $|A| = M$, $ |B| = N$ determine whether there exist $\alpha \in A$ and $\beta \in B$ such that $\alpha$ and $\beta$ are orthogonal, namely, $\alpha \cdot \beta = \sum_{i=1}^{d} \alpha[i] \cdot \beta[i] = 0$.
\end{definition}
Our reduction relies on the following restricted case of the Unbalanced Orthogonal Vectors Hypothesis (\uovh), which is known to be implied by SETH~\cite{10.1109/FOCS.2015.15}.
\begin{conjecture*}[Unbalanced Orthogonal Vectors Hypothesis]
\label{def:ovh}
    For no $\epsilon > 0$ there is an algorithm for \ov, restricted to $M= \Theta(N)$ and $d  \le N^{o(1)}$, that runs in time $\mO(N^{2-\epsilon})$.
\end{conjecture*}

\noindent\textbf{Assumptions on the \ov instance.}~
We make the following assumptions on the \ov instance $A=\{\alpha_1,\ldots,\alpha_M\}, B=\{\beta_1,\ldots,\beta_N\}$ with $M=\Theta(N)$, which can all be ensured via trivial linear-time modifications to any general instance.

\begin{enumerate}
    \item\label{ov: M_odd_N_even} $M$ is an odd integer, $N$ is an even integer, and $M< N$; furthermore, 
    $N \equiv 0 (\textnormal{mod} ~4)$
    (can be obtained by adding multiple copies of some vectors of $A$ and/or $B$).
    \item\label{ov: odd} The length $d$ of the vectors is odd (can be obtained by adding a $0$ at the end of all vectors in case they have even length).
    \item\label{ov: A_zeros_B_ones} All vectors of set $A$ begin and end with a $1$; all vectors of $B$ begin and end with a $0$ (can be obtained by appropriately padding all the vectors at the beginning and the end).
    \item\label{ov: no_trivial_vectors} $A$ and $B$ do not contain the vectors $1^d$, $0^d$, $10^{d-2}1$, and $01^{d-2}0$ (can be checked with a linear-time scan).
    \item\label{ov: a1_aM_not_orthogonal} $\alpha_1\notperp \beta_j$ and $\alpha_M\notperp \beta_j$ for all $j\in [N]$.
    \item\label{ov: ai_bj_i_j_same_parity} If there are $i,j$ such that $\alpha_i \cdot \beta_j = 0$ then there are $i',j'$ such that $\alpha_{i'} \cdot \beta_{j'} = 0$ and $i'\equiv j' (\textnormal{mod}~2)$ (Assumption $3$ in~\cite{focs16} justifies why this can be assumed w.l.o.g.).
\end{enumerate}

\noindent\textbf{Gadgets.}~Our reduction uses the constant-size alphabet $\Sigma = \{x,y,\$\}$.
We begin by showing how to encode the vectors of $A$ with regexp gadgets of type $\conc +$. 
Coordinate gadgets encode the entries of a vector with the following rationale: even positions correspond to gadgets that only use the letter $x$, while the gadgets for the odd positions only use $y$. 
The size of a gadget is determined by the value of the corresponding entry in the vector, namely, size-3 gadgets of the form $ccc^+$ encode entries equal to 1, and size-1 gadgets of the form $c^+$ encode $0$ entries (where $c\in \{x,y\}$ according to the parity of the position of the vector). Formally, we thus define coordinate gadgets $C_A(v,k)$ for $v\in\{0,1\}$ and $k\in[d]$ as follows:

\[C_A(v,k)\coloneq
\begin{cases}
    yyy^+ & \textnormal{for} ~v=1 ~\textnormal{and}~ k\equiv 1 (\textnormal{mod} ~2)\\
    xxx^+ & \textnormal{for} ~v=1 ~\textnormal{and}~ k\equiv 0 (\textnormal{mod} ~2)\\
    y^+ & \textnormal{for} ~v=0 ~\textnormal{and}~ k\equiv 1 (\textnormal{mod} ~2)\\
    x^+ & \textnormal{for} ~v=0 ~\textnormal{and}~ k\equiv 0 (\textnormal{mod} ~2).
\end{cases}\]

Vector gadgets $a_i^\perp$ are then defined as the concatenation of the coordinate gadgets for $\alpha_i$: \[a_i^\perp \coloneq C_A(\alpha_i[1],1)C_A(\alpha_i[2],2)\cdots C_A(\alpha_i[d],d) .\]

Due to Assumptions~\ref{ov: odd} and~\ref{ov: A_zeros_B_ones}, all such vector gadgets begin with $yyy^+$ and end with $yyy^+$.  
To encode the vectors of $B$, we define coordinate gadgets which still associate letter $y$ with odd positions and letter $x$ with even positions, but this time size-$1$ gadgets encode the occurrences of $1$, and size-$3$ gadgets the occurrences of $0$; since $\cB$ is of type $\conc |$, the gadgets do not contain the operator $+$ and the vectors of $B$ are encoded with solid strings.  
Formally, we define the coordinate gadgets $C_B(v,k)$ for $v\in\{0,1\}$ and $k\in[d]$ as follows:
%
\[C_B(v,k)\coloneq
\begin{cases}
    y & \textnormal{for} ~v=1 ~\textnormal{and}~ k\equiv 1 (\textnormal{mod} ~2)\\
    x & \textnormal{for} ~v=1 ~\textnormal{and}~ k\equiv 0 (\textnormal{mod} ~2)\\
    yyy & \textnormal{for} ~v=0 ~\textnormal{and}~ k\equiv 1 (\textnormal{mod} ~2)\\
    xxx & \textnormal{for} ~v=0 ~\textnormal{and}~ k\equiv 0 (\textnormal{mod} ~2).
\end{cases}\]

Vector gadgets $b_j$ are then defined depending on the parity of $j$ (given a fixed but arbitrary ordering of the vectors of $B$):
%
\[b_j\coloneq 
\begin{cases}
    C_B(\beta_j[1],1)C_B(\beta_j[2],2)\cdots C_B(\beta_j[d],d) &\textnormal{if} ~j \equiv 1 (\textnormal{mod} ~2)\\
    yyyC_B(\beta_j[1],1)C_B(\beta_j[2],2)\cdots C_B(\beta_j[d],d)yyy &\textnormal{if} ~j \equiv 0 (\textnormal{mod} ~2).
\end{cases}\]

Due to Assumptions~\ref{ov: odd} and~\ref{ov: A_zeros_B_ones}, all gadgets $b_j$ with an odd $j$ start and end with $y^3$, and those with an even $j$ start and end with $y^6$. 
%
We also define another two gadgets of type $\conc +$
%
\begin{equation}\label{eq: a_zero_a_even}
a_0^\perp\coloneq (y^+x^+)^{\lfloor\frac{d}{2}\rfloor}y^+,
~~~~~~~~
a_{even}^\perp\coloneq y^6x^+(y^+x^+)^{\lfloor\frac{d}{2}\rfloor-1}y^6
\end{equation}
%
and three additional gadgets of type $\conc |$ 
%
\begin{equation}\label{eq: b_zero_dollar}
b_0\coloneq \left(y^3\left[x|
y\right]^3\right)^{\lfloor\frac{d}{2}\rfloor}y^3; ~~~~~ b_{even}\coloneq y^6x\left(yx\right)^{\lfloor\frac{d}{2}\rfloor-1}y^6; ~~~~~ b_{odd}\coloneq y^3x\left(yx\right)^{\lfloor\frac{d}{2}\rfloor-1}y^3.
\end{equation}
%
Finally, we define $b_0^{(\$)} \coloneq b_0 \left[y|\$\right]$, $ b_{even}^{(\$)} \coloneq b_{even}
\left[y|\$\right]$, and $b_{odd}^{(\$)} \coloneq b_{odd} \left[y|\$\right]$. 

\begin{example}\label{ex:gadgets}
    Let $d=5$, consider the vectors $\alpha_1=10011$, $\alpha_2=11001$, $\beta_1=00010$, $\beta_2=01010$, and denote by $x^{3+}$ and $y^{3+}$ the expressions $xxx^+$ and $yyy^+$, respectively. 
    The associated gadgets are $a_1^\perp=y^{3+}x^{+}y^+x^{3+}y^{3+}$; $a_2^\perp=y^{3+}x^{3+}y^{+}x^{+}y^{3+}$; $b_1=y^3x^3y^3xy^3$; $b_2=y^6xy^3xy^6$. 
    Note that $a_2^\perp\sqcap b_1 \neq \emptyset$, but $a_1^\perp\sqcap b_1= \emptyset$: indeed, $\beta_1$ is orthogonal to $\alpha_2$, but not to $\alpha_1$.
    Furthermore, $a_0^\perp=y^+x^+y^+x^+y^+$; $a_{even}^\perp=y^6x^+y^+x^+y^6$; $b_0=y^3\left[x|y\right]^3 y^3 \left[x|y\right]^3 y^3$; $b_0^{(\$)}=y^3\left[x|y\right]^3 y^3 \left[x|y\right]^3 y^3 \left[y|\$\right]$; $b_{even}^{(\$)}=y^6xyxy^6\left[y|\$\right]$; and $b_{odd}^{(\$)}=y^3xyxy^3\left[y|\$\right]$.
\end{example}

\Cref{lem: orthogonal_gadgets} is straightforward from the definitions of the vector gadgets $a_i^\perp$ and $b_j$.

\begin{lemma}\label{lem: orthogonal_gadgets}
    For any $i\in[M]$ and $j\in [N]$, $a_i^\perp \sqcap b_j\ne \emptyset$ (thus $a_i^\perp$ aligns with $b_j$) if and only if $\alpha_i\perp \beta_j$.
\end{lemma}

Since gadgets $b_j$ are strings, we have $a_i^\perp \sqcap b_j\ne \emptyset$ if and only if $b_j \in \cL(a_i^\perp)$, 
thus $\cL(a_i^\perp)$ contains the string $b_j$ for each vector $\beta_j$ orthogonal to $\alpha_i$.
We remark that, morally, $a_0^\perp$ and $b_0$ encode the vector $0^d$, while $b_{odd}$ and $b_{even}$ encode the vector $0 1^{d-2}0$. 
This is consistent with the fact that (i) $b_0 \in \cL(a_i^\perp)$ and $b_j \in \cL(a_0^\perp)$ for all $i\in [M],j\in [N]$ (as $0^d$ is orthogonal to any vector), and (ii) $a_i^\perp$ does not align with $b_{odd}$ or $b_{even}$ 
(as by Assumption~\ref{ov: no_trivial_vectors}, $A$ does not contain the vector $10^{d-2}1$, and thus $0 1^{d-2}0 \notperp \alpha_i$ for all $i\in[M]$). Furthermore, since $\cL(b_0)$ contains a run of the letter $y$, we can align $a_0^\perp$ with $b_0^k$ for any $k\ge1$.
We summarise these properties, which are straightforward to verify from the gadget definitions, in \Cref{rk: gadgets_matches}.

\begin{remark}\label{rk: gadgets_matches}
    The following relations among the gadgets hold:
    \begin{enumerate}
        \item \label{a_zero_b_i}  $a_0^\perp \sqcap (b_0)^k b_j\neq\emptyset$ for all $j\in[N]$ for all $k\ge 0$.
        \item\label{b_zero_a_i} $a_i^\perp \sqcap (b_0)^k\neq\emptyset$ for all $i\in[0,M]$ for all $k\ge 1$.   
         \item\label{b_0-b_j_a_i_ortho} $a_i^\perp \sqcap (b_0)^kb_j\neq\emptyset$ if and only if $\alpha_i\perp\beta_j$  for all $k\ge 0$.
        \item\label{b_even_odd_not_a_i} 
        $a_0^\perp \sqcap (b_0)^k b_{even} (b_0)^h\neq\emptyset$ and $a_0^\perp \sqcap (b_0)^k b_{odd} (b_0)^h\neq\emptyset$, but
        $a_i^\perp \sqcap (b_0)^k b_{even} (b_0)^h=\emptyset$ and $a_i^\perp \sqcap (b_0)^k b_{odd} (b_0)^h=\emptyset$ for all $i\in[M]$, for all $h,k\ge0$.
        \item\label{a_even_b_even_b_odd} $a_{even}^\perp \sqcap b_{even}\neq\emptyset$ but  $a_{even}^\perp \sqcap b_0=\emptyset$ and $a_{even}^\perp \sqcap b_{odd}=\emptyset$.

        \item\label{a_even_b_p_even} $a_{even}^\perp \sqcap b_p \ne \emptyset$ if and only if $p$ is even.

        \item \label{a_0_cannot_eat_b_even_b_odd} Since there are exactly $d-1$ alternation of $y$ and $x$ in $a_i^\perp$ for $i\in [0,M]$, $a_i^\perp$ can align with at most one string $b_j$ (including $b_{even}$ or $b_{odd}$ if $i=0$); for instance, $a_0^\perp \sqcap b_{even} b_0 b_{odd}=\emptyset$.
    \end{enumerate}
\end{remark}
For all cases of \Cref{rk: gadgets_matches}, given a regexp $\cA$ of type $\conc +$ and $\cB$ of type $\conc |$, the following are equivalent: $\cA \sqcap \cB \ne \emptyset$, $\cA \$\sqcap \cB\$ \ne \emptyset$, $\$ \cA \sqcap \$ \cB \ne \emptyset$, $\$ \cA\$\sqcap \$ \cB \$\ne \emptyset$.
This holds even if the symbol $\$$ is replaced by $[y|\$]$ in the regexp of type $\conc |$, or $b_0$ is replaced by $b_0^{(\$)}$.
\medskip

\noindent\textbf{Full reduction.}~
We concatenate the gadgets encoding \ov sets $A$ and $B$ to construct two regexps $\cA$, $\cB$ of types $\conc +$ and $\conc |$, respectively. 
Each regexp is partitioned into three fragments: $\cA=\cA_{pre}\cA^\perp\cA_{suf}$ and $\cB=\cB_{pre}\cB^\perp\cB_{suf}$.
The $pre$ and $suf$ fragments are designed to force the alignment of a fragment of  $\cA^\perp$ with a fragment of $\cB^\perp$ whenever we have a global alignment of $\cA$ and $\cB$, which in turn will imply that a pair of orthogonal vectors exists.

$\cA^\perp$ and $\cB^\perp$ are the central fragments of $\cA$ and $\cB$, respectively. They contain the gadgets $a_i^\perp$ and $b_j$, which do not appear anywhere else in $\cA$ and $\cB$, and are defined as follows.
\begin{align}
    \label{eq: calA_perp}
   \cA^\perp &\coloneq a_1^\perp\$ a_0^\perp\$ a_2^\perp\$ \cdots \$a_{M-1}^\perp\$a_0^\perp\$ a_M^\perp
   \\[2pt] \label{eq: calB_perp}
   \cB^\perp &\coloneq b_0^{(\$)} b_1 \$ b_0^{(\$)} b_2 \$ \cdots \$b_0^{(\$)} b_{N-1} \$b_0^{(\$)} b_N \$ .
\end{align}
%
\vspace{-12pt}
\begin{remark}\label{rk: number_of_dollars_cAperp_cBperp}
    All strings in the language of $\cA^\perp$ contain $2M-2$ occurrences of $\$$; all strings in the language of $\cB^\perp$ contain at least $N$ and at most $2N$ occurrences of $\$$.
\end{remark}

The two regular expressions $\cA$ and $\cB$ are then defined as
%

\begin{align}
    \label{eq: calA}
    \cA &\coloneq 
    \underbracket{\left(a_0^\perp\right)^{2M+N}\left(a_0^\perp\$\right)^{N-1} a_{even}^\perp\$}_{\cA_{pre}}  \cA^\perp \underbracket{\$a_{even}^\perp
    \left(\$a_0^\perp\right)^{N-1}\left(a_0^\perp\right)^{2M+N}}_{\cA_{suf}}
    \\[5 pt]
    \label{eq: calB}
    \cB &\coloneq 
    \underbracket{\left(b_0\right)^{2M+N}\left(b_0^{(\$)}b_{odd}^{(\$)}b_0^{(\$)}b_{even}^{(\$)}\right)^{\frac{2M+N-2}{4}}}_{\cB_{pre}} 
    \cB^\perp 
    \underbracket{\left(b_0^{(\$)}b_{odd}^{(\$)}b_0^{(\$)}b_{even}^{(\$)} \right)^{\frac{2M+N-2}{4}}\left(b_0\right)^{2M+N}}_{\cB_{suf}}.
\end{align}
%
%
\vspace{-12pt}
\begin{remark}\label{rk: A_B_fixed_dollars}
    All strings in the language of $\cA$ have exactly $2M+2N-2$ occurrences of \$, and
    all strings in the language of $\cB$ have at least $N$ and at most $4N+4M-4$ 
    occurrences of $\$$.
\end{remark}
Recall that by Assumption~\ref{ov: M_odd_N_even}, $N\equiv0 (\textnormal{mod}~4)$ and $2M \equiv 2 (\textnormal{mod}~4)$ thus $2M+N-2 \equiv 0 (\textnormal{mod}~4)$. 
Suppose that the intersection of the languages of $\cA$ and $\cB$ is not empty and consider a string $U\in \cA \sqcap \cB$. By Remark~\ref{rk: A_B_fixed_dollars}, $U$ has exactly $2M+2N-2$ occurrences of \$.
Lemma~\ref{lem: calA_perp_intersects_calB_perp} shows that the fragment $U[s_{\cA}\dd e_{\cA}]$ aligned with $\$\cA^\perp\$$ and the fragment $U[s_{\cB}\dd e_{\cB}]$ aligned with $\cB^\perp$ must overlap, and thus a fragment of $\cA^\perp$ aligns with a fragment of $\cB^\perp$: see also \Cref{fig:intersection_intervals}.

\begin{figure}[!ht]
    \centering
    \includegraphics[width=\textwidth]{intersection_intervals_test2.pdf}
    \caption{Visual representation of \Cref{lem: calA_perp_intersects_calB_perp}. The blue lines are vertical to emphasise that the alignment of $U$ with $\cB$ is the identity function.}  \label{fig:intersection_intervals}
\end{figure}

\begin{lemma}\label{lem: calA_perp_intersects_calB_perp}
    For any $U\in \cA \sqcap \cB$, let $U[s_{\cA}\dd e_{\cA}]$ and $U[s_{\cB}\dd e_{\cB}]$ be the fragments aligned with $\$\cA^\perp\$$ and $\cB^\perp$, respectively.
    Then  $[s_{\cA},e_{\cA}] \cap [s_{\cB
},e_{\cB}] \neq \emptyset$.  
\end{lemma}

\begin{proof}
By the definition of $\cA$, $s_\cA$ and $e_\cA$ are the positions of the $N$-th and the $(N+2M-1)$-th occurrence of \$  in $U$, respectively.
Thus the only way $[s_{\cA},e_{\cA}] \cap [s_{\cB
},e_{\cB}]$ could be empty is if the first $N+2M-1$ occurrences of \$ in $U$ are all all aligned within $\cB_{pre}$ or symmetrically, if the last $N+2M-1$ occurrences are all aligned within $\cB_{suf}$.
A simple counting argument shows that this is impossible. 
In fact, by the definition of $\cB$, at most $N+2M-2$ occurrences of \$ can be aligned within $\cB_{pre}$; and symmetrically, within $\cB_{suf}$. 
\end{proof}

\begin{lemma}
    If $\cA \sqcap\cB \ne \emptyset$ then there exists a pair of orthogonal vectors.
\end{lemma}
    \begin{figure}[t]
        \centering
        \includegraphics{interesection_ortho_second_case_zoom.pdf}
        \caption{Example of the alignment of $a_{even}^\perp \$a_{1}^\perp\$$ with $b_{p}\$ b_{0}^{(\$)}$, for an even $p$. Here $d=5$, $\alpha_1= 10011$, $\beta_p=00010$, and $\beta_{p+1}=01010$. Note that, coherently with Assumption~\ref{ov: a1_aM_not_orthogonal}, $a_1^\perp$ does not align with $b_p$ nor with $b_{p+1}$.}
        \label{fig:a_even_sqcap_b_p_second_case}
    \end{figure}

\begin{proof}

Since $\cA \sqcap\cB\ne \emptyset$, $\cA$ can be aligned with $\cB$. The general idea is to prove that for each possible alignment of $\cA$ and $\cB$ there exist $i\in[M],j\in[N]$ such that $a_i^\perp$ is aligned with $b_0^{(\$)}b_j$ or $b_j$, which by \Cref{rk: gadgets_matches}.\ref{b_0-b_j_a_i_ortho} and \Cref{lem: orthogonal_gadgets} implies that $\alpha_i \perp \beta_j$. 
Let the intervals $[s_{\cA},e_{\cA}]$ and $[s_{\cB},e_{\cB}]$ be defined as in Lemma~\ref{lem: calA_perp_intersects_calB_perp}.
Since the intersection of these two intervals is not empty, we study the following three cases.

\begin{description}
    \item[Case $s_{\cB} \le s_\cA < e_\cA \le e_{\cB}$.]
    Let us focus on how the extremities of $\$\cA^\perp\$$, that is, $\$ a_1^\perp $ and $a_M^\perp\$$, can be aligned inside $\cB^\perp$. 
    In principle, the first \$ could be either aligned with an explicit occurrence of \$ in $\cB^\perp$ or with an ``optional'' occurrence in a set $[y|\$]$.
    The second case would imply that $\$ a_1^\perp \$$ aligns with $[y|\$] b_j\$$ for some $j\in [N]$, which is a contradiction due to Assumption~\ref{ov: a1_aM_not_orthogonal}.
    Therefore, it must be aligned with an explicit occurrence of \$ in $\cB^\perp$, which implies, in particular, that the whole $a_{even}^\perp\$a_1^\perp$ must be aligned within $\cB^\perp$.
    Again by Assumption~\ref{ov: a1_aM_not_orthogonal}, $\$a_1^\perp\$$ cannot align with $\$b_0^{(\$)}b_j\$$ for any $j\in[N]$;
     furthermore, by \Cref{rk: gadgets_matches}.\ref{a_even_b_p_even}, $a_{even}^\perp\$$ aligns with $ b_p \$$ if and only if $p$ is even. 
     The whole reasoning implies that  $a_{even}^\perp \$ a_1^\perp\$ $ must be aligned with $b_p\$b_0^{(\$)}$ for some even $p$ (see \Cref{fig:a_even_sqcap_b_p_second_case}).
    A similar reasoning proves that $a_M^\perp \$a_{even}^\perp\$$ must be aligned with $b_0^{(\$)}b_q\$$ for some even $q$.

    Let us study what happens in the middle part of $\cA^\perp$.
    Fixed any $i\in [2,M-1]$,  $\$a_i^\perp \$$ can only align with the following types of fragments of $\cB^\perp$: $\$ b_0^{(\$)}$ or $\$b_0^{(\$)}b_j\$$ or $[y|\$]b_j \$$. By \Cref{lem: orthogonal_gadgets} and \Cref{rk: gadgets_matches}.\ref{b_0-b_j_a_i_ortho}, the last two cases can occur if and only if $\alpha_i \perp \beta_j$.
    In contrast, $\$ a_0^\perp\$$ can align with  $\$b_0^{(\$)}$ or $\$ b_0^{(\$)}b_j\$$ or $[y|\$]b_j \$$ without any implications on vector orthogonality.
    Now since $a_{even}^\perp \$ a_1^\perp\$$ is aligned with $b_p\$b_0^{(\$)}$ for some even $p$,  $a_{even}^\perp \$ a_1^\perp\$ a_0^\perp\$$ must be aligned with $b_p\$b_0^{(\$)}b_{p+1}\$$.
    Suppose for a contradiction that $\alpha_i \not \perp \beta_{p+i}$ for all $i\in [M]$.
    Then $\alpha_2 \not \perp \beta_{p+2}$ implies that $a_{even}^\perp \$ a_1^\perp\$ a_0^\perp\$ a_2^\perp\$a_0^\perp\$$ must be aligned with $b_p\$b_0^{(\$)}b_{p+1}\$b_0^{(\$)}b_{p+2}\$$, and in particular, $b_0^{(\$)}$ is aligned with $a_2^\perp\$$ and $b_{p+2}\$$ is aligned with $a_0^\perp\$$.
    Iterating this process, we get that $a_{even}^\perp \$ a_1^\perp\$ a_0^\perp\$ a_2^\perp\$a_0^\perp\$\cdots \$ a_{M-1}^\perp\$a_0^\perp\$a_{M}^\perp \$$ is aligned with $b_p\$b_0^{(\$)}b_{p+1}\$b_0^{(\$)}b_{p+2}\$\cdots \$b_0^{(\$)}b_{p+M-1}\$b_0^{(\$)}$. 
    This leads to a contradiction because it would force $a_{even}^\perp\$$ to align with $b_{p+M}\$$, which is impossible since $p+M$ is odd by Assumption~\ref{ov: M_odd_N_even}. 
    We conclude that a pair of orthogonal vectors exists.
    \begin{center}
        \includegraphics{interesection_ortho_second_case.pdf}
    \end{center}
     \item[Case $s_\cA < s_{\cB}$.]
     Since $\cB[s_{\cB}] = y$ and $\cA[e_{\cA}] = \$$, we have $s_{\cB} \ne e_\cA$.
    Since $s_\cA < s_{\cB}$, the fragment $ a_{even}^\perp \$ a_1^\perp \$$ must be aligned with some fragment of $\cB$ starting to the left of $\cB^\perp$, i.e. in $\cB_{pre}$. 
    In particular, $a_{even}^\perp \$ a_1^\perp \$ $ can only align with some occurrence of $b_{even}^{(\$)}b_0^{(\$)}$ (in the case where $s_\cA=s_{\cB}-1$, it is aligned with the last occurrence of $b_{even}^{(\$)}$ in $\cB_{pre}$ and the first occurrence of $b_0^{(\$)}$ within $\cB^\perp$). Indeed, by Remark~\ref{rk: gadgets_matches}.\ref{a_even_b_even_b_odd}, $a^{\perp}_{even} \$ $ can only align with $b_{even}\$ $, and by Remark~\ref{rk: gadgets_matches}.\ref{b_even_odd_not_a_i}, $a_1^\perp$ does not align with $b_0^{(\$)}b_{odd}$: see \Cref{fig:a_even_sqcap_b_even}. 
    %
    \begin{figure}[t]
        \centering
        \includegraphics{interesection_ortho_third_case_zoom.pdf}
        \caption{Example of the alignment $a_{even}^\perp \$a_{1}^\perp\$$ and $b_{even}^{(\$)}b_{0}^{(\$)}$ with $d=5$ and $\alpha_1= 10011$.}
        \label{fig:a_even_sqcap_b_even}
    \end{figure}
    %
    In principle, $a_{even}^\perp \$ a_1^\perp \$a_0^\perp\$$ could be aligned with  $b_{even}^{(\$)}b_0^{(\$)} b_{odd}^{(\$)}b_0^{(\$)}$, and in particular, the last two positions of $b_{odd}^{(\$)}$ and the whole $b_0^{(\$)}$ (except its last position) could be aligned with the last position of $a_0^\perp$ (which corresponds to $y^+$: see Equations~\ref{eq: a_zero_a_even}, \ref{eq: b_zero_dollar}). 
    However, this would imply that $a_2^\perp\$$ would have to align with $b_{even}^{(\$)}$, which is not possible by Remark~\ref{rk: gadgets_matches}.\ref{b_even_odd_not_a_i}.
    By Remark~\ref{rk: gadgets_matches}.\ref{a_0_cannot_eat_b_even_b_odd}, $a_{even}^\perp \$ a_1^\perp \$a_0^\perp\$$ cannot be aligned with $b_{even}^{(\$)}b_0^{(\$)} b_{odd}^{(\$)}b_0^{(\$)}b_{even}^{(\$)}$ or any longer fragment;   
    therefore $a_{even}^\perp \$ a_1^\perp \$a_0^\perp\$$ must be aligned with $b_{even}^{(\$)}b_0^{(\$)} b_{odd}^{(\$)}$ so that $a_2^\perp \$$ can be aligned with $b_0^{(\$)}$.
    Proceeding with the alignment and iterating this reasoning, we get that for any odd $i$ such that $a_i^\perp$ is aligned within $\cB_{pre}$, $a_i^\perp \$a_0^\perp \$ a_{i+1}^\perp \$a_0^\perp \$$ must be aligned with $b_0^{(\$)} b_{odd}^{(\$)} b_0^{(\$)} b_{even}^{(\$)}$.

    Therefore, for any even $p$,
    $a_{even}^\perp \$ a_1^\perp \$a_0^\perp\$\cdots \$a_p^\perp\$a_0^\perp \$$ must be aligned with either (i) $b_{even}^{(\$)}(b_0^{(\$)} b_{odd}^{(\$)} b_0^{(\$)} b_{even}^{(\$)})^{\frac{p}{2}}$ or (ii) $b_{even}^{(\$)}(b_0^{(\$)} b_{odd}^{(\$)} b_0^{(\$)} b_{even}^{(\$)})^{\frac{p}{2}}b_0^{(\$)}$, implying that the smallest $i$ such that $a_i^\perp$ is aligned with a fragment of $\cB^\perp$ is always odd.
    Case (ii) occurs if and only if the last $a_0^\perp\$$ in $a_{even}^\perp \$ a_1^\perp \$a_0^\perp\$\cdots \$a_p^\perp\$a_0^\perp \$$ aligns with $b_{even}^{(\$)}b_0^{(\$)}$. This forces $a_{p+1}^\perp\$$ to align with $b_1\$$, which implies that $\alpha_{p+1} \perp \beta_1$ by \Cref{lem: orthogonal_gadgets}. So, suppose we are in Case (i).
    We now study the alignment of $ a_{p+1}^\perp \$a_0^\perp\$\cdots \$a_0^\perp\$a_M^\perp \$ $ (that is the remaining part of $\cA^\perp$). 
    Suppose for the sake of contradiction that $\alpha_{p+i} \not \perp \beta_{i}$ for all $i\in [1,M-p]$.
    Since $\alpha_{p+1} \not \perp \beta_{1}$, then $ a_{p+1}^\perp \$$ can only be aligned with $b_0^{(\$)}$ because, by \Cref{rk: gadgets_matches}.\ref{b_0-b_j_a_i_ortho}, if $ a_{p+1}^\perp \$ \sqcap b_0^{(\$)}b_1\$\neq\emptyset$ (thus $a_{p+1}^\perp \sqcap b_0 b_1\neq\emptyset$) 
    then $\alpha_{p+1}\perp \beta_1$.
    Therefore, under the assumption that $\alpha_{p+i} \not \perp \beta_{i}$ for each $i\in [1,M-p]$, the only possibility, by \Cref{rk: gadgets_matches}.\ref{a_zero_b_i} and \ref{rk: gadgets_matches}.\ref{b_zero_a_i}, would be to align $ a_{p+1}^\perp \$a_0^\perp\$\cdots \$a_0^\perp\$a_M^\perp \$$ with $ b_0^{(\$)}b_1\$ \cdots b_{M-p-1}\$b_0^{(\$)}$.
    This would force the alignment of $a_{even}^\perp\$$ with $b_{M-p}\$$, which is not possible because $M-p$ is odd by Assumption~\ref{ov: M_odd_N_even}. 
    \begin{center}
        \includegraphics{interesection_ortho_third_case.pdf}
    \end{center}
    \item[Case $s_{\cB} \le s_\cA$.] The case $e_{\cA} \le e_{\cB}$ has already been considered. If $e_{\cB} < e_{\cA}$, we can proceed  symmetrically to the case $s_{\cA} < s_{\cB}$.
    We briefly sketch the proof. 
    Suppose $\alpha_i \not\perp \beta_N$, for all $i$.
    Then, $b_0^{(\$)}b_N\$$ must align with $a_{q}^\perp\$a_0^\perp\$$, for some $q$. We first prove the fragment $a_{q+1}^\perp\$a_0^\perp\$ a_{q+2}^\perp\$ \cdots\$a_0^\perp\$ a_{M}^\perp\$a_{even}^\perp$ must align with a fragment of $\cB_{suf}$ and by Remarks~\ref{rk: gadgets_matches}.\ref{b_zero_a_i}, \ref{rk: gadgets_matches}.\ref{b_even_odd_not_a_i} and \ref{rk: gadgets_matches}.\ref{a_even_b_even_b_odd}, $q$ must be odd.
    Secondly, assuming that $\alpha_{i}\not \perp \beta_{N-q+i}$ for $i\in [q]$, we get that $a_1^\perp\$a_0^\perp\$ a_{2}^\perp\$ \cdots\$a_0^\perp\$ a_{q}^\perp\$a_0^\perp \$ $ aligns with $b_0^{(\$)}b_{N-q+1}\$\cdots\$ b_0^{(\$)}b_{N}\$ $. This forces the alignment of $a_{even}^\perp\$$ with $b_{N-q}\$$, which is a contradiction since $N-q$ is odd.\qedhere
\end{description}
\end{proof}

\begin{lemma}
