        \item $(a_0^\perp)^2 \sqcap b_0^{(\$)}b_{odd}^{(\$)}b_0^{(\$)}b_{even}^{(\$)}\ne \emptyset$
        \item $(a_0^\perp\$)^4\sqcap b_0^{(\$)}b_{odd}^{(\$)}b_0^{(\$)}b_{even}^{(\$)}\ne \emptyset$ and $(a_0^\perp\$)^3a_{even}^\perp\$\sqcap b_0^{(\$)}b_{odd}^{(\$)}b_0^{(\$)}b_{even}^{(\$)}\ne \emptyset$
