    % 
    \begin{proof}
     We aim to demonstrate that the objective  
    \[
    \mathbb{Q}'(X) = \sum_{j=1}^M \mathbb{Q}_j(X) = \sum_{j=1}^M \frac{C_D(\mathbf{q}_j) + 1+ \sum_{t_i\in X} t_i.\beta\times w_{ij}}{C_D(\mathbf{q}_j) + 1 }
    \]
    % 由于目标公式线性的特性，我们可以把内层对$t_i.\beta$的求和挪到外层，对$t_i.\beta$进行重新排列，并针对集合 $A\setminus B$,$B\setminus A$, $A\cap B$ 进行组合，最终证明等式成立。
    Due to the linear nature of the target $\mathbb{Q}'(X)$, we can move the summation over $t_i.\beta$ from the inner layer to the outer layer, rearrange $t_i.\beta$, and combine elements based on the sets $(A\setminus B)$, $(B\setminus A)$, and $(A\cap B)$. Then, we prove that $\mathbb{Q}'(X)$ 
    satisfies the modular property. 

We can rewrite \( \mathbb{Q}'(X) \) as:
\[
\mathbb{Q}'(X) = M + \sum_{j=1}^M \frac{\sum_{t_i\in X} t_i.\beta\times w_{ij}}{C_D(\mathbf{q}_j) + 1}.
\]
Let us define \( H_i = \sum_{j=1}^M \frac{w_{ij}}{C_D(\mathbf{q}_j) + 1} \). Consequently, we have
\[
\mathbb{Q}'(X) =  M+\sum_{i=1}^N t_i.\beta\times H_i.
\]
Considering the left-hand side, we obtain:
\[
\mathbb{Q}'(A \cup B) + \mathbb{Q}'(A \cap B) = \sum_{t_k \in A \cup B} t_k.\beta\times H_k + \sum_{t_k \in A \cap B} t_k.\beta\times H_k.
\]
This can be expanded as:
\[
\sum_{t_k \in A \setminus B} t_k.\beta\times H_k + 2 \sum_{t_k \in A \cap B} t_k.\beta\times H_k + \sum_{t_k \in B \setminus A} t_k.\beta\times H_k.
\]
On the other hand, the right-hand side is:
\[
\mathbb{Q}'(A) + \mathbb{Q}'(B) = \sum_{t_k \in A} t_k.\beta\times H_k + \sum_{t_k \in B} t_k.\beta\times H_k.
\]
This also expands to:
\[
\sum_{t_k \in A \setminus B} t_k.\beta\times H_k + 2 \sum_{t_k \in A \cap B} t_k.\beta\times H_k + \sum_{t_k \in B \setminus A} t_k.\beta\times H_k.
\]
Therefore, we have
\[
\mathbb{Q}'(A) + \mathbb{Q}'(B) = \mathbb{Q}'(A \cup B) + \mathbb{Q}'(A \cap B).
\]
This equality demonstrates the modular property.
\end{proof}

